#!/usr/bin/env node
/* codex-review — 이종 벤더(GPT/Codex) 적대 검수 러너
 *
 * 왜 이종인가: 같은 벤더 에이전트끼리는 **블라인드스팟이 상관된다**(2026-07-10 판정).
 *   내가 내 코드를 리뷰하면 내가 못 보는 것은 리뷰에서도 안 보인다. 2026-08-05 실측이 이걸
 *   그대로 보여줬다 — 내가 **변이 테스트로 내 회귀의 구멍을 찾아 고친** 커밋(fff91f0)에서
 *   Codex 가 테스트 격리 결함을 하나 더 찾아냈다(tests/배포판점검.test.js(⚠삭제됨 e75fc7fc 2026-08-19 — 지금 없다) PATH 격리).
 *
 * ■ 이 도구가 지키는 불변식 하나
 *   「라이브로 나가는 바이트가 검수를 받았는가」 — 커밋 메시지도 절차 기억도 아니라 **내용 지문**으로 건다.
 *   지문은 `배포판점검.지문()` 을 그대로 쓴다(새로 정의하지 않는다 — 같은 판정을 두 곳에 적으면
 *   갈라지고 갈라지는 방향은 언제나 「통과」다). 파일이 한 바이트라도 바뀌면 지문이 바뀌어
 *   옛 검수 기록이 자동으로 무효가 된다.
 *
 * ■ 통과와 미실행을 절대 같은 모양으로 두지 않는다
 *   종료 코드 0=차단급 0건 · 1=차단급 지적 있음 · 2=**확인 불가**(codex 없음·로그인 만료·타임아웃·
 *   스키마 파싱 실패). 2 를 0 으로 접으면 「안 돌았는데 초록」이 되는데, 그게 이 저장소가
 *   가장 여러 번 데인 형태다. 그래서 파싱 실패에 산문 폴백을 두지 않았다 — 폴백은 조용히
 *   「지적 0건」을 만들어내고, 그건 거짓 초록이다.
 *
 * ■ 처분 이력이 노이즈를 회차마다 줄인다 — 단 **세 처분이 다르게 논다**(2026-08-17)
 *   내가 검토한 지적은 `검수기각.jsonl` 에 사유·`처분`과 함께 남는다(`처분레버들`). 그중
 *   **`기각`만** 다음 런에서 걸러진다 — 채택수리(옳았고 고쳤다)·범위밖은 남되 안 걸러진다.
 *   안 그러면 같은 지적이 매번 오고 내가 매번 다시 판단한다 — 그럼 검수는 상시 세금이 되지
 *   감가하는 비용이 안 된다.
 *   ⚠ 「프롬프트에 먹인다」가 아니다 — 1단계 검수는 `codex exec review` 라 커스텀 프롬프트를
 *     **원리상 못 준다**(아래 ⛔막다른 길). 걸러내는 자리는 결과를 받은 **뒤**다(`걸러지는키들`).
 *     프롬프트를 먹일 수 있는 것은 `exec` 를 쓰는 제안·기능체크 단계뿐이다.
 *
 * 사용 (유호님 설계 3단 파이프라인 · 2026-08-05):
 *   ① node tools/codex-review.js --제안           # 설계 선파악 — 기능지도 + 업그레이드 제안(sol/max)
 *   ② node tools/codex-review.js --제안판정 <키> --채택 [--사유 ".."]   # 클로드가 제안을 판정
 *      node tools/codex-review.js --제안판정 <키> --기각 --사유 "왜"    # 기각은 다음 회차에 안 올라온다
 *   ③ node tools/codex-review.js                  # 최종 검수 = 버그 사냥 + 기능 전수 체크
 *
 *   대상 지정: (기본) 미커밋 있으면 그것, 없으면 HEAD / --commit <sha> / --base <브랜치> / --uncommitted
 *   픽 전환:   --검수 sol    (기본·효력·회차의 정본 = tools/모델정책.js — 여기 값을 «적지 않는다».
 *                             적어 두면 갈린다: 이 줄이 08-15 판 「luna/high」를 08-31 까지 말했고
 *                             그 사이 편성이 «세 번» 바뀌었다. 지금 값은 `node tools/모델정책.js --표`)
 *   빠르게:    --버그만      (기능 전수 체크 생략 — 유호님 「빠르게」 모드)
 *              --회차 2      (그날만 넓게 — 기본은 1회다 · 유호 확정 08-31)
 *   지적 기각: --기각 <키> --사유 "왜 기각했는지"
 *   게이트 조회: --확인      (검수 안 돌림·부작용 0)
 */
'use strict';
const { execFileSync, spawn } = require('child_process');
const crypto = require('crypto');
const fs = require('fs');
const os = require('os');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const 점검 = require(path.join(ROOT, 'tools', '배포판점검.js'));
const 프로젝트 = require(path.join(ROOT, '.claude', 'hooks', 'lib', 'clasp-project.js'));
const 런 = require(path.join(ROOT, 'tools', 'lib', '검수런.js'));
// 세션 id 는 한 통로에서만 뽑는다 — 축이 셋이라 직독하면 갈라진다(F634).
const 보드id = require('../.claude/hooks/lib/board-id.js');

/* ── 검수 «대상 저장소» — 도구의 «집»과 «재는 것»을 가른다 (2026-08-31 · 형제 저장소를 못 보던 자리)
 *
 * 병: `ROOT` 한 값이 **두 가지**를 뜻했다 —
 *   ① 이 도구의 집 = 스키마·판단 정본(철학·방향)·장부·Apps Script 배포층이 사는 곳(언제나 이 저장소)
 *   ② **지금 재는 저장소** = git 이 도는 곳 · codex 가 읽는 곳
 * 둘이 같은 값이라 형제 저장소(SYNK-talk)는 **원리상** 못 봤다. 실측 2026-08-31
 * (런 `검수-2026-08-31T0726-146d06`): talk 커밋 sha 를 `--commit` 으로 주고 cwd 를 talk 에 두고
 * 불렀는데도 git 이 여기서 돌아 `fatal: ambiguous argument '20d4455': unknown revision` 으로
 * 종료 2. 즉 「확인 불가」로 정직하게 죽긴 했지만 **검수 자체가 불가능**했다.
 * → ②만 `--저장소 <경로>` 로 뗀다. ①은 그대로 ROOT 다.
 *
 * 🔑 왜 장부는 안 가르나(집에 그대로 둔다):
 *   · 「어느 게 현행인가」는 파일 하나가 안다(CLAUDE.md). 장부를 저장소마다 두면 미처분 조회·
 *     런 목록·SessionStart 훅이 각자 반쪽 진실을 말한다 — 사람이 보는 콘솔이 둘이 된다.
 *   · 던진 런 상태는 이미 이 집의 tmp 한 곳에 산다(`검수런.js`). 장부만 갈라 두면 그 둘이 어긋난다.
 *   · talk 은 `docs/_ops/` 에 검수 장부 규약이 없고, 그쪽 커밋 게이트는 전체 스위트를 돈다 —
 *     **읽기 전용 검수 한 번에 남의 저장소 커밋을 요구**하는 꼴이 된다.
 * 🔴 그런데 한 벌로 두면 **키가 겹친다.** 지적 키는 `sha256(파일+제목)` 이라 저장소를 모르는데,
 *   두 저장소에 같은 상대 경로가 흔하다(`tools/…` · `lib/…` · `docs/…` · `package.json`).
 *   talk 에서 기각한 지적이 이 저장소의 같은 이름 지적을 **조용히 걸러내면** 그건 거짓 초록이다
 *   (`기각` 은 영구 필터다 · `걸러지는키들`). 그래서 **행마다 저장소를 적고 읽을 때 가른다.**
 * 🔑 스탬프는 «집이 아닐 때만» 찍는다 — 그래야 옛 행(스탬프 없음 = 집) 전량이 한 톨도 안 흔들리고,
 *   집에서 도는 판정(배포 게이트)이 저장소 이름을 알아내려 git 을 한 번도 더 안 부른다
 *   (훅 로드 경로에 새 사슬을 얹지 않는다 — 등록층에서 새면 방향은 언제나 「통과」다). */
const 저장소플래그 = '--저장소';
let 대상ROOT = ROOT;
/** 지금 재는 것이 이 도구의 집이 **아닌가**. Apps Script 배포층이 서는지 가르는 유일한 축이다. */
const 타저장소 = () => 대상ROOT !== ROOT;

/* 저장소 이름 — **워크트리에서도 같은 값**이어야 한다. 이 저장소는 레인마다 워크트리를 파는데
 * `basename(작업본)` 으로 적으면 같은 저장소가 세션마다 다른 이름(`zen-elbakyan-d21925`)으로
 * 장부에 남고, 그러면 어제 찍은 처분이 오늘 안 걸러진다. `--git-common-dir` 은 워크트리에서도
 * 본 저장소의 `.git` 을 가리키므로 그 부모가 답이다(실측: 이 워크트리에서도 `SYNK-appsscript`).
 * ⚠ 못 읽으면 basename 으로 떨어진다 — 그 방향은 「장부 행이 안 보인다」= 다시 검수하라이지
 *   「통과」가 아니다. 새는 방향을 뒤집어 둔다. */
const 이름캐시 = new Map();
function 저장소이름(root) {
  if (이름캐시.has(root)) return 이름캐시.get(root);
  let 이름;
  try {
    const 공통 = execFileSync('git', ['-C', root, 'rev-parse', '--path-format=absolute', '--git-common-dir'],
      자식옵션({ encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'], timeout: 15000 })).trim();
    이름 = 공통 ? path.basename(path.dirname(path.resolve(공통))) : path.basename(root);
  } catch (_) { 이름 = path.basename(root); }
  이름캐시.set(root, 이름);
  return 이름;
}

/** 절대 경로로 대상을 잡는다(회차 자식은 방에서 이 값을 읽어 그대로 잡는다). */
function 저장소잡기(절대) {
  대상ROOT = path.resolve(절대);
  return 대상ROOT;
}

/* `--저장소 <경로>` 를 읽어 대상을 연다. 경로는 저장소 «안» 아무 데나 줘도 된다 — toplevel 로 올린다.
 * ⚠ 인자 배열의 값을 **절대 경로로 고쳐 둔다**: 던지기·이어받기 자식은 cwd 가 다르므로 상대 경로를
 *   그대로 물려주면 자식이 딴 저장소를 열거나 못 열고, 그 실패는 30분 뒤 「멈춤」으로만 보인다. */
function 저장소열기(argv) {
  const i = (argv || []).indexOf(저장소플래그);
  if (i === -1) return null;
  const 값 = argv[i + 1];
  if (!값 || /^--/.test(값)) {
    const e = new Error(`${저장소플래그} 뒤에 저장소 경로가 없다 — 예: ${저장소플래그} ../SYNK-talk`);
    e.확인불가 = true; throw e;
  }
  const 후보 = path.resolve(process.cwd(), 값);
  let top;
  try {
    top = execFileSync('git', ['-C', 후보, 'rev-parse', '--show-toplevel'],
      자식옵션({ encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 15000 })).trim();
  } catch (e) {
    const err = new Error(`${저장소플래그} "${값}" 을 git 저장소로 못 읽었다 — ${String((e && e.stderr) || (e && e.message) || e).split('\n').filter(Boolean).pop() || ''}`);
    err.확인불가 = true; throw err;
  }
  argv[i + 1] = 저장소잡기(top);
  return 대상ROOT;
}

/* 동기 대기 — 이벤트 루프를 안 돌리고 잔다.
 * 왜 이 모양인가: 이 파일의 실행 사슬은 **전부 동기**(`execFileSync`)다. 회차 병렬을 위해
 * async 로 뒤집으면 main 300줄과 그 안의 return 전부가 Promise 가 되고, 그 대수술의 회귀
 * 위험이 병렬로 버는 시간보다 크다. 자식은 `spawn` 으로 띄우고(프로세스 생성 자체는 동기다)
 * 결과는 **파일**로 받으므로, 부모는 이벤트 루프 없이 파일만 폴링하면 된다.
 * ⚠ 그래서 자식 stdio 를 파이프로 두면 안 된다 — 파이프는 이벤트 루프가 있어야 비워지고,
 *   여기서 루프는 멈춰 있다. 버퍼가 차면 자식이 그대로 매달린다. 반드시 파일 fd 로 준다. */
function 동기대기(ms) {
  try { Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms); } catch (_) { /* 못 자면 바쁜 폴링으로 떨어진다 */ }
}

/* 장부 경로 — env 로 갈아끼울 수 있다. 회귀가 **픽스처로 탐지력을 못 박기** 위해서다
 * (실저장소 장부로 시험하면 「지금 마침 지적이 없어서」 초록인지 「검사가 죽어서」 초록인지 안 갈린다).
 * 우회 수단이 되지는 않는다 — env 를 세울 수 있는 사람은 CLASP_GUARD_BYPASS 도 세울 수 있고,
 * 그쪽이 이미 **의식적인** 정식 레버다. */
const 기록경로 = process.env.SYNK_REVIEW_LEDGER || path.join(ROOT, 'docs', '_ops', '검수기록.jsonl');
const 기각경로 = process.env.SYNK_REVIEW_REJECTS || path.join(ROOT, 'docs', '_ops', '검수기각.jsonl');
const 제안경로 = process.env.SYNK_REVIEW_PROPOSALS || path.join(ROOT, 'docs', '_ops', '검수제안.jsonl');
const 스키마경로 = path.join(__dirname, 'codex-review.schema.json');
const 제안스키마경로 = path.join(__dirname, '검수제안.schema.json');
const 기능체크스키마경로 = path.join(__dirname, '기능체크.schema.json');

/* 차단급 — P0(라이브 데이터 손상·보안) · P1(배포 전 반드시). P2/P3 는 알리되 막지 않는다.
 * 등급을 넓히면 사람이 우회를 배운다(v6.11) — 막는 것은 정말 막아야 하는 것만. */
const 차단급 = new Set(['P0', 'P1']);

/* ── 처분 레버 셋 (2026-08-17 · 유호 픽 「1,2,3 한벌로 가자」) ──────────────────────────
 * 옛 판은 종결 레버가 `--기각` **하나뿐**이었다. 그래서 「지적이 옳았고 고쳤다」도 기각 통에 들어갔고,
 * 장부에 실제로 그렇게 적혀 있다 — *"지적이 옳았다 — 그리고 고쳤다(기각은 이 도구의 유일한 종결
 * 레버라 여기 적는다 · 틀렸다는 뜻 아님)"*. 한 통에 뭉치면서 둘이 함께 샜다:
 *   ① **계측이 거짓말한다** — 기각률을 검수 오판율로 읽으면 실제보다 나쁘게 나온다(실측 08-17:
 *      기능체크 P1 기각률 36% · 코드 diff 10%. 그 안에 「옳았고 고쳤다」가 섞여 있어 둘 다 상한이다).
 *   ② **수리 불완전이 조용해진다** — 기각은 다음 런에서 영구 필터라(`걸러지는키들`), 고쳤다고
 *      적는 순간 그 지적은 **다시는 안 올라온다.** 수리가 덜 됐어도 그렇다.
 * 🔑 그래서 필터는 **`기각`만** 탄다. 채택수리·범위밖은 장부에 남되 안 걸러진다 —
 *   채택수리가 다시 올라오면 그건 소음이 아니라 **「수리가 덜 됐다」는 신호**이고,
 *   범위밖은 다음 런의 범위가 다르면 유효해진다.
 * ⚠ 대가를 함께 적는다: 그 둘은 매 런 다시 올라올 수 있다(소음이 는다). 그래서 `이전처분줄들()` 이
 *   「이전에 이렇게 처분했다」를 나란히 찍는다 — 걸러주지 않고 **보여준다**(억제는 신호를 죽인다).
 * 🔑 하위호환: `처분` 필드가 없는 옛 행(08-17 이전 81건)은 전부 `기각`으로 읽는다 — 그게 당시 뜻이다. */
/* 🔴 **축이 둘이다 — 그리고 08-17 에 그 둘을 한 필드로 뭉쳐서 샜다**(F588 · 유호 픽 ㉣ 08-17).
 *   `걸러냄` 은 「다음 런 프롬프트에서 걸러내나」(필터 축)이고, 배포 게이트가 묻는 것은
 *   「이 지적이 처분됐나」(게이트 축)다. **뜻이 다른 두 질문**인데 `게이트판정()` 이
 *   `걸러지는키들()` 하나를 같이 써서, `걸러냄:false` 인 레버가 곧 «게이트를 영구히 못 연다»가 됐다.
 *   실측(F588): 전임 세션이 P1 4건을 `--대상아님` 으로 사유까지 달아 전부 처분했는데 게이트는
 *   그대로 block — 사람이 보는 모든 신호는 「처분 끝」인데 게이트만 안 열렸다. 그래서
 *   **참인데 배포집합 밖인 지적에는 정직한 출구가 0** 이었고, 남은 출구는 `기각`(=「틀렸다」 +
 *   영구 필터)으로 **참인 지적을 묻는 것**뿐이었다.
 * 🔑 그래서 축을 **선언으로 끌어낸다** — `걸러냄`(필터) 옆에 `게이트해소`(게이트)를 따로 적는다.
 *   두 소비자가 각자 자기 필드를 읽으므로 한쪽을 고칠 때 다른 쪽이 조용히 갈리지 않고,
 *   회귀가 「선언과 실제가 같다」를 단언할 수 있다(값을 못 박는 게 아니라 **정합**을 지킨다).
 * `게이트해소` 세 값:
 *   '항상' — 지적이 틀렸다는 뜻이라 무조건 해소(기각).
 *   '없음' — 해소로 안 센다. 채택수리가 이쪽인 이유: 고쳤으면 **바이트가 바뀌어 지문이 바뀌고**
 *            검수 기록 자체가 무효가 된다 — 게이트는 새 지문에서 다시 물어야 한다.
 *   '지문' — **그 지문에 한해서만** 해소(대상아님 · 유호 픽 ㉣). 배포집합이 한 바이트라도 바뀌면
 *            지문이 달라져 자동 무효다(검수 기록이 이미 쓰는 그 기전). 그리고 «범위 밖»이라는
 *            주장 자체를 기계로 함께 잰다 — `과녁이배포집합밖()`. 오분류 한 건이 그 배포를 열기
 *            때문에, 사람의 라벨만 믿지 않는 것이 이 값의 대가이자 안전선이다. */
const 처분레버들 = [
  { 플래그: '--기각', 처분: '기각', 걸러냄: true, 게이트해소: '항상',
    다음런: '다음 런에서 이 지적은 **걸러진다**(재발 필터 대상).' },
  { 플래그: '--채택수리', 처분: '채택수리', 걸러냄: false, 게이트해소: '없음',
    다음런: '지적이 옳았다는 뜻이라 **안 걸러진다** — 다시 올라오면 그건 「수리가 덜 됐다」는 신호다.' },
  { 플래그: '--대상아님', 처분: '대상아님', 걸러냄: false, 게이트해소: '지문',
    다음런: '이번 채택 범위 밖이라는 뜻이라 **안 걸러진다** — 범위가 바뀌면 다시 유효해진다.\n   그리고 이 처분은 **찍힌 그 지문에서만** 게이트를 연다(배포집합이 바뀌면 자동 무효).' },
];
const 레버of = (처분) => 처분레버들.find((L) => L.처분 === 처분) || null;
/* ⚠ 이름이 `--범위밖` 이 아닌 이유(실측 08-17 · 짓다가 밟았다): `--범위밖` 은 이미 `범위밖탈출` 이다.
 *   같은 문자열을 값플래그에 얹으면 인자 파서가 **뒤 토큰을 값으로 건너뛰어**(`아는가` 루프),
 *   `--범위밖 --버그만` 의 `--버그만` 이 조용히 삼켜진다. 안 도는 게 아니라 «맞는 얼굴로 틀린 값»이라
 *   더 위험하다. `tests/검수처분.test.js` 의 첫 시험(「플래그 충돌 — 값플래그가 홑플래그·단독 상수와
 *   겹치지 않는다」)이 이 자리를 기계로 막고, 바로 다음 시험이 그 **검출기 자신의 탐지력**까지 잰다
 *   — 일부러 겹친 목록을 먹여 ≥1건을 잡는지 본다(안 잡히면 앞 시험의 초록이 거짓이다). */
const 처분of = (행) => (행 && 행.처분) || '기각';
/* 이 판정을 쓰는 곳이 둘이다(`게이트판정` · `main` 의 신규 필터). 두 곳에 적으면 갈라지고,
 * 갈라진 쪽 증상은 «게이트는 막는데 화면엔 안 뜬다»(또는 그 반대)라 사람이 원인을 못 찾는다. */
const 걸러지는키들 = (기각행들) => new Set((기각행들 || []).filter((r) => 처분of(r) === '기각').map((r) => r.키));

/* ── 무효 표식 — 「이 기록행은 **검수 도장이 아니다**」 (2026-09-03 실측 · 방 열쇠 충돌의 뒤처리)
 *
 * 왜 필요한가: 방 열쇠에 내용 축이 없던 동안, 한 세션의 기록행에 **옆 세션의 지적**이 박혔다
 *   (`docs/_ops/검수기록.jsonl` 2026-09-03T00:17:59.689Z · 변경 33f6014226e9 는 엔진_폼리포트 쪽인데
 *   지적 7건이 전부 `영상/` 파일이었다). 그 행이 주장하는 것은 «배포내용 1e2d08c8 을 검수했다»인데
 *   codex 는 그 바이트를 **한 번도 안 봤다** — 즉 행 자체가 도장으로서 거짓이다.
 * 🔑 지우지 않는다(장부는 append-only) · 지적을 `--기각` 하지도 않는다 — 그 7건은 **남의 진짜 지적**이라
 *   기각하면 재발 필터에서 영구히 사라진다. 무효로 만드는 것은 «행과 지문의 짝»이지 지적이 아니다.
 * 🔑 그래서 표식은 **행 단위**이고 손잡이는 그 행의 `시각`(장부에서 유일하다)이다. 표식 행은 지문
 *   칸이 없으므로 게이트의 지문 필터에 원리상 안 걸린다 — 표식이 도장으로 오독될 길이 없다.
 * ⚠ 짝을 못 찾는 표식은 **아무것도 안 지운다**(그 행이 아직 다른 워크트리에 있는 경우) — 새는
 *   방향이 「그 행이 여전히 게이트를 막는다」라 안전하다. 표식을 적는 쪽에서 큰 소리로 알린다. */
const 검수행인가 = (r) => !!r && !r.종류;                 // 검수 기록행엔 `종류` 칸이 없다(표식 행에만 있다)
const 무효행들 = (기록행들) => new Set((기록행들 || [])
  .filter((r) => r && r.종류 === '무효' && r.무효행).map((r) => r.무효행));

/* ── 「그 지적의 과녁이 정말 이 프로젝트의 배포집합 밖인가」를 **기계로** 판정한다 (유호 픽 ㉣ 08-17)
 *
 * 왜 사람 라벨만 믿지 않나: `대상아님` 이 그 지문의 게이트를 열게 되면, **오분류 한 건이 그 배포를
 * 연다.** 그래서 라벨과 나란히 과녁을 잰다 — 새는 방향이 「통과」인 자리라 검사가 없으면 안 된다.
 *
 * ⚠ 기능체크 갈래엔 기계가 읽을 `파일` 칸이 **아예 없다**(상수 `(기능체크)` · 그게 F545 키 병의 뿌리다).
 *   그래서 그쪽은 산문(제목·근거·수정방향)에서 배포집합 **파일명**을 찾는다. 실측 08-17: 기능체크
 *   차단급 64건 중 **22건이 배포집합 파일을 지목했다** — 「기능체크는 늘 배포와 무관」은 거짓이다.
 * 🔑 그래서 판정은 **보수적**이다 — 한 이름이라도 걸리면 «밖»이라고 하지 않는다(모르면 안 열린다).
 *   틀리는 방향을 「막힘」으로 몰아 둔다: 잘못 막으면 사람이 보고 풀지만, 잘못 열면 아무도 안 본다. */
function 과녁이배포집합밖(원본, 배포집합) {
  if (!원본) return false;                                  // 원본을 못 찾으면 판정 불가 → 안 연다
  const 집합 = 배포집합 instanceof Set ? 배포집합 : new Set(배포집합 || []);
  if (!집합.size) return false;                             // 배포집합을 못 읽었으면 안 연다(F207)
  const p = String(원본.파일 || '').replace(/\\/g, '/');
  if (!p || p === '(모름)') return false;
  if (!/^\(/.test(p)) return !집합.has(p);                   // 코드 지적 — 경로 하나로 갈린다

  /* 기능체크 갈래 — 산문에서 배포집합 파일명을 찾는다. 확장자 있는 이름만 쓴다(짧은 토큰이
   * 우연히 걸리면 «못 연다» 쪽으로 새므로 안전하지만, 무의미한 막힘은 그 자체로 F103 이다). */
  const 이름들 = [...집합].filter((f) => /\.(js|json)$/.test(f));
  const 글 = [원본.제목, 원본.근거, 원본.수정방향].filter(Boolean).join('\n');
  return !이름들.some((n) => 글.includes(n));
}

/* ── 게이트 축: 「이 지적이 해소됐나」 (필터 축 `걸러지는키들` 과 **다른 질문**이다 · F588)
 *
 * `이름`·`fp` = 지금 판정 중인 프로젝트와 그 배포 내용 지문. `배포집합` = 그 프로젝트의 나갈 파일들.
 * 반환 = 해소된 키들의 Set.
 * 🔑 `'지문'` 레버는 **두 조건을 다** 넘어야 해소다 — ①찍힌 지문이 지금 지문과 같다 ②과녁이
 *   기계로도 배포집합 밖이다. 하나라도 못 넘으면 그 행은 없는 것처럼 취급한다(게이트는 닫힌 채). */
function 게이트해소키들(기각행들, 이름, fp, 배포집합, 원본찾기) {
  const 해소 = new Set();
  for (const r of 기각행들 || []) {
    /* 🔑 옛 행(처분 필드 없음)은 `처분of` 가 이미 `'기각'` 으로 번역하므로 레버 표에서 `'항상'` 이
     *   나온다 — 하위호환은 그 자리가 진다(실측: 실장부 182행 전부 레버 표에 있다).
     * ⚠ 그래서 이 폴백이 실제로 타는 경우는 **모르는 `처분` 값**뿐이다(미래 레버·손편집·깨진 행).
     *   그때 `'항상'` 으로 접으면 모르는 값이 게이트를 **연다** — 새는 방향이 「통과」다.
     *   변이 검사가 이 자리를 구멍으로 잡아냈다(08-17): 폴백을 바꿔도 14건이 전부 초록이었다.
     *   ⇒ 모르면 **안 연다**. 잘못 막으면 사람이 보고 풀지만, 잘못 열면 아무도 안 본다. */
    const 모드 = (레버of(처분of(r)) || {}).게이트해소 || '없음';
    if (모드 === '항상') { 해소.add(r.키); continue; }
    if (모드 === '없음') continue;
    if (모드 !== '지문') continue;
    if (!r.지문 || r.지문[이름] !== fp) continue;                 // 다른 배포 내용에 대한 판정이다
    const 원본 = 원본찾기 ? 원본찾기(r.키) : null;
    if (!과녁이배포집합밖(원본 || r, 배포집합)) continue;          // 라벨은 밖인데 과녁이 안이면 안 연다
    해소.add(r.키);
  }
  return 해소;
}
/* 안 걸러지는 처분(채택수리·범위밖)이 다시 올라왔을 때 나란히 보여줄 줄. */
function 이전처분줄들(지적들, 기각행들) {
  const 표 = new Map();
  for (const r of 기각행들 || []) if (처분of(r) !== '기각') 표.set(r.키, r);
  return (지적들 || []).filter((f) => 표.has(f.키)).map((f) => {
    const r = 표.get(f.키);
    return `  ↩ ${f.등급} ${f.제목}\n     이전 처분 «${처분of(r)}»(${r.시각 ? r.시각.slice(0, 10) : '시각 미상'}): ${r.사유}`;
  });
}

/* ── 진행 표식 — **조용한 죽음을 보이게 한다** (F333 · 2026-08-11 실측) ─────────────
 * 이 파일 머리말은 「통과와 미실행을 같은 모양으로 두지 않는다」를 종료코드로 지킨다. 그런데
 * 종료코드는 **이 프로세스가 살아서 반환할 때만** 존재한다. 밖에서 죽으면 catch 도 종료코드도
 * 없고, 남는 것은 이미 찍힌 머리말 몇 줄뿐이다 — 그게 F333 이 본 화면이다(헤더만·기록 0).
 *
 * 왜 그게 상수인가(추정이 아니라 산술):
 *   · ③ 최종검수 1회 = 1단계 분석 + 2단계 구조화 + 기능체크. 기본 회차 2 → 판단 패스 4번.
 *     max 추론 실측이 패스당 5~8분이므로 **정상 완주가 20~40분**이다(아래 「검수 중…」 줄의 근거).
 *   · 호출자(클로드 세션)의 포그라운드 셸 상한은 **10분**이고 기본은 2분이다.
 *   → 즉 ③ 은 포그라운드에서 **완주할 수 없다.** 가끔 죽는 게 아니라 언제나 죽는다.
 *     F333 의 4수는 전부 그 상한 안에서 죽었고, 죽음의 모양이 「헤더만」이라 도구 결함으로 읽혔다.
 *
 * 그래서 시작할 때 표식을 남기고 **정상 반환 시 지운다**(try/finally). 밖에서 죽으면 finally 가
 * 안 돌아 표식이 남고, 다음 실행이 그걸 읽어 「직전은 완주 못 했다」를 사람에게 말한다.
 * 남는 것이 증거고, 지워지는 것이 정상이다 — 새는 방향이 「통과」가 되지 않게 뒤집어 놓는다.
 *
 * ⚠ 표식은 **게이트가 아니다.** 검수기록과 섞지 않는다(섞으면 배포를 막는 장부에 「돌다 죽음」이
 *   행으로 들어가 판정이 갈린다). 세션별·프로젝트별로 갈라 남의 실행을 내 것으로 읽지 않는다.
 * 자리는 저장소 밖 임시 폴더의 **전용 디렉터리**다 — 미커밋 노이즈로 남의 작업본에 섞일 일이
 *   원천적으로 없다(F073).
 * ☠️ **`handoff-store.stateDir()` 안에 두면 안 된다**(2026-08-11 실측으로 잡았다 · 첫 판이 그랬다):
 *   그 폴더는 `handoff-store.sweep()` 이 청소하는데, 규칙이 `if (!j.at || 나이>TTL) unlink` 라
 *   **`at` 필드가 없는 내 표식은 나이와 무관하게 즉시 지워진다.** 세션이 여럿 도는 시간대엔
 *   남의 훅이 sweep 을 부르는 순간 사라져서, 실측에서 검수 시작 몇 초 뒤에 이미 없었다.
 *   증상은 「표식이 없다」 = 「완주했다」 — **증거를 지키려고 만든 장치가 정확히 반대로 샜다.**
 *   sweep 이 틀린 게 아니다(모르는 파일을 치우는 게 그 일이다) — **남의 청소 구역에 내 증거를
 *   둔 것이 틀렸다.** 그래서 폴더를 가른다. 이름 규칙만 그 모듈 것을 쓴다(같은 판정 두 벌 금지).
 * 회귀가 「stateDir 안이 아니다」를 못박는다 — 되돌리면 조용히 다시 샌다. */
function 진행파일() {
  if (process.env.SYNK_REVIEW_INFLIGHT) return process.env.SYNK_REVIEW_INFLIGHT;
  /* 지연 require — 이 모듈은 clasp-guard 훅도 부른다. 위(모델설정) 주석과 같은 축으로,
   * 훅 로드 경로에 새 require 사슬을 얹지 않는다(등록층에서 새면 방향은 언제나 「통과」다). */
  const store = require(path.join(ROOT, '.claude', 'hooks', 'lib', 'handoff-store.js'));
  const 세션 = store.safeId(보드id.세션id() || '');
  /* 키는 **재는 저장소**로 만든다 — 한 세션이 두 저장소를 검수하면 표식이 서로를 덮고,
   * 덮인 쪽의 「밖에서 죽었다」가 통째로 사라진다(증거가 사라지는 방향 = 통과). 집이면
   * 예전과 같은 값이라 이미 떨어져 있는 표식도 그대로 읽힌다. */
  return path.join(os.tmpdir(), 'synk-검수진행', `${store.projectKey(대상ROOT)}-${세션}.json`);
}

function 진행시작(정보) {
  const p = 진행파일();
  /* 표식을 못 남기는 것이 검수를 막을 이유는 아니다 — 이건 증거지 게이트가 아니다.
   * 다만 조용히 넘기면 「표식이 없다 = 완주했다」가 거짓이 되므로 그 사실만 알린다. */
  try {
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.writeFileSync(p, JSON.stringify({ ...정보, pid: process.pid, 시작: new Date().toISOString() }, null, 2));
  } catch (e) {
    console.error(`⚠ 진행 표식을 못 남겼다(${e.message}) — 이 실행이 밖에서 죽으면 그 사실이 안 남는다.`);
    return null;
  }
  return p;
}

function 진행종료() {
  try { fs.unlinkSync(진행파일()); } catch (_) { /* 없으면 그만 — 지우는 게 목적이다 */ }
}

function 낡은진행() {
  try { return JSON.parse(fs.readFileSync(진행파일(), 'utf8')); } catch (_) { return null; }
}

/* 죽은 표식을 사람이 읽을 줄로. **처방이 그대로 실행 가능해야 한다**(F103) — 그래서 「늘려라」가
 * 아니라 백그라운드로 돌리는 명령 그 자체를 준다. `--timeout` 을 늘리는 처방은 이 자리에선
 * 오히려 해롭다: 도구가 더 오래 버티게 만들 뿐, 호출자의 10분 상한은 그대로다. */
/* 예상 소요를 **호출 규약과 함께** 못박는다 — 「오래 걸린다」만으로는 호출자가 포그라운드로 부르고
 * 상한에 죽는다(F333 4수는 전부 그 모양이었다). 숫자와 명령을 같이 줘야 처방이 실행 가능해진다(F103).
 * ⚠ 조건을 걸지 않는다 — **가장 빠른 조합(`--버그만 --회차 1`)도 5~8분**이라 포그라운드 기본 2분을
 *   이미 넘는다. 「이 조합은 괜찮다」로 한 자리라도 빼면 그 자리가 다음 F333 이 된다.
 * 5~8분은 실측(max 추론 판단 패스 1번 · 아래 「검수 중…」 줄과 같은 근거)이고, 패스 수는
 * 회차 × (버그 사냥 + 기능체크)다 — 곱을 사람이 암산하게 두지 않는다. */
function 소요안내(argv, 회차) {
  const 패스수 = ((argv || []).includes('--버그만') ? 1 : 2) * (회차 || 1);
  return `⏳ 정상 완주 ${패스수 * 5}~${패스수 * 8}분(판단 패스 ${패스수}번 × 5~8분) — **포그라운드 셸에서는 죽는다**` +
    '(기본 2분 · 상한 10분). 백그라운드로 부르고 로그는 파일로 받아라 — 파이프를 끼우면 종료코드가 사라진다(F308).';
}

/* 긴 codex 경로의 **공통 입구** — ③최종검수만이 아니라 ①선파악·②심문도 같은 모양으로 죽는다
 * (셋 다 판단 패스 5~8분짜리를 여러 번 돈다). 호출부마다 표식을 걸면 언젠가 한 문을 빠뜨리고,
 * 빠뜨린 그 문이 다음 F333 이 된다 — 그래서 거는 자리를 하나로 둔다.
 * 「직전이 죽었다」를 알리는 것도 여기서 한다: 어느 문으로 들어와도 같은 사실을 같은 말로 듣는다. */
function 진행걸기(argv, 정보) {
  const 이전 = 낡은진행();
  if (이전) console.error('\n' + 진행경고줄(이전, argv).join('\n') + '\n');
  진행시작(정보);
  /* 지우는 자리를 `exit` 리스너 **하나로** 둔다. return 마다 손으로 지우면 하나만 빠뜨려도
   * 「완주했는데 표식이 남는」 거짓 경고가 되고, 거짓 경고는 사람이 경고를 무시하게 만든다.
   * 🔑 이게 정확히 원하는 판별자다 — 정상 종료·예외·process.exit 에서는 리스너가 돌아 지워지고,
   *   **밖에서 죽으면(SIGTERM/SIGKILL/taskkill) 안 돌아 표식이 남는다.** */
  process.on('exit', 진행종료);
}

function 진행경고줄(이전, argv) {
  const 대상표기 = 이전 && 이전.대상 ? `${이전.대상.종류} ${이전.대상.값}` : '(모름)';
  const 인자 = (argv || []).join(' ');
  return [
    '🔴 직전 실행이 **완주하지 못했다** — 검수 기록 0건으로 끝났다(통과가 아니다).',
    `   시작 ${(이전 && 이전.시작) || '(모름)'} · 대상 ${대상표기} · pid ${(이전 && 이전.pid) || '?'}`,
    '   종료코드도 오류 줄도 없이 끊겼다 = **밖에서 죽었다.** 가장 흔한 원인은 호출한 셸의 시간 상한이다',
    '   (③ 최종검수 정상 완주 = 20~40분 · 포그라운드 셸 상한 = 10분 → 포그라운드에선 언제나 죽는다).',
    `   처방: 백그라운드로 돌린다 —  node tools/codex-review.js ${인자} > 검수.log 2>&1 &`,
  ];
}

// ─────────────────────────────────────────────────────────────── 공용

const jsonl = (p) => {
  if (!fs.existsSync(p)) return [];
  return fs
    .readFileSync(p, 'utf8')
    .split('\n')
    .filter((l) => l.trim())
    .map((l) => {
      try { return JSON.parse(l); } catch (_) { return null; }
    })
    .filter(Boolean);
};

const append = (p, obj) => {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.appendFileSync(p, JSON.stringify(obj) + '\n', 'utf8');
};

/* ── 장부 한 벌 · 저장소별로 가름 (위 「대상 저장소」 머리말의 실행부)
 * `''` = 이 도구의 집이고, **스탬프 없는 옛 행 전량이 그 값**이다(하위호환이 규칙 하나로 닫힌다).
 * ⚠ 배포 게이트는 언제나 `장부읽기(p, '')` 로 읽는다 — 「집의 배포」를 재는 판정이라 남의 저장소
 *   행이 원리상 못 닿아야 한다. 현재 대상이 무엇이든 그 값은 안 흔들린다. */
/* 🔑 **집의 워크트리는 집이다**(2026-09-04 · 실행자 레인 `codex-build.js` 가 `.claude/worktrees/codex+…` 를
 *   `--저장소` 로 대기 시작했다). `타저장소()` 는 그대로 참이다 — 배포 지문(`유효지문`)은 **메인 작업본**의
 *   바이트를 재므로 워크트리 검수에 지문을 붙이면 F335 그대로 거짓 초록이 된다. 갈라 두는 것은 «장부 라벨»뿐이다:
 *   워크트리 행에 `저장소: 'SYNK-appsscript'` 를 찍으면 집(`''`)에서 찍은 기각이 그 검수를 못 거르고, 거기서 찍은
 *   기각이 집을 못 거른다 — 같은 저장소의 같은 결함이 두 번 올라온다. `저장소이름()` 은 워크트리에서도 집과
 *   같은 값이라(공통 `.git` 의 부모) 그것으로 «같은 집»을 가른다. 형제(talk)는 이름이 달라 그대로 갈린다. */
const 같은집 = () => !타저장소() || 저장소이름(대상ROOT) === 저장소이름(ROOT);
const 저장소스탬프 = () => (같은집() ? {} : { 저장소: 저장소이름(대상ROOT) });
const 이저장소표 = () => (같은집() ? '' : 저장소이름(대상ROOT));
const 행저장소 = (r) => (r && r.저장소) || '';
const 장부읽기 = (p, 표) => jsonl(p).filter((r) => 행저장소(r) === (표 === undefined ? 이저장소표() : 표));

/* Apps Script 배포층은 **이 도구의 집에만** 있다 — 형제 저장소엔 `.clasp.json` 이 없고, 있어도
 * 이 집의 `.claspignore` 로 남의 파일을 재면 안 된다(글롭이 우연히 맞는 날 남의 검수가 이 집의
 * 배포 게이트를 연다 — 거짓 초록의 교과서). 그래서 「프로젝트 목록」을 여기 한 곳에서 낸다:
 * 같은 판정을 호출부 여섯에 적으면 갈라지고, 갈라진 쪽이 새는 쪽이다(가드 맹점 ④). */
function 클라스프프로젝트들() {
  return 타저장소() ? [] : 점검.claspProjects();
}

/* 지적 키 — 같은 지적이 회차를 넘어 같은 것으로 인식되게 하는 손잡이.
 * 파일+제목으로 만든다(등급은 뺀다 — 같은 결함에 회차마다 다른 등급이 붙을 수 있고,
 * 그때 기각이 풀리면 기각의 뜻이 사라진다). 제목은 공백·대소문자를 눌러 정규화한다. */
function 키(f) {
  const norm = String(f.제목 || '').toLowerCase().replace(/\s+/g, ' ').trim();
  return crypto.createHash('sha256').update(String(f.파일 || '') + '\0' + norm).digest('hex').slice(0, 12);
}

/* 프로젝트별 지문 — 지금 이 순간 라이브로 나갈 바이트의 지문이다.
 *
 * 🔴 **검수한 것과 지문이 같은 것을 가리킬 때만 기록한다.** 2026-08-05, 이 도구를 이 도구로
 *   검수하다가 잡힌 P1 결함이다(첫 실전 검수의 첫 지적):
 *     `--commit <sha>` 로 검수하는 동안 작업본에 **다른** 미커밋 배포 파일 변경이 있으면,
 *     검수된 것은 그 커밋인데 기록되는 지문은 **작업본**이다. 그러면 게이트는 검수된 적 없는
 *     작업본 바이트를 「검수됨」으로 읽고 통과시킨다 — 정확히 이 게이트가 막으려던 미탐이다.
 *   그래서 대상과 작업본이 어긋나면 그 프로젝트의 지문을 **아예 안 적는다.** 빠진 지문은
 *   게이트에서 `none`(알림)이 되므로, 모르는 것은 「모름」으로 나타난다. */
/** 이 목록에 그 프로젝트의 **배포 파일**이 있나 — 판정만 하는 순수 함수(탐지력은 픽스처가 진다). */
function 배포변경있나(바뀐파일들, projRoot, root = ROOT) {
  return (바뀐파일들 || []).some((f) => 프로젝트.isDeployFile(f, projRoot, root));
}

function 유효지문(대상) {
  /* 형제 저장소엔 Apps Script 배포집합이 **원리상** 없다 — 여기서 이 집의 지문을 재면 남의
   * 검수 기록이 이 집의 배포 게이트를 여는 열쇠를 들고 다니게 된다(거짓 초록). 빈 값이 정답이다. */
  if (타저장소()) return {};
  const dirty = 미커밋파일들();
  let head = '';
  try { head = git(['rev-parse', 'HEAD']); } catch (_) {}
  /* 검수한 커밋 **이후로 바뀐 파일들** — 배포집합이 그 안에 없으면 지금 나갈 바이트 = 검수한 바이트다.
   * 못 읽으면 「전부 바뀐 것」으로 둔다(모름을 통과로 접지 않는다). */
  let 이후 = null;
  if (대상.종류 === 'commit') {
    try { 이후 = git(['-c', 'core.quotepath=false', 'diff', '--name-only', 대상.값, 'HEAD']).split('\n').filter(Boolean); }
    catch (_) { 이후 = null; }
  }

  const out = {};
  for (const p of 클라스프프로젝트들()) {
    const 이름 = path.relative(ROOT, p).replace(/\\/g, '/') || '(루트)';
    const 더러움 = dirty.some((f) => 프로젝트.isDeployFile(f, p, ROOT));
    /* uncommitted = 작업본 자체가 검수 대상이라 언제나 일치한다.
     * base/commit = 커밋된 상태를 검수한 것이라, 작업본에 그 프로젝트의 미커밋 배포 변경이
     *   있으면 어긋난다. commit 은 추가로 **그 커밋 이후 이 프로젝트의 배포집합이 안 바뀌었어야**
     *   한다 — 옛 커밋을 검수하고 지금 작업본을 「검수됨」이라 부르면 안 되기 때문이다.
     * 🔑 그 조건이 오래도록 「그 커밋이 곧 HEAD」였다. 지문은 **배포집합만** 해싱하므로 HEAD
     *   동일성은 뜻보다 넓은 조건이고, 이 저장소는 세션들이 docs·tools 를 쉼 없이 커밋해 버전
     *   커밋이 HEAD 인 순간이 거의 없다. 그래서 「남이 안 밀고 간 판을 떠맡아 검수하고 미는」
     *   이 저장소의 확립된 통로에서 게이트가 **구조적으로 안 채워졌다**(2026-08-09 실측: v9.198
     *   을 검수해 차단급 P1 을 잡았는데 기록의 지문이 비어 그 지적이 배포를 못 막았다).
     *   좁히는 게 아니라 재는 대상을 바로잡은 것이다 — 배포 바이트가 바뀌면 여전히 안 적는다. */
    const 일치 =
      대상.종류 === 'uncommitted' ? true :
      대상.종류 === 'base' ? !더러움 :
      !더러움 && head && (대상.값 === head || (이후 !== null && !배포변경있나(이후, p, ROOT)));
    if (!일치) continue;
    try { out[이름] = 점검.지문(p, ROOT); } catch (_) { /* 못 읽는 프로젝트는 빼둔다(없는 지문을 지어내지 않는다) */ }
  }
  return out;
}

// ─────────────────────────────────────────────────────────────── 대상

/* maxBuffer 를 **명시**한다 — 기본값은 1MB 고, 이 저장소에서 그 상한은 상시 조건에서 넘는다.
 * 2026-08-10 실측(F308): 옆 세션이 발표물 PDF 7벌을 미커밋으로 들고 있어 `diff HEAD` 가
 * 3.2MB 가 됐고 `spawnSync git ENOBUFS` 로 죽었다. 새는 방향이 나쁘다 — 예외가 파이프 뒤에서
 * 「통과」와 같은 모양이 됐다. 세션이 10개 도는 시간대엔 「누군가는 바이너리를 들고 있다」가
 * 우연이 아니라 상수라, 이 한 줄이 없으면 검수는 그 시간대에 원리상 못 돈다.
 * 넘치면 **죽지 말고** 확인 불가(2)로 내려간다 — 사유 없는 죽음이 통과로 읽히지 않게. */
const git버퍼 = 64 * 1024 * 1024;

/* 버퍼 초과인가 — node 판·플랫폼에 따라 `code` 가 안 붙고 문구로만 오는 경우가 있어 **둘 다** 본다.
 * 하나만 보면 못 알아본 초과가 그대로 위로 터져 사유 없는 죽음이 된다(그게 F308 의 모양이었다). */
function 버퍼초과(e) {
  return !!(e && (e.code === 'ENOBUFS' || /ENOBUFS|maxBuffer/i.test(String(e.message || ''))));
}

/* 자식 프로세스 옵션은 **여기 한 자리**에서 낸다(F361).
 *
 * 왜 통로인가: Windows 에서 자식 콘솔 창이 뜨는 조건은 「부모에게 콘솔이 없다」이고, 던지기(:1504)가
 * `detached` 로 뜨는 순간 그 아래 사슬 전체가 그 상태가 된다 — 즉 창을 만드는 것은 던지기가 아니라
 * **그 손자들**(회차 spawn · codex CLI · git)이다. 던지기에만 `windowsHide` 를 적어 둔 동안 유호님
 * 화면에는 회차마다 검은 창이 떴고, stdio 는 파이프·파일 fd 라 **한 글자도 안 찍힌다** — 진행 신호도
 * 아닌 순수한 방해이고 「멈춘 것 같다」로 읽힌다. 도구가 스스로를 고장난 것처럼 보이게 한 자리다.
 *
 * 왜 호출부마다 적지 않는가: 같은 판정을 두 곳에 적으면 갈린다(CLAUDE.md 등록층 맹점 ④). 실제로
 * 갈렸고, 새는 방향은 언제나 「창이 뜬다」였다. 새 호출부가 이 통로를 안 지나면 `창숨김누락()` 이
 * 그 줄 번호를 내고 회귀가 빨개진다. */
function 자식옵션(opts) {
  return Object.assign({ windowsHide: true }, opts);
}

/* 위 통로를 안 지나는 자식 호출부를 소스에서 센다 — 회귀가 쓰는 검사기다.
 * 반환 = 빠진 호출부의 줄 번호 배열. 호출부를 **하나도 못 찾으면 `null`** — 빈 배열을 내면
 * 「검사할 것이 없었다」가 「전부 통과」와 같은 모양이 된다(분모 없는 초록 · F207). */
function 창숨김누락(소스) {
  const src = String(소스 == null ? '' : 소스);
  const 호출 = /\b(?:spawnSync|spawn|execFileSync|execSync)\s*\(/g;
  const 빠진줄 = [];
  let 본것 = 0, m;
  while ((m = 호출.exec(src))) {
    const 여는 = m.index + m[0].length - 1;
    const 닫는 = 짝괄호(src, 여는);
    if (닫는 < 0) continue;          // 괄호가 안 닫히면 호출부로 세지 않는다(분모에서 뺀다)
    본것++;
    if (!src.slice(여는, 닫는 + 1).includes(`${자식옵션.name}(`)) {
      빠진줄.push(src.slice(0, m.index).split('\n').length);
    }
  }
  return 본것 ? 빠진줄 : null;
}

/* 여는 괄호의 짝을 찾는다. 문자열 안의 괄호는 세지 않는다 — 안 걸러내면 `')'` 하나가 슬라이스를
 * 통째로 어긋내고, 어긋난 슬라이스는 「통로를 지났다」로도 읽혀 조용히 통과한다. */
function 짝괄호(s, i) {
  let 깊이 = 0, 인용 = '';
  for (let k = i; k < s.length; k++) {
    const c = s[k];
    if (인용) { if (c === '\\') k++; else if (c === 인용) 인용 = ''; continue; }
    if (c === '"' || c === "'" || c === '`') { 인용 = c; continue; }
    if (c === '(') 깊이++;
    else if (c === ')') { 깊이--; if (!깊이) return k; }
  }
  return -1;
}

/* ⚠ cwd 는 **재는 저장소**다(`대상ROOT`) — 여기가 `ROOT` 로 못박혀 있던 것이 형제 저장소를
 * 원리상 못 보던 자리다(위 「대상 저장소」 머리말 · 08-31 실측 `unknown revision`). */
function git(args) {
  try {
    return execFileSync('git', args, 자식옵션({ cwd: 대상ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], maxBuffer: git버퍼 })).trim();
  } catch (e) {
    if (버퍼초과(e)) {
      const err = new Error(`git 출력이 상한(${Math.round(git버퍼 / 1024 / 1024)}MB)을 넘었다 — 대상이 너무 넓다. `
        + '`--commit <sha>` 로 과녁을 좁혀 다시 돌린다(미커밋 전체가 대상이면 남의 바이너리까지 들어온다).');
      err.확인불가 = true;
      throw err;
    }
    throw e;
  }
}

/* 미커밋(스테이지·비스테이지·미추적) 파일 목록.
 * core.quotepath=false — 끄지 않으면 한글 파일명이 이스케이프돼 매칭이 통째로 빗나간다
 * (이 저장소 배포 파일 상당수가 한글이라 이 한 줄이 없으면 「깨끗함」으로 보인다). */
function 미커밋파일들() {
  return git(['-c', 'core.quotepath=false', 'status', '--porcelain'])
    .split('\n').filter(Boolean)
    .map((l) => { let p = l.slice(3).trim(); const a = p.indexOf(' -> '); if (a !== -1) p = p.slice(a + 4).trim(); return p.replace(/^"|"$/g, ''); });
}

/* 🔴 F578 — 커밋 하나를 읽는 **공용 통로**. 세 자리(대상 파일목록 2 · 검수 본문 1)가 각각
 *   `git show` 를 부르던 것을 여기 하나로 모은다 — 호출부마다 고치면 다음에 느는 자리가 또 샌다.
 *
 * 급소: `git show <머지>` 는 기본이 **combined diff**(`--cc`)라 「양 부모 **모두**와 다른」 파일만
 *   낸다. 머지가 한쪽 부모에서 그대로 들여온 변경은 **통째로 안 보인다.** 그런데 과녁을 뽑는
 *   `과녁커밋` 의 `git log -- <배포집합>` 은 **모든 부모**와 대조해 바로 그 머지를 잡는다.
 *   두 자리의 부모 기준이 갈려서 게이트가 **자기가 뽑은 과녁으로 자기를 못 열었다**(종료 2).
 *   실측 2026-08-17 (`local_e9524e5d`):
 *     · `80b63ca9`(PR #79 머지)  — 현행 배포 0건 / 본문 **283자**  ↔  `--first-parent` 배포 2건 / **83,515자**
 *     · `fb84d011`(origin 머지)  — 현행 배포 0건                    ↔  `--first-parent` 배포 3건
 *   ⚠ 더 나쁜 쪽은 **본문**이다 — 파일 목록이 통과하는 날에도 283자를 던지면 검수자가 빈 판을
 *   보고 통과시킨다. 새는 방향이 「통과」라 조용하다.
 *
 * ⚠ 실커밋에는 아무 영향이 없다(부모가 하나면 `--first-parent` 는 무의미) — 추정이 아니라 실측이다:
 *   `661d2156` 은 두 방식이 **81,782자로 바이트까지 같다.** 그래서 이 플래그는 머지에서만 일한다.
 * 🔑 배포는 master 에서만 한다(CLAUDE.md 세션 규약) — 그래서 「master 사슬이 무엇을 받아들였나」인
 *   첫 부모 기준이 이 게이트가 재려던 바로 그것이다. F578 신고문은 원인을 「첫 부모 기준이라 안
 *   나온다」로 적었는데 **반대였다** — combined 라서 안 나오고, 첫 부모를 대야 나온다. */
const 머지기준 = '--first-parent';
function 커밋읽기(sha, ...args) {
  return git(['-c', 'core.quotepath=false', 'show', 머지기준, ...args, sha]);
}
function 커밋파일들(sha) {
  return 커밋읽기(sha, '--name-only', '--format=').split('\n').filter(Boolean);
}

/* 검수 대상 결정 + 그 대상이 건드린 파일 목록.
 * 파일 목록이 필요한 이유: **어느 clasp 프로젝트가 실제 검수 범위였는지**를 기록해야
 * 「루트만 검수하고 crewcard 를 배포」가 통과로 보이지 않는다(미탐 방향 차단). */
function 대상결정(argv) {
  const i = (k) => argv.indexOf(k);
  if (i('--commit') !== -1) {
    const sha = argv[i('--commit') + 1];
    if (!sha) throw new Error('--commit 뒤에 커밋 해시가 없다');
    return { 종류: 'commit', 값: sha, flags: ['--commit', sha], 파일들: 커밋파일들(sha) };
  }
  if (i('--base') !== -1) {
    const br = argv[i('--base') + 1];
    if (!br) throw new Error('--base 뒤에 브랜치명이 없다');
    return { 종류: 'base', 값: br, flags: ['--base', br], 파일들: git(['-c', 'core.quotepath=false', 'diff', '--name-only', br + '...HEAD']).split('\n').filter(Boolean) };
  }
  if (i('--uncommitted') !== -1) return { 종류: 'uncommitted', 값: '(미커밋)', flags: ['--uncommitted'], 파일들: 미커밋파일들() };

  // 기본값 — 미커밋이 있으면 그것, 없으면 HEAD. **무엇을 골랐는지 항상 출력한다**(조용한 선택 금지).
  const d = 미커밋파일들();
  if (d.length) return { 종류: 'uncommitted', 값: '(미커밋)', flags: ['--uncommitted'], 파일들: d };
  const sha = git(['rev-parse', 'HEAD']);
  return { 종류: 'commit', 값: sha, flags: ['--commit', sha], 파일들: 커밋파일들(sha) };
}

/* 처방의 **과녁** — 이 프로젝트의 배포집합을 마지막으로 건드린 커밋(8자리).
 * 게이트판정(알림문)과 실행 전 정지(아래 `범위밖정지`)가 **같은 한 곳**에서 뽑는다 —
 * 같은 판정을 두 곳에 적으면 갈라지고, 갈라진 쪽은 「따라도 안 열리는 처방」이 된다.
 * ⚠ 못 뽑으면 빈 문자열을 낸다 — 틀린 과녁을 지어내면 남의 판을 검수하게 된다. */
function 과녁커밋(projRoot, root = ROOT) {
  try {
    const 집합 = 점검.배포집합(projRoot, root);
    if (!집합.length) return '';
    /* 🔴 F578 — `머지기준` 과 **같은 축**으로 뽑는다. 이 한 줄이 없으면 `git log --` 는 모든 부모와
     *   대조해 머지를 잡는데 `커밋읽기` 는 첫 부모만 보므로, 뽑은 과녁을 읽는 쪽이 빈손이 된다.
     *   같은 판정을 두 곳에 적으면 갈라지고 갈라진 쪽이 새는 쪽이다(가드 맹점 ④). */
    const sha = git(['-c', 'core.quotepath=false', 'log', '-n', '1', 머지기준, '--format=%H', '--', ...집합]);
    return sha ? sha.slice(0, 8) : '';
  } catch (_) { return ''; }
}

/* 🔴 F578 — 위 두 축이 **정말로** 맞물렸는지 그 자리에서 되먹여 본다. 과녁을 내밀기 전에 그 sha 를
 *   `커밋파일들` 로 읽어 이 프로젝트의 배포 파일이 실제로 나오는지 본다 — 즉 **가드가 시키는 명령을
 *   가드에 되먹여 통과하는지**를 검사한다(CLAUDE.md 가드 맹점 ③). F578 은 정확히 이 검사가 없어서
 *   났다: 처방을 그대로 따른 세션이 5분을 태우고 종료 2(범위 밖)를 받았고, 그건 차단이 아니라
 *   알림이라 **배포는 그대로 나갔다.**
 * ⚠ 고치는 게 아니라 **드러내는** 장치다 — 부모 기준이 앞으로 또 갈리든, 배포집합 정의가 바뀌든,
 *   「따라도 안 열리는 처방」이면 내밀기 전에 걸린다.
 * ⚠ 못 재면(git 실패) `null` — 「배포 파일 0건」과 뭉치지 않는다(F207). 호출부가 축을 밝힌다. */
function 과녁이열리나(sha, projRoot, root = ROOT) {
  if (!sha) return null;
  try {
    const 집합 = new Set(점검.배포집합(projRoot, root));
    return 커밋파일들(sha).some((f) => 집합.has(f));
  } catch (_) { return null; }
}

/* 🔴 F335 — **과녁을 댈 수 있는 상태인가**를 가르는 한 벌. 위 `과녁커밋` 이 「어느 커밋이냐」를
 *   답한다면 여기는 「그 커밋을 대도 되느냐」를 답한다. 축은 하나다: 이 프로젝트의 배포 파일이
 *   지금 **미커밋**인가.
 *     · 미커밋이다 → 나갈 바이트가 곧 작업본이다. `--commit` 검수는 `유효지문`(:245)이 일부러
 *       지문을 안 적는 갈래라 **따라도 게이트가 안 열린다**(2026-08-11 실측 20~40분 소각).
 *     · 깨끗하다  → 작업본 diff 에 배포 파일이 0건이라 인자 없는 호출은 「범위 밖」으로 기록된다
 *       (F292 · 2026-08-09 실측 50분 소각). 그래서 과녁이 맞다.
 *   두 병은 **정반대 조건에서** 난다 — 그래서 처방도 배타가 아니라 상보다.
 * 🔑 이 판정을 쓰는 곳이 둘이다(게이트 알림문 · 실행 전 정지). 그래서 **여기 하나에서만** 한다 —
 *   같은 판정을 두 곳에 적으면 갈라지고 갈라진 쪽이 새는 쪽이 된다(가드 맹점 ④ · 이 파일이
 *   F293 으로 이미 한 번 밟았다).
 * ⚠ 못 재면(`null`) 한쪽으로 접지 않는다 — 호출부가 축을 밝히고 둘 다 남긴다. */
function 과녁판정(projRoot, root = ROOT, 주입) {
  const sha = 과녁커밋(projRoot, root);
  let 미커밋배포;
  /* 회귀는 **이 자리로** 상태를 끼운다. 실저장소의 더러움에 기대면 CI 는 깨끗한 트리라
   * 「미커밋」 갈래가 원리상 안 서고 그 초록은 통과가 아니라 미실행이며(F207), 반대로 옆
   * 세션이 배포 파일을 들고 있는 날엔 깨끗함 갈래가 거짓 적색이 된다 — 어느 방향이든
   * 실저장소는 이 판정을 못 진다. */
  if (주입 !== undefined) 미커밋배포 = 주입;
  else { try { 미커밋배포 = 점검.배포집합미커밋(projRoot, root); } catch (_) { 미커밋배포 = null; } }
  const 더러움 = 미커밋배포 === null ? null : 미커밋배포.length > 0;
  /* 🔴 F578 — 과녁을 내밀기 전에 **그 과녁으로 이 게이트가 열리는지** 되먹여 본다.
   * `false`(읽었는데 배포 파일 0건)면 과녁을 내지 않는다 — 따라도 종료 2 로 끝날 처방을 내미는 것이
   * 「없는 처방」보다 나쁘다(5분을 태우고 「돌렸는데 안 되네」로 접게 만든다 · F103 무늬).
   * ⚠ `null`(못 쟀다)은 `false` 로 접지 않는다 — 안 재본 것을 「안 열린다」로 번역하면 멀쩡한 과녁을
   * 조용히 버린다(F207). 못 쟀으면 종전대로 낸다. */
  const 열림 = (sha && 더러움 !== true) ? 과녁이열리나(sha, projRoot, root) : null;
  return { sha, 더러움, 미커밋배포, 열림, 과녁: (sha && 더러움 !== true && 열림 !== false) ? ` --commit ${sha}` : '' };
}

/* 검수 범위에 든 clasp 프로젝트 — 대상 diff 가 그 프로젝트의 **배포 파일**을 건드렸는가. */
function 범위(파일들) {
  const out = [];
  for (const p of 클라스프프로젝트들()) {
    const 이름 = path.relative(ROOT, p).replace(/\\/g, '/') || '(루트)';
    if (파일들.some((f) => 프로젝트.isDeployFile(f, p, ROOT))) out.push(이름);
  }
  return out;
}

// ─────────────────────────────────────────────────────────────── 업그레이드 제안 층 (2026-08-05 유호님 설계)

/* 유호님이 정한 검수 파이프라인의 1단이다:
 *   ① 검수자(sol/max)가 변경의 **설계·기능을 선파악**해 기능지도 + 업그레이드 제안을 낸다 (--제안)
 *   ② 클로드가 제안마다 채택/기각을 **판정**하고 장부에 남긴다 (--제안판정)
 *   ③ 채택이면 구현 후, 기각이면 원래 방향 그대로 → 최종 검수(버그 + 기능 전수 체크)로 간다
 *
 * ■ 제안은 **절대 배포를 막지 않는다.** 차단으로 만들면 codex 없는 폰 클라우드 경로가 통째로
 *   죽는다 — 「따를 수 없는 처방」의 재생산이다(F103). 제안 없음·제안 미판정은 게이트와 무관하다.
 * ■ 기각된 제안은 다음 제안 프롬프트에 「다시 내지 마라」로 실린다 — 지적 기각 이력과 같은 축
 *   (재제안 방지). 지적과 달리 이건 codex 쪽에서도 걸러진다: 제안 단계는 `exec`(커스텀 프롬프트
 *   가능)라 기각 이력을 **먹일 수 있다.** review 단계가 못 먹이는 것과 갈리는 지점(위 막다른 길). */

const 제안키 = (p) => {
  const norm = String(p.제목 || '').toLowerCase().replace(/\s+/g, ' ').trim();
  // 지적 키와 네임스페이스를 가른다('제안\0') — 같은 문구라도 지적 기각이 제안을 못 지우게.
  return crypto.createHash('sha256').update('제안\0' + norm).digest('hex').slice(0, 12);
};

/* 장부(제안됨→채택/기각 판정 누적)를 키별 최신 상태로 접는다.
 * 판정은 키에 대해 **영구**다 — 같은 제안이 다시 올라와도(재제안 행) 앞선 채택/기각을 지우지 않는다.
 * 지우면 기각의 뜻(다시 보지 않는다)이 사라진다. */
function 제안현황(경로) {
  const 상태 = new Map();
  for (const r of 장부읽기(경로 || 제안경로)) {
    if (!r.키) continue;
    if (r.종류 === '제안') {
      const 이전 = 상태.get(r.키);
      상태.set(r.키, { ...r, 상태: 이전 && 이전.상태 !== '제안됨' ? 이전.상태 : '제안됨', 사유: 이전 ? 이전.사유 : undefined });
    } else if (r.종류 === '판정' && 상태.has(r.키)) {
      상태.set(r.키, { ...상태.get(r.키), 상태: r.상태, 사유: r.사유 });
    }
  }
  return 상태;
}

/* 대상 diff 를 프롬프트에 **인라인**한다 — 에이전트가 스스로 git 을 돌리게 두면 무엇을 읽었는지
 * 확정할 수 없다. 너무 크면 통계+파일 목록으로 접고 「직접 읽어라」로 넘긴다(읽기 전용이라 안전). */
const 디프상한 = 180000;
function 디프수집(대상) {
  let d = '';
  if (대상.종류 === 'commit') d = 커밋읽기(대상.값);   // F578 — 머지면 combined diff 라 본문이 283자로 접힌다
  else if (대상.종류 === 'base') d = git(['-c', 'core.quotepath=false', 'diff', 대상.값 + '...HEAD']);
  else {
    d = git(['-c', 'core.quotepath=false', 'diff', 'HEAD']);
    // 미추적 파일은 diff 에 안 나온다 — 전문을 붙인다(새 파일이 제안 대상의 핵심인 경우가 많다)
    const 미추적 = git(['-c', 'core.quotepath=false', 'ls-files', '--others', '--exclude-standard']).split('\n').filter(Boolean);
    for (const f of 미추적) {
      try {
        const 본문 = fs.readFileSync(path.join(대상ROOT, f), 'utf8');
        d += `\n--- 미추적 새 파일: ${f} ---\n${본문.length > 40000 ? 본문.slice(0, 40000) + '\n…(잘림)' : 본문}`;
      } catch (_) { d += `\n--- 미추적 새 파일: ${f} (읽기 실패 — 직접 읽어라) ---`; }
    }
  }
  if (d.length > 디프상한) {
    return `(diff 가 ${d.length.toLocaleString()}자로 상한을 넘어 접었다 — 아래 파일들을 저장소에서 직접 읽어라)\n파일 목록:\n` +
      대상.파일들.map((f) => '  - ' + f).join('\n');
  }
  return d;
}

/* 앱의 방향 정본 — 유호님 확정 로드맵(2026-08-05 "gpt에도 내 계획을 알아야 할 것 같아" ·
 * 08-10 시기 표기가 「4개년」에서 「+6/18/24/28개월」로 개정됐다).
 * 검수자가 방향을 모르면 업그레이드 제안이 아무 데나 향한다 — 그래서 선파악·기능체크 프롬프트에
 * 매번 실린다. 파일이 없으면 **없다고 크게 말한다**(조용히 방향 없이 돌면 그게 미탐이다). */
const 방향경로 = path.join(ROOT, 'docs', '제품방향.md');
const 방향상한 = 6000;

/* 🔑 **싣는 범위는 «절 단위»다 — 전문을 뒤에서 자르지 않는다**(유호 픽 ㉡ 2026-08-17 · F549).
 *
 * 옛 판은 파일 전문을 읽고 상한을 넘으면 **뒤에서부터** 잘랐다. 그 파일의 마지막 절이
 * `## 설계 불변식`(2,492자 = 전체의 34%)이라, 검수자가 제안을 재는 데 **가장 필요한 절이
 * 첫 희생**이었다. 옛 주석도 그 위험을 알고 있었는데("뒤 = 최신 불변식이 첫 희생") 막지는
 * 못했다 — 아는 결함을 주석으로 적어 두는 것은 장치가 아니다.
 *
 * 실사고 2026-08-17: PR #50 이 이 상한을 세우고, PR #51(유호 확정 「엔진 로드맵 신설」)이 같은 날
 * 그 파일을 6,000 → 7,241자로 키웠다. 두 트랙이 서로를 못 봐서 **master 가 주인 없는 적색**이 됐고,
 * 남의 배포까지 막았다. 줄일 대상이 유호님 확정 문구라 기계가 못 고치는 자리이기도 했다.
 *
 * 그래서 고치는 축을 바꿨다 — **파일을 줄이는 게 아니라 싣는 것을 고른다.** 상한은 그대로다
 * (그 상한이 막으려던 것은 프롬프트 비대이고, 그건 여전히 유효하다).
 *   · 머리(H1 블록)는 **언제나** 싣는다 — 그게 나머지를 읽는 틀이다.
 *   · 나머지 절은 아래 우선순위로 채우고, **안 들어간 절은 이름을 밝힌다**(조용한 손실 금지).
 *   · 목록에 없는 새 절은 «버리지 않고» 맨 뒤로 간다 — 정본이 개정돼도 사라지지 않는다.
 * 🔑 이름으로 무는 이유: 유호님이 절을 새로 만들면 이 목록은 낡는데, 낡는 방향이 «맨 뒤»라
 *   안전하다. 반대로 순서를 파일 순서에 맡기면 새 절이 낡은 불변식을 밀어낸다(그게 이번 사고다). */
const 방향절순서 = ['설계 불변식', '로드맵', '핵심 등식', '코어 엔진', '출시'];

function 방향절나누기(t) {
  const 절들 = [];
  let 지금 = { 제목: '', 줄들: [] };
  for (const l of t.split(/\r?\n/)) {
    if (/^#{1,3}\s/.test(l)) { 절들.push(지금); 지금 = { 제목: l.replace(/^#+\s*/, '').trim(), 줄들: [l] }; }
    else 지금.줄들.push(l);
  }
  절들.push(지금);
  return 절들.map((s) => ({ 제목: s.제목, 본문: s.줄들.join('\n').trim() })).filter((s) => s.본문);
}

function 방향텍스트(경로 = 방향경로) { // 경로 인자 = 회귀 픽스처용(방향지문과 같은 축)
  let t;
  try {
    t = fs.readFileSync(경로, 'utf8').trim();
  } catch (_) {
    console.error('⚠ docs/제품방향.md 가 없다 — 검수자가 앱의 방향을 모른 채 제안한다(만들어라).');
    return '';
  }
  if (t.length <= 방향상한) return t;                     // 다 들어간다 — 고를 것이 없다

  const 절들 = 방향절나누기(t);
  /* 절이 하나뿐(제목 없는 덩어리)이면 고를 단위가 없다 — 옛 통로 그대로 뒤를 자른다.
   *  절 단위로 고르는 것이 **못 하는 자리**를 여기서 밝힌다(억지로 넓히면 문장 중간이 잘린다). */
  if (절들.length <= 1) {
    console.error(`⚠ docs/제품방향.md ${t.length.toLocaleString()}자 — 상한 ${방향상한.toLocaleString()}자 초과인데 절(##) 이 없어 뒤에서부터 잘랐다.`);
    return t.slice(0, 방향상한) + '\n…(상한 초과로 잘림 — docs/제품방향.md 에 절 제목을 두거나 압축하라)';
  }

  const 순위 = (제목) => {
    const i = 방향절순서.findIndex((k) => 제목.includes(k));
    return i === -1 ? 방향절순서.length : i;             // 모르는 절은 버리지 않고 맨 뒤로
  };
  const 머리 = 절들[0];
  const 나머지 = 절들.slice(1)
    .map((s, i) => ({ ...s, 문서순서: i }))
    .sort((a, b) => (순위(a.제목) - 순위(b.제목)) || (a.문서순서 - b.문서순서));

  const 실은것 = [머리.본문];
  const 뺀것 = [];
  let 길이 = 머리.본문.length;
  for (const s of 나머지) {
    const 더할길이 = 길이 + 2 + s.본문.length;           // '\n\n' 이음매
    if (더할길이 <= 방향상한) { 실은것.push(s.본문); 길이 = 더할길이; } else 뺀것.push(s.제목 || '(제목 없음)');
  }

  /* 뺀 사실은 **양쪽에 낸다** — 프롬프트 본문의 경고는 검수자만 보고, stderr 는 운영자만 본다. */
  console.error(`⚠ docs/제품방향.md ${t.length.toLocaleString()}자 — 상한 ${방향상한.toLocaleString()}자라 절 ${뺀것.length}개를 뺐다: ${뺀것.join(' · ')}`);
  return 실은것.join('\n\n')
    + `\n\n…(상한 ${방향상한.toLocaleString()}자를 넘어 이 절들은 안 실렸다 — ${뺀것.join(' · ')})`;
}
const 방향블록 = (방향) => (방향 ? `\n앱의 방향 (유호님 확정 — 제안과 판정은 이 방향에 복무해야 하고, 어긋나는 제안은 내지 마라):\n${방향}\n` : '');

/* ── 판단 정본 게이트 (2026-08-12 · 유호님 질문 「gpt도 내 철학 정본을 읽고 의도를 파악하고 있나」)
 *
 * 답은 **아니다**였다. 실측: 이 파일 전문에 `철학`·`SYNK_철학` 0건 — 검수자·심문자가 매번 받는
 * 정본은 `docs/제품방향.md` **하나**뿐이었다. 「똑똑하게」 3층으로 대조하면 ②엔진은 방향 불변식
 * 5·6 으로 잘 실렸고 ③운영은 불변식 3 으로 반쪽인데, **①기본(재미 + 실사용 한국어 도움 + 신선)은
 * 0**이고 궁극 가치(삶 파악 → 스스로 찾게 → 학생별 로드맵)도 0이었다. 그래서 구조적으로 못 잡는
 * 지적이 있었다 — 「이 설계가 수집엔 완벽한데 학생에겐 재미없다」.
 *
 * 🔴 더 나쁜 자리: 검수자가 읽는 그 유일한 정본이 *"화면·게임화는 그 수집기를 매일 돌게 하는
 *   엔진이지 목적이 아니다"*(docs/제품방향.md)라고 가르친다 — 재미 축 제안을 낼 이유가 구조적으로
 *   없고 **깎을 근거는 있다.** 그래서 블록에 **서열 한 줄**을 박는다(철학블록). 안 박으면 모델은
 *   두 정본을 못 가르고, 갈리는 자리에서 언제나 방향이 이긴다.
 *
 * 🔑 문구를 여기 베끼지 않는다 — 정본은 하루에 세 번 개정된다(v1.1→v1.4). 사본은 반드시 갈라지고,
 *   갈린 쪽은 낡은 기준으로 판정하면서 초록을 본다. 뽑는 일은 이미 `philosophy-card.js` 가
 *   앵커·실패 처리까지 갖춰 하고 있으므로 그 **추출기를 그대로 가져다 쓴다**(사본 금지).
 * 🔑 전문(23,281자 · 08-12 측정)을 싣지 않는 이유는 방향상한과 같다 — 판정을 가르는 자리만 싣는다. */
const 철학경로 = path.join(ROOT, 'docs', 'SYNK_철학.md');
const 철학카드경로 = path.join(ROOT, '.claude', 'hooks', 'philosophy-card.js');
const 철학상한 = 4000;

/* 카드와 **같은 자리**를 뽑는다 — 목록이 갈리면 세션이 보는 기준과 검수자가 보는 기준이 갈린다.
 * 앵커는 정본의 구조 그 자체다: 절이 바뀌면 여기서 빨개져야 한다(실정본 회귀가 그걸 잰다). */
function 철학자리(md, 카드) {
  return [
    ['궁극 가치', 카드.뽑기(md, /^\*\*한 문장:/, false)],
    ['「똑똑하게」 4층 = 산출물 게이트', 카드.뽑기(md, /^\*\*3\. 「똑똑하게」/, true)],
    ['하지 않는 것 셋', 카드.인용뽑기(md, /^>\s*\*\*그리고 우리가 하지 않는 것 셋/)],
    ['적용 대상 (학생 접점 / 배관)', 카드.뽑기(md, /^⚠\*\*적용 대상을 가른다/, false)],
    ['이해 3층', 카드.목록뽑기(md, /^\*\*「이해」는 세 층이다/)],
  ];
}

/* 못 뽑은 자리는 **조용히 빠지지 않는다** — 빠진 채 도는 심문은 「지적 없음」과 같은 모양이 된다.
 * 경고를 stderr 뿐 아니라 **블록 본문**에도 박는 이유: 심문 결과는 파일로 남고 나중에 그것만 읽는데,
 * stderr 는 그 파일에 안 남는다(방향상한 절단 경고와 같은 축). */
/* 경고에는 **실제로 읽은 자리**를 적는다 — 파일명을 상수로 박으면 픽스처가 낸 경보와 진짜 경보가
 *   CI 출력에서 같은 모양이 된다(실측 08-15: 아래 「반쪽」 픽스처 검사가 stderr 로 실정본 이름을
 *   외쳤고, 그걸 읽은 세션이 정본 절 구조가 깨진 줄 알고 되짚었다 — 정본은 멀쩡했다 · F174 모양).
 * 🔑 repo 안이면 상대 경로라 **정상 경보의 문구는 예전 그대로** `docs/SYNK_철학.md` 다 — 바뀌는 것은
 *   저장소 밖(임시 픽스처) 뿐이라, 진짜 경보를 알아보던 눈은 그대로 두고 가짜만 갈라 낸다. */
function 읽은자리(경로) {
  const rel = path.relative(ROOT, 경로);
  return rel && !rel.startsWith('..') && !path.isAbsolute(rel) ? rel.split(path.sep).join('/') : 경로;
}

function 철학텍스트(경로 = 철학경로, 카드경로 = 철학카드경로) {
  let md;
  try { md = fs.readFileSync(경로, 'utf8'); }
  catch (_) {
    console.error(`⚠ ${읽은자리(경로)} 가 없다 — 검수자·심문자가 **판단 기준 없이** 본다(만들어라).`);
    return '';
  }
  let 카드;
  try { 카드 = require(카드경로); }
  catch (e) {
    console.error(`⚠ 철학 추출기를 못 읽었다(${e.message}) — 게이트가 안 실린다: ${카드경로}`);
    return '';
  }
  const 자리 = 철학자리(md, 카드);
  const 빠진것 = 자리.filter(([, v]) => !v).map(([n]) => n);
  if (빠진것.length) {
    console.error(`⚠ ${읽은자리(경로)} 에서 게이트 자리를 못 뽑았다: ${빠진것.join(' · ')}`
      + ' — 절 구조가 바뀌었다(앵커를 고쳐라). 지금 검수는 반쪽 기준으로 돈다.');
  }
  const 본문 = 자리.filter(([, v]) => v).map(([n, v]) => `[${n}] ${v}`).join('\n');
  if (!본문) return '';
  const 경고 = 빠진것.length ? `\n⚠ 이 게이트는 **반쪽이다** — 못 뽑은 자리: ${빠진것.join(' · ')}(정본 절 구조 변경). 판정에 참고하라.` : '';
  if (본문.length > 철학상한) {
    console.error(`⚠ 철학 게이트 ${본문.length.toLocaleString()}자 — 상한 ${철학상한.toLocaleString()}자 초과로 잘린다.`);
    return `${본문.slice(0, 철학상한)}\n…(상한 초과로 잘림 — docs/SYNK_철학.md 의 게이트 절을 압축하라)${경고}`;
  }
  return 본문 + 경고;
}

/* 🔑 **서열**이 이 블록의 절반이다 — 위 🔴 참조. 「상위」라고만 하면 모델이 둘을 나란히 놓으므로
 *   무엇이 무엇인지(기준 vs 실행 계획)와 갈릴 때 누가 이기는지를 같은 줄에 적는다. */
const 철학블록 = (철학) => (철학 ? `\n판단 정본 — docs/SYNK_철학.md (유호님 확정 · **아래 「앱의 방향」보다 상위다**):
방향은 *무엇을 언제 짓는가*의 실행 계획이고, 이것은 *그 산출물이 좋은가*를 가르는 기준이다.
둘이 갈리면 **이쪽이 이긴다** — 방향 문서에 「게임화는 목적이 아니다」류의 문장이 있어도
그것은 우선순위 서술이지 ①기본 게이트(재미·실사용 한국어 도움·신선)의 면제가 아니다.
${철학}
` : '');

/* 그 판정이 **어느 판단 기준 아래서** 내려졌는지 — 방향지문(:아래)과 같은 축이고 이유도 같다.
 * 정본이 개정되면 「그때 왜 그렇게 판정했나」의 전제가 사라지고, 행에 표시가 없으면 복원할 방법이
 * 없다. 지문 대상은 **파일 전문**이다(프롬프트에 실린 발췌가 아니라) — 판정의 전제는 정본이고,
 * 발췌가 반쪽인 것은 그 자체로 따로 경고하는 별개의 결함이다(철학텍스트). */
function 철학지문(경로 = 철학경로) {
  try {
    return crypto.createHash('sha256').update(fs.readFileSync(경로)).digest('hex').slice(0, 12);
  } catch (_) { return '없음'; }
}

/* 그 판정이 **어느 방향 아래서** 내려졌는지 — 장부 행마다 방향 정본의 지문을 박는다.
 *
 * 왜 (제안 61d775a5b85d 채택분 · 2026-08-05): 방향 정본은 유호님 지시로 개정된다.
 *   개정되고 나면 「이 제안을 그때 왜 채택했나」의 전제가 사라지는데, 행에 아무 표시가 없으면
 *   **나중에는 복원할 방법이 없다.** 시각으로 역추적하려면 그 파일의 커밋 이력을 뒤져야 하고,
 *   그건 장부가 스스로 답하지 못한다는 뜻이다. 소급이 안 되는 종류라 **쓰는 시점에** 박는다.
 *   (같은 이유로 모델·효력을 남긴다 — 바로 아래 검수기록 주석과 같은 축이다.)
 *
 * ⚠ 지문 대상은 **파일 전문**이다(프롬프트에 실린 잘린 텍스트가 아니라). 판정의 전제는 정본이고,
 *   잘림은 그 자체로 따로 경고하는 별개의 결함이다(방향상한).
 * ⚠ 파일이 없으면 조용히 비우지 않고 '없음' 을 박는다 — 방향 없이 돈 것과 그냥 안 적힌 것이
 *   같은 모양이면 안 된다(이 저장소가 반복해 밟은 형태).
 * 🔑 경로를 **인자**로 받는다(env 이음매가 아니라) — env 로 두면 운영에서도 방향 정본을 조용히
 *   갈아끼울 수 있는 구멍이 된다. 회귀는 인자로 픽스처를 넣어 없는 파일 가지까지 본다. */
function 방향지문(경로 = 방향경로) {
  try {
    return crypto.createHash('sha256').update(fs.readFileSync(경로)).digest('hex').slice(0, 12);
  } catch (_) { return '없음'; }
}

/* 변경지문(= 제안 61d775a5b85d 이 말한 change_id) — 이 행이 **어느 변경**에 대한 것인가.
 *
 * 왜 대상칸으로 부족한가: 대상은 `commit sha` 이거나 `(미커밋)` 인데, 후자는 **모든 미커밋 회차가
 *   같은 문자열**이다. 그래서 선파악과 최종 체크가 같은 내용을 본 것인지 장부가 스스로 못 말한다.
 *   내용 해시로 걸면 한 바이트만 달라도 갈리고, 같은 내용이면 커밋 전후로도 이어진다
 *   (이 저장소가 배포 게이트를 커밋 메시지가 아니라 내용 지문으로 거는 것과 같은 축).
 * 🔑 **디프 텍스트를 인자로 받는다** — 안에서 git 을 다시 돌리면 ①비용이 두 배고 ②프롬프트에
 *   실린 것과 지문이 갈릴 수 있다. 실제로 검수자에게 보낸 그 바이트를 그대로 건다.
 * 채택 범위 밖(구현 링크·계보 필터·legacy 호환)은 **짓지 않았다** — 판정문이 명시적으로 잘라냈다. */
function 변경지문(diff텍스트) {
  return crypto.createHash('sha256').update(String(diff텍스트 || '')).digest('hex').slice(0, 12);
}

/* 이 변경(변경지문)에 대해 **선파악이 그린 기능지도**. 없으면 null — 「지도가 없다」와
 * 「지도는 있는데 미확인 0건」이 같은 모양이면 안 된다(이 저장소가 반복해 밟은 형태). */
function 선파악지도(변경fp, 경로) {
  const 행들 = 장부읽기(경로 || 제안경로).filter((r) => r.종류 === '기능지도' && r.변경 === 변경fp);
  return 행들.length ? (행들[행들.length - 1].기능지도 || []) : null;
}

/* 폐루프 대조(제안 590c00590105 채택분) — 선파악이 알던 기능 중 최종 전수 체크가 **안 짚은** 것.
 *
 * 채택 범위 그대로: ①미매칭은 **알림(미확인)이지 차단이 아니다** — 이름 흔들림에서 오는 거짓
 *   미확인이 곧 가드를 끄게 만든다. 그래서 지적으로 변환하지 않는다(게이트에 안 닿는다).
 *   ②안정 기능 ID 규칙은 **아직 안 정한다** — 판정문이 "이름 표기가 두 패스 사이에서 얼마나
 *   흔들리는지 재고 나서" 를 조건으로 걸었고, 오늘 장부에는 두 패스가 같은 대상에 붙은 쌍이
 *   **0건**이라 잴 재료 자체가 없다. 이 함수의 출력이 곧 그 실측이다 — 공백·대소문자만 눌러
 *   맞춰보고 남는 것이 「흔들림」의 실제 크기다. 쌓이면 그때 ID 규칙을 정한다.
 *
 * ⚠ 알려진 천장: 짝은 **변경지문이 같을 때만** 맞는다. 채택 제안을 구현하면 diff 가 커져
 *   지문이 갈리므로, 그 경로에서는 짝이 없어 `null`(대조 안 함)로 나온다 — 전건 기각 경로에서만
 *   자동으로 맞는다. 구현 후에도 대조하려면 **`--제안` 을 한 번 더 돌려** 지금 트리의 지도를
 *   만들면 된다(콘솔이 그렇게 안내한다). 대상칸으로 느슨하게 짝짓지 않은 이유는 `(미커밋)` 이
 *   모든 회차에서 같은 문자열이라 **남의 변경 지도와 조용히 짝지어지기** 때문이다. */
const 기능이름 = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
function 미확인기능들(기능지도, 체크) {
  const 짚음 = new Set((체크 || []).map((c) => 기능이름(c.기능)));
  return (기능지도 || []).map((f) => f.기능).filter((n) => !짚음.has(기능이름(n)));
}

/* 선파악이 장부에 쓸 행들을 만든다 — **순수 함수**라 codex 호출 없이 검사할 수 있다.
 *
 * 왜 갈라냈나 (2026-08-05): 방향 스탬프를 넣고 변이 시험을 돌리니 기능지도·제안 행에서 스탬프를
 *   통째로 빼도 **28건이 전부 초록**이었다 — 그 행은 실제 codex 호출로만 쓰여서 어떤 검사도
 *   닿지 않았다. 「검사할 수 없는 자리」는 곧 조용히 새는 자리다. append 옆에 있던 조립을
 *   여기로 옮겨 회귀가 직접 부른다(실행 경로는 그대로 이 함수를 쓴다 — 사본이 아니다). */
function 선파악행들(대상, 결과, 현황, now, 방향fp = 방향지문(), 변경fp = null, 철학fp = 철학지문()) {
  const 대상칸 = { 종류: 대상.종류, 값: 대상.값 };
  const 기록행들 = [
    { 종류: '기능지도', 시각: now, 대상: 대상칸, 방향: 방향fp, 철학: 철학fp, 변경: 변경fp, 기능지도: 결과.기능지도 || [], 학습데이터: 결과.학습데이터 || [] },
  ];
  const 신규 = [];
  for (const p of 결과.제안 || []) {
    const k = 제안키(p);
    const 이전 = 현황.get(k);
    if (이전 && 이전.상태 === '기각') continue;        // 기각된 것은 내 앞에 다시 오지 않는다
    if (이전 && 이전.상태 === '채택') continue;        // 이미 채택된 것도 — 구현 몫이지 재판정 몫이 아니다
    기록행들.push({ 종류: '제안', 시각: now, 대상: 대상칸, 방향: 방향fp, 철학: 철학fp, 변경: 변경fp, 키: k, ...p });
    신규.push({ ...p, 키: k });
  }
  return { 기록행들, 신규 };
}

/* 학습데이터 영향 계약(제안 16967d287d18 채택분) — 이 변경이 3·4년차 학습 코퍼스에 무엇을 남기는가.
 *
 * 채택 범위 그대로 **데이터 경로를 건드리는 기능에만** 요구한다. 08-04 실측: 선파악 기능지도
 *   36항목 중 학습데이터를 만드는 기능은 **0건**이었다 — 전 항목에 5필드를 필수로 걸면 회차마다
 *   180개의 「없음」 선언이 생기고, 그 노이즈가 곧 검사를 끄게 만든다(F049 계열).
 *   그래서 기능마다 붙이는 필드가 아니라 **해당 기능만 담는 별도 배열**로 냈다 — 해당 없으면
 *   빈 배열이고, 그때 이 계약은 출력에 한 글자도 차지하지 않는다.
 * ⚠ 이 판정은 검수자 LLM 의 **추측**이다 — 그래서 지적으로 변환하지 않는다(차단이 아니라 알림). */
const 학습데이터지시 = `데이터 경로를 건드리는 기능만 골라 계약을 적어라 — 수집·시트 스키마·학생 산출물.
   그런 기능이 하나도 없으면 **빈 배열**이 옳은 답이다. 기능마다 「없음」을 적지 마라.`;

function 제안프롬프트(diff텍스트, 기각제목들, 방향, 철학) {
  return `당신은 SYNK 저장소의 이종 검수자다. 지금은 **설계 선파악 단계**다 — 버그를 찾지 마라(그건 다음 단계다).
아래 변경의 설계와 기능을 정밀히 파악한 뒤 세 가지를 내라:

1) 기능지도 — 이 변경이 새로 만들거나 바꾸는 기능 **전부**. 빠뜨리지 마라 — 최종 검수가 이 지도로 전수 체크한다.
2) 학습데이터 — ${학습데이터지시}
3) 업그레이드 제안 — 이 변경을 기능적으로 한 단계 올릴 **구체적** 제안. 실제로 값어치 있는 것만 —
   억지 제안·장식을 위한 장식 금지. 진짜 없으면 빈 배열이 옳은 답이다.
   각 제안의 크기: 소=1시간 내 · 중=반나절 · 대=하루 이상 또는 방향 전환.
   ⚠ 이 변경이 **학생·학부모가 닿는 것**(기능·콘텐츠·화면·알림)이면 아래 ①기본 게이트로도 재라 —
   「수집엔 완벽한데 학생에겐 재미없다」는 이 저장소가 지금까지 한 번도 못 잡던 지적이다.
   배관(계약·마이그레이션·훅·가드·배포 도구)이면 ①을 묻지 마라(아래 「적용 대상」).
${철학블록(철학)}${방향블록(방향)}
${기각제목들.length ? `이미 기각된 제안 — **같은 것을 다시 내지 마라**:\n${기각제목들.map((t) => '  · ' + t).join('\n')}\n` : ''}
--- 변경 내용 ---
${diff텍스트}`;
}

/* ── ② 「이 저장소가 이미 아는 미완」 (2026-08-17)
 * 🔑 실측이 과녁을 댔다: 기각 81건 중 **66건(81%)이 기능체크**였고, 그 오판의 결이 하나로 일정하다 —
 *   검수자가 «저장소가 스스로 미완이라고 적어둔 칸»을 새 결함으로 집는다. 장부의 사유가 그대로 말한다:
 *     "인용된 완결 3칸 표가 ✗ 인 것은 그 트랙이 자기 미착지분을 **정직하게 적은 칸**이다"
 *     "이해 대장은 이 빈칸을 감추는 문서가 아니라 **드러내려고 만든 계기판**이다"
 *   즉 검수자가 나쁜 게 아니라 **입력이 빠졌다** — 이 저장소가 미완을 정직하게 장부에 적는 곳이라는
 *   사실을 모른다. 그래서 그 장부를 프롬프트에 함께 준다.
 * ⚠ 「올리지 마라」가 아니라 **「어떻게 다른지 대라」**인 이유: 억제하면 진짜 결함이 그 목록에 겹칠 때
 *   함께 가려진다(가드 맹점 ④ — 맞는 얼굴로 틀린 값). 말하게 하면 겹쳐도 근거가 남는다.
 * ⚠ 이 재료는 **런 시점에 기계로** 뽑는다 — 손으로 적으면 낡고, 낡은 목록은 검수자를 침묵시킨다.
 * ⚠ 상한을 씌우되 **잘린 것을 밝힌다**(no silent caps) — 조용히 자르면 「전부 줬다」로 읽힌다. */
/* ── 재료는 **저장소마다 다르다** (2026-08-31 · talk 첫 런이 스스로 낸 구멍)
 * 🔴 실측(런 `검수-2026-08-31T0840-6b9bbf`): talk 첫 이종 검수의 지적 **3건이 전부** 「저장소가
 *   스스로 미완이라고 적어 둔 칸」이었다 — 이 블록이 막으려던 바로 그 무늬다. 까닭은 재료가
 *   `gh pr list` **하나**였기 때문이다. 그건 이 집의 규약이고(유호 확정 08-15 「PR = 작업 목록」),
 *   talk 은 열린 PR 이 **0개**다(실측). 그래서 블록이 통째로 안 실렸는데, 로그는 「열린 트랙 0개」
 *   라고 적어 **「미완이 없다」처럼** 보였다 — 없는 것과 «출처가 다른 것»이 같은 모양이었다.
 *
 * 🔑 그런데 재료를 «목록»으로 통일할 수는 없다. talk 은 미완을 목록이 아니라 **산출물 안에
 *   인라인으로** 선언한다(빈 측정란 · 「추정값」·「미측정」 주석 · 해소된 것은 ~~취소선~~).
 *   긁어 모으는 자는 실측으로 **못 쓴다**: `남은 것 =` 4건(그중 3건이 이미 취소선) · `🔴` 342건
 *   (미완 표식이 아니라 그냥 강조). 억지로 긁으면 낡고 틀린 목록이 되고, 낡은 목록은 검수자를
 *   **틀리게** 침묵시킨다 — 이 블록이 지금 내는 값보다 나쁘다.
 * → 그래서 재료를 두 **종류**로 가른다:
 *     `목록` = 긁어 온다(이 집의 열린 PR).
 *     `규약` = 「이 저장소는 미완을 어떻게 선언하나」를 말해 준다 + 큐레이션된 관문만 싣는다.
 * ⚠ 모르는 저장소는 «빈 목록»이 아니라 **«출처 없음»**이다 — 둘이 같은 모양이면 다음 저장소가
 *   붙는 날 같은 사고가 조용히 되풀이된다(0건이 성공 얼굴).
 * ⏭ 더 옳은 자리는 **저장소가 스스로 선언하는 것**이다(그러면 여기가 안 낡는다). 그건 talk 커밋이
 *   필요해 이 판에 안 넣었다 — 대신 아래 표가 낡으면 «크게» 말하게 해 두었다. */
const 아는미완출처들 = {
  // 집 — 유호 확정 08-15. 보드 층을 걷은 뒤 「지금 열린 트랙」의 정본은 PR 이다(위임 2단계 08-20).
  '': { 종류: '목록', 이름: '열린 PR', 재검법: 'gh pr list' },
  /* SYNK-talk — 열린 PR 을 안 쓴다(실측 08-31 = 0개). 「다음 관문」만 큐레이션돼 있고 나머지
   * 미완은 문서·주석 안에 인라인으로 산다. 그래서 목록이 아니라 **읽는 법**을 준다. */
  'SYNK-talk': {
    종류: '규약', 이름: 'README 「다음 관문」 + 인라인 선언',
    관문파일: 'README.md', 관문절: '다음 관문', 재검법: 'README.md 의 「다음 관문」 절',
    선언법: [
      '`~~취소선~~`·`✅` = **이미 해소된 것**이다 — 그걸 미완으로 읽지 마라(거꾸로 된 지적이 된다).',
      '설계 문서의 **빈 표·빈 측정란**은 빠뜨린 것이 아니라 「아직 안 쟀다」를 드러내는 칸이다.',
      '코드 주석이 스스로 「추정값」·「미측정」·「실기기 전 초기값」이라 적은 상수는 **정직한 선언**이다.',
    ],
  },
};

/** 이 저장소의 미완 재료가 무엇인가 — 모르면 `null`(빈 목록이 아니다). */
function 아는미완출처(표) {
  const k = 표 === undefined ? 이저장소표() : 표;
  return Object.prototype.hasOwnProperty.call(아는미완출처들, k) ? { ...아는미완출처들[k], 저장소: k } : null;
}

/** 마크다운 문서에서 `## <절 이름>` 한 절을 떼어 온다(다음 `## ` 앞까지). 없으면 `[]`. */
function 절줄들(절대경로, 절이름, 상한, 칸상한, 자르기) {
  let 본문 = '';
  try { 본문 = fs.readFileSync(절대경로, 'utf8'); } catch (_) { return null; }
  const 줄 = 본문.split(/\r?\n/);
  const i = 줄.findIndex((l) => /^##\s/.test(l) && l.includes(절이름));
  if (i === -1) return null;
  const 끝 = 줄.findIndex((l, j) => j > i && /^##\s/.test(l));
  return 줄.slice(i + 1, 끝 === -1 ? 줄.length : 끝)
    .map((l) => l.trim()).filter(Boolean)
    .slice(0, 상한).map((l) => '  · ' + 자르기(l, 칸상한));
}

function 아는미완줄들(상한 = 24, 칸상한 = 100) {
  const 자르기 = (s, n) => (s.length > n ? s.slice(0, n) + '…' : s);
  const 출처 = 아는미완출처();
  /* 🔴 모르는 저장소 — 여기서 «빈 목록»을 내면 블록이 안 실리고, 그건 검수자에게
   *   「이 저장소엔 미완이 없다」로 읽힌다. 출처를 그대로 `null` 로 얹어 위층이 크게 말하게 한다. */
  if (!출처) return { 줄들: [], 전체: 0, 출처: null };

  if (출처.종류 === '규약') {
    const 절 = 절줄들(path.join(대상ROOT, 출처.관문파일), 출처.관문절, 상한, 칸상한, 자르기);
    /* 절을 못 찾은 것과 「관문이 0개」는 다르다 — 앞은 이 표가 낡았다는 뜻이라 사유로 낸다. */
    if (절 === null) {
      return { 줄들: [], 전체: 0, 출처, 오류: `${출처.관문파일} 에서 「${출처.관문절}」 절을 못 찾았다 — 이 도구의 재료 표가 낡았다` };
    }
    return { 줄들: 절, 전체: 절.length, 출처 };
  }

  try {
    /* cwd 는 **재는 저장소**다 — 「이 저장소가 이미 아는 미완」이라 말하면서 남의 열린 PR 을
     * 실으면 검수자가 없는 트랙을 근거로 지적을 접는다(면죄부가 거꾸로 선다). */
    const 원 = execFileSync('gh', ['pr', 'list', '--state', 'open', '--json', 'number,title,body'],
      자식옵션({ cwd: 대상ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 30000 }));
    const 목록 = JSON.parse(String(원 || '[]').trim() || '[]');
    const 줄들 = 목록.map((p) => {
      const 첫줄 = String(p.body || '').split(/\r?\n/).map((l) => l.trim()).find((l) => l && !l.startsWith('**지문**')) || '(본문 없음)';
      return `  · #${p.number} ${자르기(String(p.title || ''), 칸상한)}\n      상태: ${자르기(첫줄, 칸상한)}`;
    });
    return { 줄들: 줄들.slice(-상한), 전체: 줄들.length, 출처 };
  } catch (e) {
    /* 재료를 못 읽는 것이 검수를 막을 이유는 아니다 — 없으면 블록이 안 실릴 뿐이다(안전한 방향).
     * ⚠ `gh` 인증이 끊겨도 여기로 온다 — 「열린 트랙 0」이 아니라 **못 읽었다**이고, 그 사유는 아래로 나간다. */
    return { 줄들: [], 전체: 0, 출처, 오류: String((e && e.message) || e) };
  }
}

/* 🔴 재료가 «없을» 때 침묵하면, 그 침묵은 검수자에게 **「이 저장소엔 미완이 없다」**로 읽힌다.
 *   08-31 talk 첫 런이 정확히 그 모양이었다(지적 3건 전부 자기선언 칸). 그래서 「0줄」을 셋으로
 *   가른다 — ⓐ출처를 모른다 ⓑ출처는 아는데 못 읽었다 ⓒ출처를 읽었는데 정말 0건.
 * ⚠ 셋 다 **말은 한다**(블록을 낸다). 다만 없는 목록을 지어내지는 않는다 — 파는 것은 목록이
 *   아니라 「이 침묵을 미완 없음으로 읽지 마라」는 한 줄이다. */
function 아는미완빈블록(미완) {
  const 출처 = 미완 && 미완.출처;
  const 머리 = !출처
    ? `⚠ **이 저장소가 미완을 어디에 적는지 이 도구가 모른다** — 재료를 못 실었다.`
    : 미완.오류
      ? `⚠ **이 저장소의 미완 재료(${출처.이름})를 못 읽었다** — ${미완.오류}`
      : `ℹ 이 저장소의 미완 재료(${출처.이름})를 읽었고 **정말 0건**이었다.`;
  return `${머리}
🔴 **그러니 이 침묵을 「이 저장소엔 미완이 없다」로 읽지 마라.** 저장소는 미완을 여러 모양으로
   적는다 — 빈 표·빈 측정란, 「추정값」·「미측정」이라 스스로 밝힌 상수, ~~취소선~~(=해소됨),
   설계 문서 머리글의 미착지 표기. **그건 빠뜨린 것이 아니라 드러내려고 적은 칸이다.**
   그런 칸을 «새로 발견한 결함»으로 올리지 마라 — 그건 발견이 아니라 옮겨 적기다.
   그래도 올릴 값이 있으면 근거에 **그 선언과 이번 diff 가 어떻게 어긋나는지** 한 줄로 대라.
⚠ 반대로 이번 diff 가 **실제로 깨뜨린 것**이면 무엇이라 적혀 있든 그대로 올려라 — 면죄부가 아니다.
`;
}

function 아는미완블록(미완) {
  if (!미완) return '';
  /* 출처 칸이 아예 없는 옛 모양은 예전 그대로 «빈 문자열»이다 — 이 함수를 직접 부르는 자리(회귀)가
   * 「재료가 없으면 블록을 지어내지 않는다」를 붙들고 있고, 그 뜻은 지금도 옳다. 새 동작은
   * **출처를 명시한 호출**에만 붙는다(한 함수가 두 계약을 지되, 가르는 축을 값으로 둔다). */
  if (!미완.줄들.length) return Object.prototype.hasOwnProperty.call(미완, '출처') ? 아는미완빈블록(미완) : '';

  /* 규약형 — 목록이 아니라 «읽는 법»이 재료다(talk). 큐레이션된 관문만 싣고 나머지는 규칙으로 준다. */
  const 출처 = 미완.출처;
  if (출처 && 출처.종류 === '규약') {
    return `이 저장소는 **미완을 산출물 «안»에 정직하게 선언한다** — 목록이 아니라 그 자리에 적는다.
${(출처.선언법 || []).map((s) => '  · ' + s).join('\n')}
⚠ **그렇게 선언된 칸을 «새로 발견한 결함»으로 올리지 마라.** 그건 발견이 아니라 옮겨 적기다.
   그래도 올릴 값이 있다고 보면 근거에 **그 선언과 이번 diff 가 어떻게 어긋나는지** 한 줄로 대라
   (예: 「주석은 60이 추정값이라 적었는데, 이번 diff 는 그 값을 이미 잰 것처럼 계약에 박았다」).
⚠ 반대로, 이번 diff 가 **실제로 깨뜨린 것**이면 무엇이라 적혀 있든 그대로 올려라 — 면죄부가 아니다.
그리고 아래는 이 저장소가 큐레이션해 둔 「다음 관문」이다(${출처.관문파일} · ~~취소선~~·✅ = 이미 해소):
${미완.줄들.join('\n')}
`;
  }

  const 잘림 = 미완.전체 > 미완.줄들.length
    ? `
(열린 트랙 ${미완.전체}개 중 최근 ${미완.줄들.length}개만 실었다 — 나머지는 gh pr list 로 본다)` : '';
  /* 이 집에만 있는 계기판을 형제 저장소 검수에 실으면 **없는 파일을 근거로 대라**는 말이 된다 —
   * 검수자는 그 줄을 못 찾고, 못 찾은 지시는 블록 전체의 신뢰를 깎는다(낡은 참조와 같은 축). */
  const 집계기판 = 타저장소() ? '' : `
그리고 \`docs/이해대장.html\` 은 「이해 12칸 중 무엇이 비었나」를 **드러내려고** 만든 계기판이고,
설계 문서들은 머리글에 스스로 「N/M 착지」·완결 3칸(모였나/닿았나/늘었나 = ✓/✗)을 적는다.`;
  return `이 저장소는 **미완을 장부에 정직하게 적어 둔다** — 아래는 지금 열려 있는 트랙과 그 상태다.${집계기판}
⚠ **거기 이미 적힌 미완을 «새로 발견한 결함»으로 올리지 마라.** 그건 발견이 아니라 옮겨 적기다.
   그래도 올릴 값이 있다고 보면 근거에 **아래 어느 줄과 어떻게 다른지** 한 줄로 대라
   (예: 「열린 PR 은 A 를 미완이라 적었는데, 이번 diff 는 B 를 이미 도는 것처럼 배선했다」).
⚠ 반대로, 이번 diff 가 **실제로 깨뜨린 것**이면 장부에 뭐라 적혀 있든 그대로 올려라 — 이 블록은
   면죄부가 아니다.
${미완.줄들.join('\n')}${잘림}
`;
}

/* ── ③ 회차 렌즈 (2026-08-17)
 * 🔑 옛 판의 2회차는 **같은 프롬프트 재추첨**이었다. 실측: 다회차 런 43개 중 **25개(58%)에서 2회차가
 *   새 지적을 0건** 냈다(겹침률 22.6% 이므로 값은 했다 — 다만 절반 넘게 헛돈다).
 * 🔑 그래서 회차마다 **각도를 가른다** — 주사위를 다시 굴리는 대신 다른 자리에서 출발시킨다.
 * ⚠ 이 파일 `입력쓰기` 주석이 경고하는 그 자리다 — 「회차마다 다른 질문을 던지면 합쳐 읽는 순간
 *   회차 대조가 원리상 무효다(F281)」. 그 경고는 **실수로** 갈리는 것을 막으려는 것이고, 여기서는
 *   의도적으로 가른다. 무효가 되지 않게 하는 값은 하나다 — **렌즈를 장부에 적는다**(런 행의 `기능렌즈`).
 *   조건이 갈린 채로도 «무엇이 갈렸는지» 적혀 있으면 대조가 판정을 낼 수 있다.
 * 🔴 그래서 이 회차 이후의 원건 수를 **앞 회차와 직접 빼지 마라**(F281) — 분모가 또 바뀌었다.
 * ⚠ 검수(버그) 단계에는 이 렌즈를 못 건다 — `codex exec review` 는 커스텀 프롬프트를 원리상 못
 *   받는다(위 ⛔막다른 길). 렌즈가 닿는 것은 `exec` 를 쓰는 기능체크뿐이다. */
const 기능렌즈들 = [
  { 이름: '전면', 지시: '' },
  { 이름: '바뀐-바이트',
    지시: `⚠ 이번 회차는 **다른 각도**다(앞 회차가 넓게 훑는다 — 그것을 반복하지 마라).
너는 이번 diff 가 **실제로 바꾼 줄**이 직접 깨뜨리는 것만 본다:
  · 회귀 — 전에 되던 것이 이 변경으로 안 되게 됐나(옛 호출부·옛 인자·옛 파일 모양)
  · 경계 — 빈 배열·null·0건·첫 실행·동시 실행에서 이 코드가 어떻게 되나
  · 어긋남 — 정의부와 호출부, 스키마와 쓰는 쪽, 상수 목록과 그것을 읽는 쪽
  · 계약 — 이 변경이 남과 주고받기로 한 모양(필드명·종료코드·파일 형식)을 깼나
설계·문서가 「아직 미완」이라고 스스로 적어 둔 것은 **이 회차의 대상이 아니다**.` },
];
const 기능렌즈 = (i) => 기능렌즈들[Math.min(Math.max(i, 1), 기능렌즈들.length) - 1];

function 기능체크프롬프트(diff텍스트, 채택제안들, 방향, 철학, 렌즈, 미완) {
  const L = 렌즈 || 기능렌즈들[0];
  return `당신은 SYNK 저장소의 이종 검수자다. 지금은 **기능 전수 체크 단계**다 — 방금 구현이 끝난 변경이다.
아래 변경이 만들거나 바꾸는 기능을 **하나도 빠짐없이** 스스로 나열하고, 각각 실제로 그 일을 하는지 판정하라
(정상 / 의심 / 깨짐 + 코드 근거). 목록은 diff 에서 직접 뽑아라 — 남이 준 목록을 믿지 말고 전수를 다시 세라.
방향에 어긋나는 설계를 발견하면 「의심」으로 표시하고 근거에 어느 조항과 어긋나는지 적어라.
**판단 정본에 어긋나는 것도 같다** — 학생·학부모가 닿는 기능이 ①기본 게이트(재미·실사용 한국어
도움·신선)를 빠뜨렸으면 「의심」으로 표시하고 근거에 어느 층이 빈지 적어라(배관에는 묻지 마라).
그리고 학습데이터 — ${학습데이터지시}
${L.지시 ? L.지시 + '\n' : ''}${철학블록(철학)}${방향블록(방향)}
${아는미완블록(미완)}${채택제안들.length ? `이번에 채택돼 함께 구현됐어야 하는 업그레이드 — 실제로 구현됐는지도 각각 체크에 넣어라:\n${채택제안들.map((t) => '  · ' + t).join('\n')}\n` : ''}
--- 변경 내용 ---
${diff텍스트}`;
}

/* 채택 제안을 기능체크 프롬프트에 실을 줄로 만든다.
 * 🔴 2026-08-07 실사고: **제목만 실었더니 「좁혀서 채택」이 「전량 채택」으로 읽혔다.** 08-04 에
 *   범위를 좁혀 채택한 3건이 08-07 검수에서 전부 「채택 기록은 있는데 구현이 없다」로 되돌아왔다
 *   (P1 2건 · P3 1건 — 그중 둘은 판정문이 **명시적으로 잘라낸** 부분을 요구하고 있었다).
 *   기각 이력은 코드 층에서 걸러지는데 **범위를 좁힌 채택은 걸러지는 통로가 없어** 매 배포마다
 *   같은 지적이 재발한다 — 08-04 에 스스로 우려한 「노이즈가 곧 검사를 끈다」의 다른 경로다.
 * 사유를 **자르지 않는 이유**: 범위는 사유의 **뒤쪽**에 온다("… 단 범위를 좁혀 채택한다 — 채택 범위=…").
 *   앞에서 N자로 자르면 정확히 그 부분만 사라져 **고치기 전과 같은 모양**이 된다.
 * 조립을 함수로 가른 이유: 호출부 안에 두면 실제 codex 호출로만 쓰여 어떤 검사도 못 닿는다. */
function 채택제안줄들(현황, 상한 = 20) {
  return [...(현황 || 제안현황()).values()]
    .filter((p) => p.상태 === '채택')
    .map((p) => (p.사유
      ? `${p.제목} — 채택 시 정한 범위: ${p.사유}`
      : `${p.제목} (범위 기록 없음 — 전량 채택으로 읽지 말 것)`))
    .slice(-상한);
}

/* 기능체크 결과를 지적으로 변환 — 게이트·기각 레버·재발 필터를 **한 통로**로 태우기 위해서다.
 * 깨짐 = 차단급(P1): 기능이 의도대로 안 도는 채 배포되는 것이 이 게이트가 막는 바로 그것.
 * 의심 = P3(알림): 막지 않는다 — 의심을 차단으로 만들면 사람이 우회를 배운다. */
function 기능체크지적들(체크) {
  return (체크 || [])
    .filter((c) => c.판정 === '깨짐' || c.판정 === '의심')
    .map((c) => ({
      등급: c.판정 === '깨짐' ? 'P1' : 'P3',
      파일: '(기능체크)',
      라인: 0,
      제목: `기능 ${c.판정}: ${c.기능}`,
      근거: c.근거 || '',
      수정방향: c.판정 === '깨짐' ? '기능을 고치고 재검수하거나, 오판이면 사유와 함께 기각' : '확인해 보고 문제면 고친다',
    }));
}

/* 기능체크 여러 회차를 하나로 — **나쁜 쪽이 이긴다.**
 * 한 회차라도 「깨짐」이면 깨진 것이다(다수결로 눌러 조용해지면 이 게이트가 막으려던 것이 통과한다).
 * 기능 이름이 손잡이다 — 회차마다 표현이 흔들리면 둘 다 남는데, 그건 조용한 누락보다 낫다. */
const 판정깊이 = { 정상: 0, 확인못함: 1, 의심: 2, 깨짐: 3 };
function 기능체크병합(모음) {
  const 산 = 모음.filter(Boolean);
  if (산.length <= 1) return 산[0] || null;
  const 표 = new Map();
  for (const r of 산) {
    for (const c of r.체크 || []) {
      const k = String(c.기능 || '');
      const 전 = 표.get(k);
      if (!전 || (판정깊이[c.판정] || 0) > (판정깊이[전.판정] || 0)) 표.set(k, c);
    }
  }
  const 학습 = [];
  const 본 = new Set();
  for (const r of 산) {
    for (const d of r.학습데이터 || []) {
      const k = JSON.stringify(d);
      if (본.has(k)) continue;
      본.add(k);
      학습.push(d);
    }
  }
  return { 체크: [...표.values()], 학습데이터: 학습 };
}

/* 학습데이터 계약을 사람이 읽는 줄로. **지적으로는 안 만든다** — 위 주석대로 이 판정은 검수자의
 * 추측이라 차단 레버에 얹으면 우회를 가르친다. 알림은 여기(콘솔)와 장부 행에만 산다. */
function 학습데이터줄들(항목들) {
  return (항목들 || []).map((d) =>
    `  📊 ${d.기능} — ${d.영향} · 원문보존 ${d.원문보존 ? '○' : '✗'} · 키 ${d.키 || '없음'} · 스키마 ${d.스키마버전 || '없음'}` +
    (d.외부PII전송 ? ' · ⚠외부 PII 전송' : ''));
}

/* codex exec + 스키마 직행 한 번 — 제안·기능체크 공용. `exec` 는 스키마를 지키므로(실측)
 * 2단계 구조화가 필요 없다. 실패는 전부 확인 불가(2)로 드러난다. */
function 스키마실행(프롬프트, 스키마, timeoutMs, 라벨) {
  const 임시 = fs.mkdtempSync(path.join(os.tmpdir(), 'synk-review-'));
  const out = path.join(임시, 'out.json');
  codex(['exec', ...잠금플래그, ...모델플래그(모델설정.분석), '--output-schema', 스키마, '--ephemeral', '-o', out, '-'],
    프롬프트, timeoutMs, 라벨);
  try { return JSON.parse(fs.readFileSync(out, 'utf8')); } catch (e) {
    const err = new Error(`${라벨} 결과가 스키마와 다르다(` + String(e.message) + ')');
    err.확인불가 = true; throw err;
  }
}

// ─────────────────────────────────────────────────────────────── 프롬프트

/* ⛔ 막다른 길(2026-08-05 실측) — **1단계에는 커스텀 프롬프트를 줄 수 없다.**
 *   `codex exec review` 는 타깃 플래그와 `[PROMPT]` 가 **배타적**이다. 셋 다 확인했다:
 *     the argument '--uncommitted' cannot be used with '[PROMPT]'
 *     the argument '--commit <SHA>'  cannot be used with '[PROMPT]'
 *     the argument '--base <BRANCH>' cannot be used with '[PROMPT]'
 *   PROMPT 모드로 가면 프롬프트는 되찾지만 **검수 범위가 불확정**해진다 — 이 도구의 기록은
 *   「어느 범위가 검수됐나」로 게이트를 거는 것이라 범위의 확정성이 프롬프트보다 값지다.
 *   그래서 타깃 플래그를 택했다. 다음 세션이 이 벽을 다시 받지 않도록 남긴다.
 *
 * 그럼 SYNK 고유의 검수 렌즈는 어디서 오나 — **저장소의 `CLAUDE.md` 다.**
 *   실측: 첫 검수에서 codex 가 시키지도 않았는데 `CLAUDE.md:45` 를 근거로 인용했다
 *   (「repo 밖 환경에 기대는 검사는 CI에서 깨진다」로 테스트 격리 결함을 잡아냈다).
 *   즉 렌즈는 이미 닿고 있다. repo 에 `AGENTS.md` 를 심지 않은 것은 그대로 유지한다 —
 *   그건 「여기서 구현해도 된다」는 신호이고, 그 순서는 08-03 판정이 따로 정해뒀다.
 *
 * 기각 이력의 효과는 그래서 **한쪽만** 남는다: codex 는 기각된 지적을 다시 올릴 수 있지만,
 *   `main()` 이 키로 걸러 **내 앞에는 안 온다.** 줄어드는 것은 내 판단 시간이지 codex 토큰이 아니다.
 *   (검수 비용은 유호님 ChatGPT 구독 몫이라 이 비대칭은 실질 손해가 아니다.) */

// ─────────────────────────────────────────────────────────────── 실행

/* 🔒 읽기 전용을 **실제로** 강제하는 조합 — 2026-08-05 실측으로 정해졌다. 세 개가 한 벌이다.
 *
 *   --ignore-user-config      ~/.codex/config.toml 을 안 읽는다. **이게 핵심이다.**
 *     그 파일에는 ①`[mcp_servers.node_repl]` — 임의 node 실행 MCP ②`[projects.'c:\users\q1212']
 *     trust_level="trusted"` — 홈 전체 신뢰 ③`[windows] sandbox="elevated"` 가 들어 있다.
 *     ③ 때문에 샌드박스 러너가 권한 오류로 죽고(`SpawnChild … Windows error 5`), 그러면
 *     에이전트는 셸 대신 **node_repl 로 우회해 `execFileA('git',…)` 를 그대로 돌린다.**
 *     즉 이 플래그가 없으면 `sandbox_mode="read-only"` 는 **글자만 읽기 전용**이다(실측).
 *   -c sandbox_mode="read-only"   쓰기 차단. 실측: `patch rejected: writing is blocked by
 *     read-only sandbox` 가 뜨고 프로브 파일이 실제로 안 생겼다.
 *   -c approval_policy="never"    신뢰 설정이 함께 빠지면서 **읽기 명령까지** 승인 대기로 거절된다
 *     (실측 6건 `blocked by policy`). 검수자가 정보를 덜 보면 검수 품질이 조용히 낮아지므로 연다.
 *     쓰기가 막히는지는 이 플래그를 넣고 다시 쟀다 — 그대로 막혔다.
 *
 * 🔴 **2026-08-06 재실측(F132) — 잠금을 실제로 지는 것은 `--ignore-user-config` 하나다.**
 *   그 플래그가 있으면 `-s workspace-write` 를 명시해도, `-c sandbox_mode="workspace-write"` 를 줘도
 *   `turn_context.sandbox_policy` 는 그대로 `read-only` 였다(rollout 을 직접 읽어 확인). 그 플래그를
 *   빼자마자 `-s workspace-write` 가 먹었다. 즉 **`-c sandbox_mode=` 는 잠금 근거가 아니다** —
 *   read-only 가 마침 그 상태의 기본값이라 「먹은 것」과 「무시된 것」이 같은 모양이었을 뿐이다.
 *   ⚠ 그래서 위험한 편집은 `-c` 줄을 지우는 게 아니라 **`--ignore-user-config` 를 지우면서
 *   「-c 가 막고 있으니 괜찮다」고 읽는 것**이다. 그 순간 잠금이 통째로 열린다.
 *
 * ⚠ 이 셋 중 하나라도 빠지면 「읽기 전용」이 사실이 아니게 된다. 지우지 말 것. */

/* 🔴 **샌드박스는 디스크를 막지 네트워크를 안 막는다**(F133 · 2026-08-06 실측).
 *   위 잠금은 **파일 쓰기만** 막는다. codex 의 `features` 는 stage=stable 이면 **기본이 true** 라
 *   `--ignore-user-config` 로도 안 꺼진다 — `codex features list` 실측에서 `apps`(GitHub MCP)·
 *   `browser_use`·`computer_use` 가 전부 true 였다. 실사고: 발주 런에서 에이전트가
 *   `mcp__codex_apps__github_create_branch` 로 **원격 저장소 쓰기**를 시도했다(디스크는 잠겨 있었다).
 *   즉 「읽기 전용」이라 부르던 상태에서 검수자는 GitHub·브라우저·데스크톱에 닿을 수 있었다.
 *
 *   여기 담는 기준은 **repo 밖으로 나가는 문**뿐이다(연산·표시 기능은 안 건드린다 — 검수 품질을
 *   조용히 깎는다). `--disable X` = `-c features.X=false`.
 *   ⚠ 이름이 바뀌면 codex 가 `Unknown feature flag` 로 **죽는다** — 조용히 열리는 게 아니라
 *   확인 불가로 드러난다(그 방향이 맞다 · 미실행과 통과가 같은 모양이면 안 된다).
 *
 *   🔬 **먹었는지 쟀다**(F132 의 교훈 — 플래그는 붙였다고 먹은 게 아니다). 같은 프롬프트·같은 모델로
 *   조건 하나만 바꿔 두 번 돌리고 **롤아웃의 실제 도구 목록**을 대조했다:
 *     옛 잠금(이 줄들 없이) → `codex_apps` **있음** · 새 잠금 → `codex_apps` **없음**.
 *   남는 것은 `~/.agents/skills` 가 주입하는 **산문**뿐이다(도구가 아니라 문장 — 나갈 수단은 없다).
 *   `--ignore-user-config` 는 config.toml 만 끊지 그 스킬 폴더를 안 끊는다. */
const 외부도구들 = [
  'apps',                          // codex_apps MCP — GitHub 원격 읽기·쓰기(실사고 통로)
  'plugins', 'plugin_sharing', 'remote_plugin', // 커넥터(실측 당시 Canva 가 도구 목록에 있었다)
  'browser_use', 'browser_use_external', 'browser_use_full_cdp_access', 'in_app_browser',
  'computer_use',                  // 데스크톱 조작
  'skill_mcp_dependency_install',  // 검수 중 MCP 의존성 설치 = 바깥에서 실행물을 들인다
];
/* 🔴 **넷째 플래그 — `windows.sandbox="elevated"` 를 명시로 되돌린다**(2026-09-02 실측 · codex 0.151.0/0.152.0).
 *   `--ignore-user-config` 가 `~/.codex/config.toml` 의 `[windows] sandbox="elevated"` 까지 지우자, 남는 것은
 *   «제한 토큰» 샌드박스인데 그 토큰은 **Microsoft Store 판 pwsh(`C:\Program Files\WindowsApps\…\pwsh.exe`)를
 *   못 띄운다.** 그래서 검수자의 **모든 셸 명령**이 「Rejected(… rejected: blocked by policy)」로 죽었다 —
 *   git 한 줄도 못 돈 채 codex 는 정상 종료하고 「확인 불가: 저장소 명령 실행이 정책에 의해 차단되어…」를 적었다
 *   (넷째 모양 · 이 문면은 옛 못봤다징후 정규식에 안 걸렸다 → 정규식도 그날 넓혔다).
 *   같은 잠금에 이 한 줄을 더하니 git 이 돌고 파일 쓰기는 「액세스가 거부되었습니다」로 막혔다(read-only 유지 실측).
 *   ⚠ 08-05 의 「elevated 가 SpawnChild error 5 로 죽는다」는 그때 참이었고 0.150.0 「Fixed elevated Windows sandbox setup」
 *   뒤 뒤집혔다 — 승급할 때마다 이 프로브(명령 실행 + 쓰기 거부)를 다시 돌린다. 언제부터 막혀 있었는지는 **안 쟀다**
 *   (09-01 15:43 장부 행엔 지적이 있었다). */
const 잠금플래그 = [
  '--ignore-user-config', '-c', 'sandbox_mode="read-only"', '-c', 'approval_policy="never"',
  '-c', 'windows.sandbox="elevated"',
  ...외부도구들.flatMap((f) => ['--disable', f]),
];

/* ■ 모델·추론 수준은 **`tools/모델정책.js` 가 혼자 정한다** — 여기엔 사본을 두지 않는다.
 *   벤더가 둘(코덱스·제미나이)이 된 뒤로 결정이 두 곳에 있으면 갈라지고, 갈라지는 방향은
 *   언제나 얕은 쪽이다. 왜 그렇게 정했는지(효력이 모델보다 레버다 · 변환은 최하급이 옳다 ·
 *   선택지를 sol·luna 둘로 닫은 이유)는 전부 그 파일 주석에 있다.
 *
 * 고르는 법: `--검수 sol|luna`(또는 `SYNK_REVIEW_PICK`) · 1회성 상향은 `--효력 max`(기본 high).
 *   모르는 이름은 **기본값으로 접지 않고 거절**한다 — 오타를 조용히 sol 로 읽으면
 *   「luna 로 돌렸다」고 믿는 상태가 만들어진다. */
const 정책 = require(path.join(ROOT, 'tools', '모델정책.js'));
const 효력들 = 정책.효력들;
const 모델플래그 = 정책.코덱스플래그;
/* require 시점엔 **기본 픽만** 놓는다 — env·CLI 는 main() 에서 얹는다. 이 모듈은 clasp-guard 훅도
 * require 하므로, 여기서 env 오타로 던지면 **가드가 통째로 죽는다**(등록층 누수 · CLAUDE.md 맹점 ①). */
const 모델설정 = {
  분석: 정책.검수선택(),
  구조화: { ...정책.구조화설정 },
};

/* 실패를 사람이 읽을 한 줄로 — **원인이 갈리게**. 실측 2026-08-08(F249 · 세 모양이 전부 다르다):
 *   ①타임아웃   signal='SIGTERM' · status=null · stderr = 배너 + 프롬프트 echo (오류 줄 없음)
 *   ②실행 중 실패 signal=null · status=1 · 오류는 stderr **맨 뒤**(앞 11줄은 배너)
 *   ③인자 오류   signal=null · status=2 · 오류는 stderr 맨 앞(배너 자체가 없다)
 * 앞 3줄을 자르면 ①②가 **배너 3줄로 완전히 같은 모양**이 되어 원인 판별이 원리상 불가능했다
 * — 그래서 타임아웃을 로그인 만료로 오진하고 15분씩 태웠다(오늘 3연속).
 * ⚠`e.killed` 는 쓰지 않는다 — 실측에서 타임아웃인데도 `undefined` 였다(가르는 건 `signal` 뿐).
 * 뒤에서 자르는 이유는 ②다: 배너를 걷어내도 그 다음 줄은 프롬프트 echo 라 앞은 영영 쓸모없다. */
const 배너줄 = /^(OpenAI Codex\b|-{5,}$|(workdir|model|provider|approval|sandbox|reasoning \w+|session id):)/i;

function 실패요점(e, timeoutMs, 라벨) {
  const 초 = Math.round((timeoutMs || 0) / 1000);
  /* 타임아웃은 「안 돈다」가 아니라 「못 기다렸다」다 — 처방이 정반대라 먼저 가른다.
   * 늘릴 값을 같이 준다: 처방이 그대로 실행 가능해야 우회가 정상 통로가 되지 않는다(F103). */
  if (e && e.signal) return `${라벨} 타임아웃(${초}초 소진 · 죽은 게 아니라 못 기다린 것이다) — \`--timeout ${초 * 2}\` 로 늘려 다시 돌린다.`;
  const 남은 = String((e && e.stderr) || (e && e.message) || e)
    .split('\n').map((s) => s.trim()).filter((s) => s && !배너줄.test(s));
  return `${라벨} 실패: ` + (남은.slice(-3).join(' / ') || '(stderr 에 배너뿐 — 원인 줄이 없다)');
}

/* 벤더 한도 차단문 — 처방이 그대로 실행 가능해야 우회가 정상 통로가 되지 않는다(F103).
 * 리셋 시각·재호출법·확인 강행·보고 문구까지 한 벌로 준다. */
function 한도차단문(상태) {
  const 시각 = (iso) => { try { return new Date(iso).toLocaleString('ko-KR'); } catch (_) { return iso || '(미상)'; } };
  return [
    `GPT(codex) 한도 소진 — 리셋 ${시각(상태.리셋시각)} 전이다(감지 ${시각(상태.감지시각)}${상태.출처런 ? ' · ' + 상태.출처런 : ''}).`,
    `지금 태우면 같은 오류로 즉사한다(실측 08-13: 심문 3회차가 15초에 전멸). 리셋 뒤 **같은 명령**을 다시 부르면 끝난 회차는 이어받는다.`,
    `풀렸는지 확인차 강행: --한도무시 (성공 1회면 마커가 지워져 이 차단도 스스로 사라진다).`,
    `codex 층이 안 돈 채 내보내는 완료·배포 보고엔 「codex 층 미검증」을 밝힌다.`,
  ].join('\n   ');
}

function codex(args, 입력, timeoutMs, 라벨) {
  /* 벤더 한도 게이트 — 모든 codex 호출이 이 함수 하나를 지나므로 여기가 안전망이다(새 호출
   * 경로가 생겨도 못 샌다 — 「라우팅은 훅보다 넓어야 한다」). 판정은 검수런.한도막나 한 곳. */
  const 한도 = 런.한도상태();
  if (런.한도막나(한도)) {
    const e = new Error(`${라벨 || 'codex'} 차단 — ${한도차단문(한도)}`);
    e.확인불가 = true; e.한도 = true;
    throw e;
  }
  const isWin = process.platform === 'win32';
  const bin = isWin ? path.join(process.env.APPDATA || '', 'npm', 'codex.cmd') : 'codex';
  if (isWin && !fs.existsSync(bin)) {
    const e = new Error(`codex CLI 를 찾을 수 없다: ${bin}`); e.확인불가 = true; throw e;
  }
  try {
    execFileSync(
      isWin ? (process.env.ComSpec || 'cmd.exe') : bin,
      isWin ? ['/c', bin, ...args] : args,
      /* cwd = **재는 저장소**. codex 는 여기서 git 을 돌린다(실측) — 1단계에 커스텀 프롬프트를
       * 못 주므로(위 ⛔막다른 길) 이 한 줄이 「어느 저장소의 규약으로 볼 것인가」를 정하는
       * 유일한 손잡이다.
       * ⏭ 렌즈 파일의 «우선순위»는 **안 재봤다**: 이 집엔 `AGENTS.md` 가 없고 그때 codex 가
       *   `CLAUDE.md:45` 를 인용한 것이 근거의 전부라, 「`AGENTS.md` 가 있으면 그쪽을 집는다」는
       *   추론이다. talk 엔 둘 다 있어서(`AGENTS.md` → `docs/이_저장소_규약.md`) 첫 talk 런이
       *   그 답을 낸다 — 그 결과를 여기 적어 추론을 실측으로 바꿔라. */
      자식옵션({ cwd: 대상ROOT, input: 입력, encoding: 'utf8', timeout: timeoutMs, stdio: ['pipe', 'pipe', 'pipe'], maxBuffer: 64 * 1024 * 1024 })
    );
    /* 성공 1회 = 한도가 풀렸다는 유일한 실측 — 마커가 있었다면 지운다(오탐 자가 치유). */
    if (한도) { 런.한도해제(); console.error('✅ codex 성공 — 벤더 한도 마커를 지웠다(풀림 실측).'); }
  } catch (e) {
    /* 실행 자체가 실패했다 = **확인 불가**다. 여기서 「지적 0건」으로 접으면 거짓 초록이 된다. */
    const err = new Error(실패요점(e, timeoutMs, 라벨));
    err.확인불가 = true;
    err.타임아웃 = !!(e && e.signal);
    /* 한도 오류면 마커를 적는다 — 다음 호출부터는 위 게이트가 태우기 전에 끊고,
     * review-runs 훅이 세션을 열 때마다 리셋 시각을 알린다(세션마다 재발견하는 비용 제거). */
    const 기록 = 런.한도기록(String((e && e.stderr) || (e && e.message) || ''));
    if (기록) {
      err.한도 = true;
      err.message += `\n   ⛔ 한도 마커를 적었다(리셋 ${기록.리셋시각 || '시각 미상 — 원문 참조'}) — 다음 호출은 태우기 전에 막힌다.`;
    }
    throw err;
  }
}

/* 2단계인 이유 — 1단계가 스키마를 안 지키기 때문이다(실측).
 *   `codex exec review` 는 자체 리뷰 하네스(다단계 적대 패스)를 돌리는 대신 **`--output-schema` 를
 *   무시하고 산문을 낸다.** 반대로 `codex exec` 는 스키마를 지키지만 그 리뷰 하네스가 없다.
 *   그래서 분석은 `review` 에, 구조화는 `exec` 에 맡긴다.
 * 🔑 산문을 정규식으로 파싱하지 **않는 이유**: 지적 0건과 파싱 실패가 **같은 모양**(빈 결과)이라
 *   구멍이 나면 조용히 초록이 된다. 2단계는 실패하면 실패한다고 말한다. */
/* 회차 = 판단 패스를 몇 번 돌리는가(기본 2 · 정본·근거 = tools/모델정책.js).
 * 합치는 규칙 셋 — 전부 **코드가** 진다(모델에게 합치라고 시키면 떨어진 지적이 조용해진다):
 *   ① 지적은 `키()`(파일+제목) 로 합집합 — 같은 결함을 두 번 세지 않는다.
 *   ② 원문은 회차별로 **다 남긴다** — 2회차가 무엇을 더 봤는지 사후에 대조할 유일한 재료다.
 *   ③ 회차별 건수를 들고 나간다 — 「2회가 값했나」는 분모 없이 못 읽는다(초록은 분모와 함께).
 * 한 회차라도 실패하면 **통째로 실패**다. 「1회는 돌았으니 통과」로 접으면 그게 거짓 초록이다. */
/* 새 플래그 — 이름을 상수로 두는 이유는 `아는플래그` 목록과 여기가 **한 글자라도 갈리면**
 * F135 가드가 「모르는 인자」로 거절하기 때문이다(그리고 그 거절은 30분을 기다린 뒤가 아니라
 * 즉시 나므로 조용하지 않다 — 그래도 두 곳에 문자열을 적는 것 자체를 없앤다). */
const 회차실행플래그 = '--회차실행';
const 직렬플래그 = '--직렬';
const 던지기플래그 = 런.던지기플래그;
/* 한도 마커 우회 — 값은 env 로 전파한다(회차 자식·던지기 자식이 spawn env 로 물려받는다).
 * argv 로 전파하면 spawn 자리마다 끼워야 하고, 하나라도 빠지면 자식만 막혀 「부모는 통과
 * 시켰는데 회차가 전멸」이라는 어리둥절한 모양이 된다. */
const 한도무시플래그 = '--한도무시';

/* 이 검수가 중간 결과를 적을 방. 갈리는 축을 전부 지문에 넣는 판정은 `검수런.방지문` 한 곳이다
 * — 여기서 다시 조립하면 두 판정이 갈리고, 갈린 쪽은 「이미 돌았다」= 통과 방향으로 샌다.
 *
 * 🔴 `내용fp` 는 **필수**다(2026-09-03). 없으면 조용히 빈 축으로 접지 않고 그 자리에서 던진다:
 *   빠뜨렸을 때 생기는 방은 «내용을 모르는 방»이고, 그 방은 남의 회차를 이어받아 codex 를 한 번도
 *   안 태운 채 통과한다 — 새는 방향이 언제나 「이미 돌았다」인 자리라 조용한 기본값을 두지 않는다.
 *   덤으로 이것이 **순서 가드**다: 지문은 diff 를 떠야 나오므로, 호출부가 diff 수집을 방 열기
 *   «뒤»로 되돌리면 그 순간 여기서 큰 소리로 죽는다(주석이 아니라 기계가 순서를 지킨다). */
function 검수방(대상, 회차, argv, 내용fp) {
  if (!내용fp) throw 확인불가('검수방에 내용 지문이 없다 — 내용을 모르는 방은 남의 회차를 이어받는다(2026-09-03 실측)');
  return 런.방({
    종류: 대상.종류, 값: 대상.값,
    모델: 모델설정.분석.model, 효력: 모델설정.분석.effort,
    버그만: (argv || []).includes('--버그만'), 총회차: 회차,
    // `(미커밋)` 은 어느 저장소에서나 같은 문자열이라, 이 축이 없으면 두 저장소가 한 방을 쓴다
    저장소: 이저장소표(),
    /* …그리고 한 저장소 «안에서도» 같은 문자열이라, 이 축이 없으면 동시에 도는 세션들이 한 방을
     * 쓴다(이 집은 워크트리 아홉이 상시다). 근거·실측은 `검수런.방지문` 의 「내용 축」 주석. */
    내용: 내용fp,
  });
}

/* 회차 병렬 — 남은 회차를 자식 프로세스로 한꺼번에 띄운다(벽시계 ≈ 1/회차).
 *
 * 🔑 **결과를 자식에게서 받지 않는다.** 자식은 체크포인트 파일에만 적고, 부모는 그 뒤 평소대로
 *   순차 루프를 돈다 — 이미 적힌 회차는 `codex한회` 가 이어받아 즉시 돌아온다. 그래서
 *   **병렬이 통째로 실패해도 순차 폴백이 공짜로 생긴다**(rate limit 은 아직 미측정이다).
 *   자식의 성공/실패를 부모가 해석하는 구조였다면 그 해석이 틀리는 날 조용히 통과했을 것이다.
 * ⚠ 한 개만 남았으면 안 띄운다 — 프로세스 값만 치르고 병렬 이득이 0 이다. */
/* 단계별 「끝났나」 판정은 **한 곳**이다 — 부모의 폴링과 자식의 이어받기가 서로 다른 잣대를 쓰면
 * 부모가 「아직」이라 보는 회차를 자식이 「이미」로 건너뛰고, 그 회차는 영원히 안 돈다.
 * ⚠ 심문만 잣대가 다르다: 결과가 체크포인트가 아니라 **repo 안 고정 경로**(경로에 대상 지문이
 *   박혀 있다)에 떨어진다. 그래서 파일 존재 + 형식 통과를 본다 — 빈 파일·거부 응답을 「끝」으로
 *   읽으면 그게 정확히 이 검사가 막으려던 것이다. */
const 아는단계 = new Set(['검수', '기능', '심문']);
const 완료칸 = { 검수: '구조', 기능: '기능' };
function 단계끝났나(방, 단계, i) {
  if (단계 === '심문') {
    const 입력 = 런.json읽기(방, '입력', 0);
    const s = 입력 && 입력.심문;
    if (!s || !s.런들 || !s.런들[i - 1]) return false;
    return 심문형식통과(심문결과읽기(심문결과경로(s.절대, s.런들[i - 1].이름, i, s.런들[i - 1].effort).경로));
  }
  return !!런.json읽기(방, 완료칸[단계] || '구조', i);
}

/* ── 어느 단계를 자식으로 띄울지 정하는 **순수 판정** (2026-08-12 · 유호님 「검수 성능 최적화」)
 *
 * 🔑 실측한 나머지 절반: **회차는 병렬인데 단계가 순차였다.** `codex실행` 이 통째로 끝나야
 *   기능체크가 시작하는 구조라(main 의 검수 호출 → 기능 블록), 벽시계가 `검수 + 기능` 이었다.
 *   기본 조합(회차 2 · 버그+기능)의 산술: 검수 8~13분 **뒤에** 기능 5~8분 = 13~21분.
 *   두 단계는 서로의 결과를 **안 쓴다** — 입력은 같은 diff 하나이고, 합치는 것은 맨 끝
 *   `기능체크지적들` 이 지적 배열에 붙일 때뿐이다. 그래서 한꺼번에 띄우면 8~13분이 된다.
 * 🔑 순수 함수로 가른 이유: 호출부 안에 두면 **실제 codex 호출로만 닿아** 어떤 회귀도 못 건다
 *   (`회차병합`·`선파악행들` 과 같은 축 — 검사 못 하는 자리가 조용히 새는 자리다).
 * ⚠ 이 결정은 동시 프로세스 수를 2 → 4 로 올린다. codex CLI 의 **동시 rate limit 은 아직
 *   미측정**이다 — 걸려도 손실은 0 이지만(자식은 체크포인트에만 적고 부모가 순차로 마저 돈다)
 *   그건 「안 걸린다」가 아니라 「걸려도 안 잃는다」다. 끄는 손잡이는 `--직렬`. */
function 병렬계획(argv, 회차, 검수회차 = 회차) {
  const a = argv || [];
  if (a.includes(직렬플래그)) return [];
  // 검수 회차는 벤더 편성 길이다(`--벤더 둘` 이면 codex 회차 + gemini 1) · 기능체크는 codex 회차 그대로
  const 계획 = [{ 단계: '검수', 회차: 검수회차 }];
  if (!a.includes('--버그만')) 계획.push({ 단계: '기능', 회차 });
  /* 총합이 1이면 안 띄운다 — 프로세스 값만 치르고 병렬 이득이 0 이다.
   * ⚠ 잣대가 「회차 > 1」이 아니라 **자식 총합**인 것이 이번 변경의 핵심이다: 옛 판은 단계마다
   *   회차만 봐서 `--회차 1` 을 통째로 놓쳤는데, 그 조합도 검수 1 + 기능 1 = 2 라 절반이 준다. */
  return 계획.reduce((s, x) => s + x.회차, 0) < 2 ? [] : 계획;
}

/* 계획대로 자식을 한꺼번에 띄우고 **전부** 끝날 때까지 기다린다.
 * 단계를 섞어 띄워도 안전한 이유는 이 설계의 원래 급소와 같다 — 자식의 성공/실패를 부모가
 * 해석하지 않고 **체크포인트만** 본다. 검수 자식이 통째로 죽어도 기능 자식은 제 칸을 채우고,
 * 부모는 그 뒤 평소의 순차 루프에서 빈 칸만 다시 돈다. */
function 병렬실행(방, 계획, timeoutMs) {
  const 남은 = [];
  for (const { 단계, 회차 } of 계획) {
    for (let i = 1; i <= 회차; i++) if (!단계끝났나(방, 단계, i)) 남은.push({ 단계, i });
  }
  if (남은.length < 2) return;

  const 묶음 = 계획.map(({ 단계, 회차 }) => (회차 > 1 ? `${단계}×${회차}회` : 단계)).join(' ∥ ');
  console.log(`⚡ ${묶음} 를 동시에 돌린다(${남은.length}프로세스) — 벽시계가 합이 아니라 **가장 긴 하나**가 된다.`);
  console.log(`   자식 로그: ${path.join(방, '로그-<단계>-<회차>.txt')}`);
  const 자식들 = [];
  for (const { 단계, i } of 남은) {
    런.조각쓰기(방, `실패-${단계}`, i, '');   // 낡은 실패 마커를 지운다 — 남아 있으면 폴링이 즉시 끝난 걸로 읽는다
    const fd = fs.openSync(path.join(방, `로그-${단계}-${i}.txt`), 'a');
    try {
      /* stdio 는 **파일 fd** 다(파이프 금지 · 위 `동기대기` 주석). 부모는 곧 이벤트 루프를
       * 멈추고 자므로 파이프였다면 버퍼가 차는 순간 자식이 그대로 매달린다. */
      /* env 는 **`런.자식환경()` 으로만** 준다 — `...process.env` 를 직접 펼치면 던진 런의
       * `SYNK_REVIEW_RUN_ID` 가 손자에게 새고, 손자가 부모보다 먼저 「완주」 도장을 찍는다
       * (F352 실사고 · 그 판은 장부 0줄인데 게이트만 열린 모양이 됐다). 회귀가 이 표기를 막는다. */
      자식들.push(spawn(process.execPath, [__filename, 회차실행플래그, 방, String(i), 단계],
        자식옵션({ cwd: ROOT, stdio: ['ignore', fd, fd], env: 런.자식환경() })));
    } catch (e) {
      console.error(`   ⚠ ${단계} 회차 ${i} 자식 기동 실패(${e.message}) — 부모가 순차로 돈다.`);
    } finally { fs.closeSync(fd); }
  }

  /* 여유를 넉넉히 준다 — 여기서 일찍 끊어도 손해는 없다(부모가 순차로 마저 돈다). 반대로
   * 짧게 끊으면 다 된 밥을 버리고 처음부터 다시 도는 꼴이라, 새는 방향을 기다리는 쪽으로 둔다. */
  const 마감 = Date.now() + timeoutMs * 2 + 300000;
  for (;;) {
    const 끝 = 남은.filter(({ 단계, i }) => 단계끝났나(방, 단계, i) || 런.조각읽기(방, `실패-${단계}`, i));
    if (끝.length === 남은.length) break;
    if (Date.now() > 마감) { console.error('   ⚠ 병렬 대기 상한 — 부모가 남은 회차를 순차로 돈다.'); break; }
    동기대기(1000);
  }
  for (const c of 자식들) { try { c.kill(); } catch (_) { /* 이미 끝났으면 그만 */ } }
}

/* 한 단계만 띄우는 옛 입구 — 심문이 쓴다(심문은 「기능체크」 같은 짝이 없다). */
function 병렬단계(방, 단계, 회차, timeoutMs) {
  병렬실행(방, [{ 단계, 회차 }], timeoutMs);
}

/* 입력 조각은 **덮지 말고 겹쳐 쓴다.**
 * 🔴 이 자리가 이번 변경으로 생기는 급소다 — 검수 쪽과 기능 쪽이 같은 조각의 **다른 칸**을 쓴다.
 *   단계를 동시에 띄우려면 `기능프롬프트` 를 검수보다 먼저 적어야 하는데, 덮어쓰면 그게 사라지고
 *   기능 자식은 「기능체크 프롬프트가 방에 없다」로 죽는다. 죽는 건 그나마 낫다 — 반대로 흘러
 *   회차마다 **다른 질문**을 던지면 합쳐 읽는 순간 회차 대조가 원리상 무효다(F281 과 같은 축). */
function 입력쓰기(방, 조각) {
  런.json쓰기(방, '입력', 0, { ...(런.json읽기(방, '입력', 0) || {}), ...조각 });
}

function codex실행(대상, timeoutMs, 회차 = 1, 방 = null, argv = [], 선띄움 = false, 벤더들 = null) {
  const 편성 = 벤더들 || 벤더편성(argv, 회차);
  /* 방을 안 받은 갈래(호출부가 하나뿐이라 지금은 안 도는 길)에서도 **내용 축을 채워서** 연다 —
   * 여기서 축을 비우면 main 과 다른 방이 서고, 그 방은 남의 회차를 이어받는 바로 그 방이다. */
  const 방경로 = 방 || 검수방(대상, 편성.length, argv, 변경지문(디프수집(대상)));
  /* 대상은 자식이 다시 만들 수 없다 — 미커밋 판정(`대상결정`)은 **시점 의존**이라 몇 초 뒤
   * 남의 세션이 커밋하면 딴 diff 를 가리킨다. 부모가 정한 그것을 그대로 넘긴다. */
  입력쓰기(방경로, { 대상, timeoutMs, 회차, 검수회차: 편성.length, 벤더들: 편성, 분석: 모델설정.분석, 구조화: 모델설정.구조화 });
  /* `선띄움` = 호출자가 이미 단계들을 한꺼번에 띄웠다(main 의 `병렬계획`). 여기서 또 띄우면
   * 같은 회차에 자식이 둘 붙어 codex 를 두 번 태운다 — 결과는 같고 값만 두 배다. */
  if (!선띄움 && 편성.length > 1 && !(argv || []).includes(직렬플래그)) 병렬단계(방경로, '검수', 편성.length, timeoutMs);
  const 회차들 = [];
  for (let i = 1; i <= 편성.length; i++) {
    try {
      회차들.push(검수한회(대상, timeoutMs, 방경로, i, 편성.length));
    } catch (e) {
      /* 둘째 벤더(gemini)의 실패는 «그 회차의 확인 불가»로 남기고 통째로 죽이지 않는다 — 배포 게이트는
       * codex 가 진다. ⚠ 조용히 통과가 아니다: 회차별에 「확인불가」가 찍히고 화면에도 🔴 로 나온다.
       * codex 회차의 실패는 옛 규칙 그대로 던진다(한 회차라도 실패하면 통째로 실패). */
      if (편성[i - 1] === 'gemini' && e && e.확인불가) {
        console.error(`🔴 gemini 회차 ${i} 확인 불가 — 둘째 검수자가 못 봤다(codex 회차는 그대로 간다): ${e.message}`);
        회차들.push({ 벤더: 'gemini', 실패: String(e.message), 요약: '', 지적: [], 원문: '' });
        continue;
      }
      throw e;
    }
  }
  return 회차병합(회차들);
}

/* 병합을 함수로 가른 이유는 **검사할 수 있게** 하기 위해서다 — codex실행 안에 두면 실제 codex
 * 호출로만 닿아 어떤 회귀도 못 건다(검사 못 하는 자리 = 조용히 새는 자리). */
function 회차병합(회차들) {
  if (회차들.length <= 1) return 회차들[0];
  const 지적 = [];
  const 본키 = new Set();
  const 키회차 = new Map();               // 키 → 그 지적을 낸 회차 번호들
  /* 합의의 분모는 **실제로 본 회차**다(09-02) — gemini 회차가 확인 불가로 끝났는데 분모에 넣으면
   * codex 만 본 지적이 「1/2」로 찍혀 «합의 없음»처럼 읽힌다. 못 본 회차는 분모가 아니라 «확인불가» 칸이다. */
  const 분모 = 회차들.filter((r) => r && !r.실패).length || 1;
  for (let i = 0; i < 회차들.length; i++) {
    for (const f of (회차들[i] && 회차들[i].지적) || []) {
      const k = 키(f);
      if (!키회차.has(k)) 키회차.set(k, []);
      if (!키회차.get(k).includes(i + 1)) 키회차.get(k).push(i + 1);
      if (본키.has(k)) continue;
      본키.add(k);
      지적.push(f);
    }
  }

  /* ── 회차별 **단독 기여** (2026-08-12 · 유호님 「2번이·sol이 값어치를 하나?」)
   * 🔑 위 ③ 이 「회차별 건수를 들고 나간다」고 적어 두고도 **정작 그 질문엔 답을 못 했다.**
   *   두 회차가 각 20건인데 완전히 겹치면 합집합도 20 이고 2회차는 **한 건도 안 보탠 것**인데,
   *   건수만 보면 「20 · 20」이라 값한 것처럼 읽힌다. 분모를 들고 나온 게 아니라 분모처럼 생긴
   *   숫자를 들고 나온 것이었다. 값한 것은 **그 회차에만 있던 지적**이다.
   * 🔑 등급까지 같이 센다 — 단독 3건이 P3 셋인 것과 P0 셋인 것은 완전히 다른 판정이고,
   *   건수만 세면 그 둘이 같은 모양이 된다(2026-08-12 상태기반 심문 실측: sol 단독 3건이
   *   **전부 P0** 였고 그중 둘은 코드로 사실 확인됐다 — 이 칸이 있었으면 손으로 안 셌다). */
  /* ── 회차 합의 (2026-08-29 · 유호님 「스킵되는 느낌」 세션의 실측이 근거)
   * 원장 9일치에서 처분된 P1 19건 중 9건이 기각이었다(47% 오경보) — 그런데 처분자가 쓸
   * 재현성 신호가 지적에 없었다. 같은 바이트를 두 회차가 독립으로 봤으니, 「몇 회차가
   * 이 결함을 봤나」가 곧 공짜 재현성 측정이다. 지적마다 `합의: "2/2"` 꼴로 박는다.
   * ⚠ 등급을 자동으로 깎지 않는다 — 단독이 진짜인 실측이 있다(08-12 sol 단독 3건 전부
   *   P0 · 그중 둘 사실확인). 신호는 처분자(사람·클로드)가 읽고, 게이트 판정은 그대로다. */
  for (const f of 지적) f.합의 = `${(키회차.get(키(f)) || []).length}/${분모}`;

  const 단독 = 회차들.map(() => ({ 건수: 0, 등급: {} }));
  for (const f of 지적) {
    const 낸회차 = 키회차.get(키(f)) || [];
    if (낸회차.length !== 1) continue;      // 둘 이상이 봤으면 누구의 단독도 아니다
    const 칸 = 단독[낸회차[0] - 1];
    칸.건수 += 1;
    const g = f.등급 || '(무등급)';
    칸.등급[g] = (칸.등급[g] || 0) + 1;
  }

  /* 벤더 칸은 codex 가 아닐 때만 적는다 — 옛 행 전량이 codex 이고, «없으면 codex» 가 그 행들과 같은 규칙이다
   * (`저장소` 칸이 「없으면 이 집」인 것과 같은 문법). `벤더들` 배열은 항상 들고 나간다. */
  const 벤더of = (r) => (r && r.벤더) || 'codex';
  const 표 = (r, i) => (벤더of(r) === 'codex' ? `${i + 1}회` : `${i + 1}회·${벤더of(r)}`);
  return {
    요약: 회차들.map((r, i) => `[${표(r, i)}] ${r && r.실패 ? '확인 불가 — ' + r.실패 : (r && r.요약) || '(요약 없음)'}`).join('\n'),
    지적,
    원문: 회차들.map((r, i) => `── 1단계 원문 ${i + 1}/${회차들.length}${벤더of(r) === 'codex' ? '' : ` (${벤더of(r)})`} ──\n${(r && r.원문) || ''}`).join('\n\n'),
    회차별: 회차들.map((r, i) => ({
      회차: i + 1,
      ...(벤더of(r) === 'codex' ? {} : { 벤더: 벤더of(r) }),
      // 못 본 회차는 0건이 아니라 null — 「지적 0건」과 「안 봤다」를 같은 모양으로 두지 않는다
      지적수: r && r.실패 ? null : ((r && r.지적) || []).length,
      단독: 단독[i].건수,
      단독등급: 단독[i].등급,
      ...(r && r.서빙모델 ? { 서빙모델: r.서빙모델 } : {}),
      ...(r && r.실패 ? { 확인불가: r.실패 } : {}),
    })),
    벤더들: 회차들.map(벤더of),
  };
}

/* 사람이 읽을 한 줄 — 장부에만 적으면 아무도 안 본다(그 판정이 다음 편성을 정하는데도). */
function 회차별줄(회차별, 지적) {
  if (!Array.isArray(회차별) || 회차별.length <= 1) return '';
  const 칸 = 회차별.map((r) => {
    const 등급 = Object.keys(r.단독등급 || {}).sort().map((g) => `${g} ${r.단독등급[g]}`).join('·');
    const 이름 = r.벤더 && r.벤더 !== 'codex' ? `${r.회차}회·${r.벤더}` : `${r.회차}회`;
    if (r.확인불가) return `[${이름}] 🔴 확인 불가(${String(r.확인불가).slice(0, 60)})`;
    return `[${이름}] ${r.지적수}건 · 단독 ${r.단독 || 0}${등급 ? `(${등급})` : ''}${r.서빙모델 ? ` · 서빙 ${r.서빙모델}` : ''}`;
  }).join(' ');
  const 줄들 = [`회차별: ${칸}\n   ↳ 「그 회차가 값했나」는 **단독**으로 읽는다 — 건수는 겹쳐도 그대로다.`];
  /* 차단급 합의 요약 — 처분 우선순위의 신호다. 전회차 합의 P1 과 단독 P1 은 무게가 다르다
   * (08-29 실측: 처분된 P1 의 47% 가 오경보 — 합의가 그 가름의 첫 재료다). */
  const 찬 = (지적 || []).filter((f) => 차단급.has(f.등급));
  if (찬.length) {
    const 전원 = 찬.filter((f) => { const [a, b] = String(f.합의 || '').split('/'); return a && a === b; }).length;
    줄들.push(`   차단급 ${찬.length}건 중 전회차 합의 ${전원}건 · 단독 ${찬.length - 전원}건 — 단독도 진짜일 수 있다(08-12 실측). 합의는 순서지 면죄부가 아니다.`);
  }
  return 줄들.join('\n');
}

/* ── 벤더 편성 (2026-09-02 · 유호 「전부 진행해줘」 · 정찰 지면 docs/교차검수_재설계_정찰_2026-09-02.html)
 *
 * 「셋째 벤더를 꽂을 자리가 없다」(Muse 기각 ㉢)는 MCP 를 자리로 본 판정이었다. 자리는 **한 회차**다 —
 *   회차 하나가 곧 «독립 검수 한 벌»이고, 병합·합의·단독 계산이 회차 단위로 이미 서 있으니 벤더를
 *   회차의 «속성»으로 두면 병합 코드가 그대로 «벤더 합의»를 낸다(지적마다 `합의: "n/총"`).
 * 편성 = codex ×회차 + (`--벤더 둘` 이면) gemini ×1. gemini 는 **diff 만** 본다(저장소를 못 돈다 —
 *   API 키 레인 · HTTP 직결 · `tools/lib/제미나이호출.js`). 그래서 값은 «다른 눈»이지 «같은 깊이»가 아니다.
 * 🔒 게이트는 codex 가 진다 — gemini 단독 모드는 일부러 없다(`--벤더 gemini` 는 거절). gemini 회차가
 *   못 보면 그 회차만 확인불가로 남긴다(`codex실행`).
 * ⚠ 모델·효력 값은 여기 없다 — 제미나이 픽도 `tools/모델정책.js` 의 `제미나이설정()` 하나가 정한다. */
const 벤더플래그 = '--벤더';
const 아는벤더모드 = new Set(['codex', '둘']);
function 벤더모드(argv) {
  const a = argv || [];
  const i = a.indexOf(벤더플래그);
  if (i < 0) return 'codex';
  const v = a[i + 1];
  if (!v || !아는벤더모드.has(v)) {
    const e = new Error(`${벤더플래그} 는 codex | 둘 중 하나다 — 받은 값: ${v || '(없음)'} (gemini 단독 모드는 없다 · 배포 게이트는 codex 가 진다)`);
    e.확인불가 = true; throw e;
  }
  return v;
}
function 벤더편성(argv, 회차) {
  const 편성 = Array.from({ length: Math.max(1, Number(회차) || 1) }, () => 'codex');
  if (벤더모드(argv) === '둘') 편성.push('gemini');
  return 편성;
}

/* 회차 i 를 어느 벤더가 보나 — 방의 `입력.벤더들` 이 정본이다(부모·자식이 같은 것을 읽는다). */
function 검수한회(대상, timeoutMs, 방, i, 총) {
  const 입력 = 런.json읽기(방, '입력', 0) || {};
  const 벤더 = (Array.isArray(입력.벤더들) && 입력.벤더들[i - 1]) || 'codex';
  if (벤더 === 'gemini') return gemini한회(대상, timeoutMs, 방, i, 총);
  return { ...codex한회(대상, timeoutMs, 방, i, 총), 벤더: 'codex' };
}

/* AGENTS.md 「## Code Review Rules」 — codex 는 저장소에서 스스로 읽지만(09-02 실측 · 첫 줄 「확인 불가」
 * 규칙을 그대로 따랐다) gemini 는 diff 만 받으므로 프롬프트에 실어 준다. 규칙은 한 파일에만 산다. */
function 검수규칙읽기() {
  try {
    const md = fs.readFileSync(path.join(대상ROOT, 'AGENTS.md'), 'utf8');
    const 시작 = md.indexOf('## Code Review Rules');
    if (시작 < 0) return '';
    const 꼬리 = md.slice(시작);
    const 끝 = 꼬리.slice(1).search(/\n## /);
    return (끝 > 0 ? 꼬리.slice(0, 끝 + 1) : 꼬리).trim();
  } catch (_) { return ''; }
}

function gemini프롬프트(대상, diff, 규칙) {
  return [
    '너는 SYNK 저장소의 «둘째 검수자»다(첫째는 GPT/Codex · 너는 독립으로 본다 · 서로 결과를 모른다).',
    '아래 변경(diff)만 근거로 **결함**을 찾아라. 스타일 취향은 넣지 않는다. 확인 못 한 것은 추측이라고 밝힌다.',
    '한국어로 답한다. 「파일」은 저장소 루트 기준 상대 경로, 행 번호를 모르면 「라인」은 0.',
    '등급: P0=라이브 데이터 손상·보안·자격증명·배포 통로 / P1=배포 전 반드시 / P2=고쳐야 하나 배포 가능 / P3=사소.',
    '결함이 없으면 「지적」은 빈 배열이고 「요약」에 없다고 명확히 쓴다. diff 를 못 읽었으면 「요약」 첫 줄에 「확인 불가」라고 쓴다.',
    규칙 ? `\n--- 검수 규칙(AGENTS.md) ---\n${규칙}` : '',
    `\n--- 대상 ---\n${대상.종류} ${대상.값} · 파일 ${(대상.파일들 || []).length}개`,
    `\n--- diff ---\n${diff}`,
  ].join('\n');
}

const 제미나이호출경로 = path.join(__dirname, 'lib', '제미나이호출.js');

/* gemini 한 회차 — codex한회 와 같은 조각 규약(산문-i · 구조-i)을 지켜 이어받기·단계끝났나 가 그대로 선다.
 * 동기 세상이라 HTTP 는 자식 프로세스(`제미나이호출.js` CLI)가 하고, 이 함수는 파일만 읽는다(codex 와 같은 꼴). */
function gemini한회(대상, timeoutMs, 방, i, 총) {
  const 꼬리 = 총 > 1 ? ` ${i}/${총}회` : '';
  const 이전 = 런.json읽기(방, '구조', i);
  if (이전 && Array.isArray(이전.지적)) {
    console.log(`  ↩ ${i}/${총}회(gemini) 이어받음 — 이미 끝난 회차다(호출 0 · 지적 ${이전.지적.length}건).`);
    return { ...이전, 원문: 런.조각읽기(방, '산문', i) || '', 벤더: 'gemini' };
  }
  const 픽 = 정책.제미나이설정();
  const 프롬프트 = gemini프롬프트(대상, 디프수집(대상), 검수규칙읽기());
  const out = 런.조각경로(방, '제미나이', i);
  const 라벨 = `gemini 검수(둘째 검수자${꼬리} · ${픽.model}/${픽.thinking_level || '기본'})`;
  try {
    execFileSync(process.execPath,
      [제미나이호출경로, '--model', 픽.model, ...(픽.thinking_level ? ['--thinking', 픽.thinking_level] : []),
        '--schema', 스키마경로, '-o', out, '--timeout', String(Math.min(timeoutMs, 300000))],
      자식옵션({ cwd: 대상ROOT, input: 프롬프트, encoding: 'utf8', timeout: timeoutMs, stdio: ['pipe', 'pipe', 'pipe'], maxBuffer: 16 * 1024 * 1024 }));
  } catch (e) {
    const 끝줄 = String((e && e.stderr) || (e && e.message) || e).trim().split('\n').filter(Boolean).slice(-2).join(' / ');
    const err = new Error(`${라벨} 실패: ${끝줄 || '(원인 줄 없음)'}`);
    err.확인불가 = true; err.벤더 = 'gemini'; throw err;
  }
  let r, j;
  try {
    r = JSON.parse(fs.readFileSync(out, 'utf8'));
    j = JSON.parse(r.text);
    if (!Array.isArray(j.지적)) throw new Error('지적 배열이 없다');
  } catch (e) {
    const err = new Error(`${라벨} 결과가 스키마와 다르다(${e.message})`);
    err.확인불가 = true; err.벤더 = 'gemini'; throw err;
  }
  j.벤더 = 'gemini';
  j.서빙모델 = r.modelVersion || null;          // «무엇이 답했나» — 픽과 다르면 장부가 그 사실을 들고 나간다
  if (r.modelVersion && !String(r.modelVersion).startsWith(픽.model)) {
    console.error(`   ⚠ gemini 서빙 모델이 픽과 다르다 — 픽 ${픽.model} · 답한 것 ${r.modelVersion}`);
  }
  런.조각쓰기(방, '산문', i, r.text);
  런.json쓰기(방, '구조', i, j);
  j.원문 = r.text;
  return j;
}

/* ■ 🔍 **«변환이 판단을 섞었나»를 재는 자** (2026-09-04 · 유호 확정 「솔로하자」에 딸린 조건)
 *
 * 🔑 **왜 있나.** 09-04 에 2단계 구조화 모델이 ①검수와 같은 값으로 올라갔다. 내가 그때 들었던 반대
 *   근거는 「이 단계의 성공 조건은 좋은 판단이 아니라 «1단계 산문과 같은가»이고, 똑똑할수록
 *   «고쳐서» 옮길 여지가 는다」였는데 — **이 저장소에 그 대조 실측이 0건이다.** 자를 안 세우면
 *   그 주장도 그 반대도 원리상 영원히 검증되지 않는다(그래서 결정문이 이 자를 조건으로 달았다).
 *
 * 🔑 **막지 않는다. 세어서 알리기만 한다.** 산문에 등급 표기가 아예 없는 판도 있고, 그때 빨간불을
 *   내면 자가 헛경보로 무뎌져 **정작 갈린 날 안 보인다.** 표기가 «있을 때»만 재고 갈린 것만 낸다.
 * ⚠ **이 자가 못 보는 것을 적어 둔다** — 잡는 것은 «등급 개수»뿐이다. 문구가 부드러워지거나 근거가
 *   깎인 것은 못 본다. 그러니 이 자의 침묵을 「원문과 같다」로 읽지 않는다(사람이 원문을 본다).
 * 🔑 함수로 갈라 둔 까닭: `codex한회` 안에 두면 실제 검수 호출로만 지나가 **어떤 시험도 못 닿는다**
 *   (검사할 수 없는 자리 = 조용히 새는 자리 · 이 파일의 `심문결과경로` 가 같은 이유로 갈려 있다). */
function 등급갈림(raw, 지적들) {
  const 산문등급 = (String(raw || '').match(/\[P[0-3]\]/g) || []).map((s) => s.slice(1, 3));
  if (!산문등급.length) return [];                       // 표기가 없는 판은 잴 것이 없다(헛경보 금지)
  const 세기 = (a) => a.reduce((m, g) => ((m[g] = (m[g] || 0) + 1), m), {});
  const 칸등급 = (Array.isArray(지적들) ? 지적들 : [])
    .map((r) => String((r && r.등급) || '').toUpperCase()).filter((s) => /^P[0-3]$/.test(s));
  const 앞 = 세기(산문등급); const 뒤 = 세기(칸등급);
  return [...new Set([...Object.keys(앞), ...Object.keys(뒤)])].sort()
    .filter((g) => (앞[g] || 0) !== (뒤[g] || 0))
    .map((g) => `${g} ${앞[g] || 0}→${뒤[g] || 0}`);
}

function codex한회(대상, timeoutMs, 방, i, 총) {
  const 꼬리 = 총 > 1 ? ` ${i}/${총}회` : '';
  const 산문 = 런.조각경로(방, '산문', i);
  const 구조 = 런.조각경로(방, '구조', i);

  /* ── 이어받기 ①: 구조화까지 끝난 회차는 codex 를 **한 번도** 안 부른다.
   * 이것이 F334 의 처방이다 — 예전엔 임시 폴더가 `mkdtempSync` 라 매번 새로 생겨서, 8분짜리
   * 1회차를 끝내고 2회차에서 죽으면 **처음부터** 다시였다. 이제 잃는 것은 죽은 그 회차뿐이다. */
  const 이전 = 런.json읽기(방, '구조', i);
  if (이전 && Array.isArray(이전.지적)) {
    const 원문 = 런.조각읽기(방, '산문', i) || '';
    console.log(`  ↩ ${i}/${총}회 이어받음 — 이미 끝난 회차다(codex 호출 0 · 지적 ${이전.지적.length}건).`);
    return { ...이전, 원문 };
  }

  // 1단계 — 분석(리뷰 하네스). 커스텀 프롬프트는 못 준다(위 「막다른 길」 참조) — 렌즈는 CLAUDE.md 가 진다.
  /* ── 이어받기 ②: **가장 비싼 패스를 가장 먼저 못박는다.** 1단계가 5~8분이고 2단계는 그보다
   * 짧다. 둘을 한 덩이로 두면 2단계에서 죽었을 때 이미 끝난 분석까지 다시 태운다. */
  let raw = 런.조각읽기(방, '산문', i);
  if (raw) {
    console.log(`  ↩ ${i}/${총}회 1단계 이어받음 — 분석은 이미 끝났다(2단계만 돈다).`);
    raw = raw.trim();
  } else {
    codex(['exec', 'review', ...대상.flags, ...잠금플래그, ...모델플래그(모델설정.분석), '--ephemeral', '-o', 산문],
      '', timeoutMs, `codex 검수(1단계 분석${꼬리} · ${모델설정.분석.model}/${모델설정.분석.effort})`);

    try { raw = fs.readFileSync(산문, 'utf8').trim(); } catch (_) {
      const e = new Error(`1단계${꼬리}가 결과 파일을 남기지 않았다`); e.확인불가 = true; throw e;
    }
  }
  if (!raw) { const e = new Error(`1단계${꼬리} 결과가 비었다`); e.확인불가 = true; throw e; }

  /* 2단계 자리표 — 아래 `등급갈림()` 이 이 단계의 결과를 1단계 산문과 맞댄다(정의는 이 파일 위쪽). */
  // 2단계 — 구조화(순수 변환). 새 지적을 만들지 못하게 못 박는다.
  const 변환 = `아래는 코드 검수 결과 원문이다. 스키마에 맞춰 **그대로** 구조화해라.

규칙:
- **원문에 없는 지적을 만들어내지 마라.** 이건 변환이지 검수가 아니다.
- 원문이 「문제 없음」이면 「지적」은 빈 배열이다.
- 등급이 원문에 있으면([P0]~[P3]) 그대로 쓰고, 없으면 심각도에 맞춰 고른다.
- 「파일」은 저장소 루트 기준 상대 경로로 바꿔라(절대경로 금지). 행 번호를 모르면 「라인」은 0.

--- 원문 ---
${raw}`;
  codex(['exec', ...잠금플래그, ...모델플래그(모델설정.구조화), '--output-schema', 스키마경로, '--ephemeral', '-o', 구조, '-'],
    변환, Math.min(timeoutMs, 300000), `codex 검수(2단계 구조화${꼬리} · ${모델설정.구조화.model}/${모델설정.구조화.effort})`);

  let j;
  try {
    j = JSON.parse(fs.readFileSync(구조, 'utf8'));
    if (!Array.isArray(j.지적)) throw new Error('지적 배열이 없다');
  } catch (e) {
    const err = new Error(`2단계${꼬리} 결과가 스키마와 다르다(` + String(e.message) + ')');
    err.확인불가 = true;
    throw err;
  }
  const 갈린 = 등급갈림(raw, j.지적);
  if (갈린.length) {
    console.error(`   🔍 2단계${꼬리} 등급 분포가 원문과 갈렸다 — ${갈린.join(' · ')}`);
    console.error(`      «변환»이 판단을 섞었을 수 있다(막지 않는다). 원문을 눈으로 본다: ${path.relative(ROOT, 산문).replace(/\\/g, '/')}`);
  }
  j.원문 = raw;
  return j;
}

// ─────────────────────────────────────────────────────────────── 게이트 조회 (부작용 0)

/* clasp-guard 가 부르는 순수 조회. 검수를 돌리지 않는다 — 훅 안에서 5분짜리를 돌릴 수는 없다.
 * 돌려주는 것: level = 'ok' | 'none' | 'scope' | 'block'
 *   ok    = 이 지문에 대해 범위 안에서 검수됐고 차단급 미해결 0
 *   none  = 이 지문에 대한 검수 기록 자체가 없다        → 알림
 *   scope = 기록은 있으나 이 프로젝트가 검수 범위 밖이었다 → 알림 (「모름」과 「정상」을 가른다)
 *   block = 차단급 지적이 미해결                        → 차단
 */
function 게이트판정(projRoot, root = ROOT, 장부 = {}) {
  const 기록p = 장부.기록경로 || 기록경로;   // 회귀가 픽스처 장부를 끼워 넣는 자리
  const 기각p = 장부.기각경로 || 기각경로;
  const 이름 = path.relative(root, projRoot).replace(/\\/g, '/') || '(루트)';
  const fp = 점검.지문(projRoot, root);
  /* 🔑 **집의 행만** 본다(`''`). 이 판정이 재는 것은 「이 저장소의 배포 바이트」인데 장부는 형제
   *   저장소 검수와 한 벌이라, 안 가르면 남의 저장소에서 찍은 처분이 이 배포를 열 수 있다.
   *   지적 키는 `sha256(파일+제목)` 이라 저장소를 모른다 — 같은 상대 경로는 두 저장소에 흔하다. */
  const 처분행들 = 장부읽기(기각p, '');
  /* 🔑 이 프로젝트의 배포집합 — `'지문'` 레버의 과녁 검사가 이걸 쓴다. 못 읽으면 빈 집합이고,
   *   그러면 `과녁이배포집합밖()` 이 전부 false 를 내 **아무것도 안 열린다**(모름 → 막힘 · F207). */
  let 배포집합 = [];
  try { 배포집합 = 점검.배포집합(projRoot, root) || []; } catch (_) { 배포집합 = []; }

  /* 🔑 처방은 **과녁을 댄다.** 인자 없이 부르면 미커밋이 있을 때 그것을 검수하는데(`대상결정`),
   *   이 저장소는 세션이 동시에 돌아 작업본에 **늘 남의 미커밋이 있다**. 그 diff 엔 배포 파일이
   *   없으니 `범위` 밖으로 기록되고, 그러면 아래 두 갈래는 영원히 안 닫힌다 — 게이트가 시키는
   *   명령이 그 게이트를 못 여는 형태다(가드 맹점 ③ · F103 과 같은 축).
   *   2026-08-09 실측: 그 기본 호출로 50분을 태웠고 기록은 범위 밖이라 게이트가 그대로였다.
   * 🔑 과녁은 **프로젝트별**이다 — 「가장 최근 [v..] 커밋」으로 뽑으면 crewcard 에 루트 커밋을
   *   처방하게 되고, 그 diff 엔 crewcard 배포 파일이 없어 처방을 따라도 게이트가 그대로다.
   *   그래서 **이 프로젝트의 배포집합을 건드린 마지막 커밋**을 집는다.
   * ⚠ 못 뽑으면 과녁 없이 낸다 — 틀린 과녁을 지어내는 것보다 낫다(그건 남의 판을 검수하게 한다). */
  const { 과녁, 더러움, 미커밋배포, sha: 과녁sha, 열림 } = 과녁판정(projRoot, root, 장부.배포미커밋);

  /* 🔴 F335 — 처방은 **작업본 상태에 따라 갈린다.** 위 과녁(`--commit <sha>`)은 이 프로젝트의
   *   배포 파일이 지금 미커밋이면 **원리상 이 게이트를 못 채운다**: `유효지문`(:245)이
   *   「검수한 것 ≠ 나갈 바이트」를 알고 그 프로젝트의 지문을 아예 안 적기 때문이다.
   *   그래서 처방을 그대로 따라도 게이트는 **같은 문구로** 남고, 남는 출구가 우회뿐이 된다
   *   (F103). 2026-08-11 실측(`81ffe463`): P1 을 고쳐 작업본 지문이 e6ac71ac 로 바뀌자
   *   게이트가 none 으로 내려갔는데 처방은 `--commit 3d705b33` 이었다 — 20~40분을 태우고도
   *   문구가 그대로였다. F292 를 고치며 과녁을 댄 것이 **반대쪽 조건에서 되갚였다.**
   * 🔑 두 처방은 배타가 아니라 **상보**다. 가르는 축은 하나 — 이 프로젝트의 배포 파일이
   *   지금 미커밋인가. 미커밋이면 인자 없는 호출의 diff 에 그 파일이 들어가 범위가 서고
   *   (F292 가 경고한 「범위 밖」은 정확히 반대 조건에서 나는 병이다), 깨끗하면 과녁 커밋의
   *   바이트가 곧 나갈 바이트라 그쪽이 맞다. 그래서 축을 재서 **한 갈래만** 낸다.
   * ⚠ 못 재면 한쪽으로 접지 않는다 — 축을 밝히고 둘 다 남긴다(모름을 확신으로 적으면
   *   그게 다시 따를 수 없는 처방이 된다 · 새는 방향이 여기선 「사람의 시간」이다). */
  /* 🔴 F578 — 세 번째 갈래. 작업본은 깨끗한데 **과녁 커밋을 읽어도 배포 파일이 0건**이면 위 두
   *   처방이 **둘 다** 막힌다: 과녁을 대면 범위 밖이고, 과녁 없이 불러도 작업본이 깨끗해 역시
   *   범위 밖이다. 그때 남는 유일한 통로가 **범위**(`--base`)다 — `<과녁>^...HEAD` 는 그 커밋의
   *   첫 부모부터라 배포 파일이 반드시 든다(그 커밋이 배포집합을 만졌으므로).
   * ⚠ 이 갈래는 위 `머지기준` 수리 뒤로는 거의 안 서야 정상이다 — 서면 그건 두 축이 **또** 갈렸다는
   *   신호다. 그래서 조용히 넘기지 않고 이유를 적는다. */
  const 못열림 = 열림 === false;
  const 처방 = 더러움 === true
    ? '   → node tools/codex-review.js   (약 5분 · 읽기 전용 — **과녁을 대지 않는다**)'
    : 못열림
      ? `   → node tools/codex-review.js --base ${과녁sha}^   (약 5분 · 읽기 전용 — 과녁이 아니라 **범위**를 준다)`
      : `   → node tools/codex-review.js${과녁}   (약 5분 · 읽기 전용)`;
  const 왜 = 더러움 === true
    ? `     ⚠ 이 프로젝트의 배포 파일 **미커밋 ${미커밋배포.length}건**(${미커밋배포.slice(0, 3).join(' · ')}${미커밋배포.length > 3 ? ' …' : ''}) — 나갈 바이트가 곧 작업본이라 **과녁 커밋을 대면 이 게이트는 원리상 안 채워진다**(F335).`
    : 못열림
      ? `     🔴 과녁 \`${과녁sha}\` 를 **실제로 읽어 봤더니** 이 프로젝트의 배포 파일이 **0건**이었다 — 그 과녁으로는 이 게이트가 안 열린다(따라도 종료 2 · F578).\n     머지 커밋이면 \`git show\` 가 combined diff 라 그렇게 나온다. 그래서 과녁 대신 범위를 준다.`
      : 더러움 === false
        ? '     ⚠ 과녁 없이 부르면 **작업본 미커밋**을 검수한다 — 그 diff 에 배포 파일이 없으면 범위 밖으로 기록돼 이 게이트는 안 채워진다(F292).'
        : `     ⚠ 미커밋을 **못 쟀다**(git 실패) — 가르는 축은 「이 프로젝트의 배포 파일이 지금 미커밋인가」다.\n     미커밋이면 과녁 없이 부르고(node tools/codex-review.js), 깨끗하면 위 과녁으로 부른다.`;

  /* 🔴 무효 표식이 붙은 행은 **도장으로 안 센다**(09-03). 장부에서 지우지 않으므로 여기서 가른다.
   *   그리고 그 사실을 **화면에 말한다** — 「기록이 없다」와 「기록은 있는데 무효다」가 같은 얼굴이면
   *   다음 사람이 장부를 열어 보고 「분명히 행이 있는데 왜?」로 시간을 태운다(0은 분모와 함께 읽는다). */
  const 기록행들 = 장부읽기(기록p, '');
  const 무효 = 무효행들(기록행들);
  const 이지문행들 = 기록행들.filter((r) => 검수행인가(r) && r.지문 && r.지문[이름] === fp);
  const 해당 = 이지문행들.filter((r) => !무효.has(r.시각));
  const 무효줄 = 이지문행들.length - 해당.length
    ? [`   ↳ 이 지문의 기록 ${이지문행들.length}건 = 유효 ${해당.length} + **무효 표식 ${이지문행들.length - 해당.length}** (표식 행은 장부에 그대로 있다 · --기록무효)`]
    : [];
  if (!해당.length) {
    return { level: 'none', 이름, fp, lines: [
      `⚠ ${이름}: 이 배포 내용(#fp:${fp})에 **이종 검수 기록이 없다**`,
      ...무효줄,
      처방, 왜,
    ] };
  }

  const 범위안 = 해당.filter((r) => Array.isArray(r.범위) && r.범위.includes(이름));
  if (!범위안.length) {
    return { level: 'scope', 이름, fp, lines: [
      `⚠ ${이름}: 검수 기록은 있으나 **이 프로젝트는 검수 범위 밖**이었다(#fp:${fp})`,
      `   내용이 안 바뀌었다면 그대로 나가도 되지만, 「검수됨」은 아니다.`,
      ...무효줄,
      처방, 왜,
    ] };
  }

  /* 가장 최근 기록 기준. **해소된 것**은 미해결에서 뺀다 — 판정은 필터 축이 아니라 게이트 축이다
   * (`게이트해소키들` · F588). `'지문'` 레버는 찍힌 지문이 지금 지문과 같고 과녁이 기계로도
   * 배포집합 밖일 때만 해소로 센다. */
  const 최신 = 범위안[범위안.length - 1];
  const 원본찾기 = (k) => (최신.지적 || []).find((f) => f.키 === k);
  const 해소키 = 게이트해소키들(처분행들, 이름, fp, 배포집합, 원본찾기);
  const 미해결 = (최신.지적 || []).filter((f) => 차단급.has(f.등급) && !해소키.has(f.키));
  if (미해결.length) {
    /* 🔑 처방은 **실제로 열리는 것만** 댄다(F103). 셋째 줄이 없던 동안, 참인데 범위 밖인 지적에는
     *   따를 수 있는 출구가 `기각`(=「틀렸다」+영구 필터) 하나뿐이었다 — 그래서 세션이 참인 지적을
     *   묻거나 배포를 접었다. 그 자리에서 실측된 것이 F588 이다. */
    const 밖인것 = 미해결.filter((f) => 과녁이배포집합밖(f, 배포집합));
    return { level: 'block', 이름, fp, 지적: 미해결, lines: [
      `${이름}: 이종 검수가 **차단급 ${미해결.length}건**을 지적했고 아직 미해결이다(#fp:${fp})`,
      ...무효줄,
      ...미해결.map((f) => `  - [${f.등급}${f.합의 ? ` · 합의 ${f.합의}` : ''}] ${f.파일}${f.라인 ? ':' + f.라인 : ''} — ${f.제목}\n      ${f.근거}\n      → ${f.수정방향}`),
      `  해소 방법 셋:`,
      `    ① 고친다 → 파일이 바뀌면 지문이 바뀌므로 재검수: node tools/codex-review.js`,
      `    ② 틀린 지적이면 사유와 함께 기각한다(영구 필터 — 참인 지적엔 쓰지 않는다):`,
      ...미해결.map((f) => `       node tools/codex-review.js --기각 ${f.키} --사유 "왜 틀렸는지"`),
      ...(밖인것.length ? [
        `    ③ **참이지만 이 배포집합 밖**이면 대상아님으로 처분한다 — 이 지문(#fp:${fp})에서만 열리고,`,
        `       배포집합이 한 바이트라도 바뀌면 자동 무효다. 과녁이 배포집합 밖인지 도구가 함께 잰다.`,
        `       아래 ${밖인것.length}건은 그 검사를 이미 통과한다(나머지 ${미해결.length - 밖인것.length}건은 과녁이 배포집합 안이라 이 길이 없다):`,
        ...밖인것.map((f) => `       node tools/codex-review.js --대상아님 ${f.키} --사유 "왜 이 배포와 무관한지"`),
      ] : [
        `    ③ 대상아님(범위 밖) 처분은 **이 판에선 길이 아니다** — 위 지적의 과녁이 전부 이 프로젝트의`,
        `       배포집합 안이거나 판정 불가다. 나갈 바이트에 관한 지적이므로 ①이나 ②로 끝낸다.`,
      ]),
    ] };
  }
  return { level: 'ok', 이름, fp, lines: [`${이름}: 이종 검수 통과 (#fp:${fp} · ${(최신.지적 || []).length}건 지적, 차단급 미해결 0)`, ...무효줄] };
}

/* 🔑 F314 — **돌리기 전에** 판정한다(2026-08-10 유호님이 22분째 도는 것을 보고 세션째 지웠다).
 *
 * 병: 과녁 없이 부르면 작업본 미커밋 전체가 대상이 되는데(그 자체는 옳은 기본값이다), 이 저장소는
 *   세션이 10개 도는 시간대가 상시라 그 diff 는 거의 언제나 **남의 docs·PDF** 다. 배포 파일이
 *   0건이면 기록이 `범위 밖`으로 남아 **끝나도 배포 게이트가 안 열린다** — 즉 30분을 태우고
 *   얻는 것이 0이다. 게이트판정(:709~)은 이 함정을 이미 알고 있었지만 **주석과 알림문으로만**
 *   경고했다. 프로즈로 막을 수 있는 규칙은 기계로 옮긴다(CLAUDE.md 신뢰성).
 *
 * ⚠ 왜 종류를 안 가리나: `--commit` 을 명시해도 그 커밋에 배포 파일이 없으면 결과는 같다.
 *   가르는 축은 「어떻게 불렀나」가 아니라 「이 대상이 게이트를 채울 수 있나」다.
 *
 * ⚠ 탈출구(`--범위밖`)가 **반드시** 있어야 한다 — 도구·훅·테스트 코드 검수는 배포 파일 0건이
 *   정상이고, 그걸 막으면 따를 수 없는 처방이 되어 우회가 정상 통로가 된다(F103). */
const 범위밖탈출 = '--범위밖';
function 범위밖정지(대상, 범위들, root = ROOT, 주입) {
  /* 🔑 형제 저장소엔 **막을 배포 게이트 자체가 없다** — 이 정지가 막으려던 것은 「30분을 태워도
   *   게이트가 안 열린다」이고, 열 게이트가 없으면 태우는 값은 그대로 남는다(지적·장부·기록).
   *   여기서 세우면 `--범위밖` 을 매번 붙이게 되고, 매번 붙이는 탈출구는 곧 습관이 되어 정작
   *   이 집의 배포 검수에서도 붙게 된다(F103 — 따를 수 없는 처방이 우회를 정상 통로로 만든다).
   * ⚠ 대신 조용히 지나가지 않는다 — 호출부가 「이 저장소엔 이 게이트가 없다」를 찍는다. */
  if (타저장소()) return null;
  if (범위들.length) return null;
  /* 과녁을 댈 수 있는지는 **`과녁판정` 한 곳**이 정한다(F335) — 여기서 `과녁커밋` 을 직접 부르면
   * 작업본이 그 프로젝트의 배포 파일을 미커밋으로 들고 있을 때 게이트를 못 여는 명령을 처방한다. */
  const 과녁줄 = [];
  let 과녁쓴것 = 0;
  let 범위쓴것 = 0;
  for (const p of 클라스프프로젝트들()) {
    const 이름 = path.relative(root, p).replace(/\\/g, '/') || '(루트)';
    const { sha, 더러움, 미커밋배포, 열림 } = 과녁판정(p, root, 주입);
    if (더러움 === true) {
      과녁줄.push(`   → node tools/codex-review.js   (${이름} · 약 5분 · 읽기 전용 — **과녁을 대지 않는다**)`);
      과녁줄.push(`     ⚠ ${이름} 의 배포 파일 **미커밋 ${미커밋배포.length}건**(${미커밋배포.slice(0, 3).join(' · ')}${미커밋배포.length > 3 ? ' …' : ''}) — 나갈 바이트가 곧 작업본이라 과녁을 대면 지문이 안 적힌다(F335).`);
    } else if (sha && 열림 === false) {
      /* 🔴 F578 — 게이트 알림문(위 `게이트판정`)과 **같은 갈래**를 여기서도 낸다. 두 곳이 같은
       * 판정을 쓰는 것이 이 함수 머리말의 요구이고, 한쪽만 고치면 그쪽이 새는 쪽이 된다(맹점 ④). */
      범위쓴것++;
      과녁줄.push(`   → node tools/codex-review.js --base ${sha}^   (${이름} · 약 5분 · 읽기 전용 — 과녁이 아니라 **범위**)`);
      과녁줄.push(`     🔴 과녁 ${sha} 를 **읽어 봤더니** ${이름} 의 배포 파일이 **0건** — 그 과녁으로는 안 열린다(머지 커밋이면 combined diff 라 그렇다 · F578).`);
    } else if (sha) {
      과녁쓴것++;
      과녁줄.push(`   → node tools/codex-review.js --commit ${sha}   (${이름} · 약 5분 · 읽기 전용)`);
    }
  }
  return [
    '🔴 확인 불가 — 검수를 **안 돌렸다**(통과가 아니다): 대상 diff 에 **배포 파일이 0건**이다.',
    `   대상: ${대상.종류} ${대상.값} · 파일 ${대상.파일들.length}개`,
    '   이대로 돌리면 5~30분을 태우고도 배포 게이트는 그대로다 — 기록이 「범위 밖」으로 남기 때문이다(F314 · 08-10 실측 22분).',
    /* 머리말이 아래 줄과 **같은 말을 해야** 한다 — 전부 미커밋 갈래인데 「과녁을 대고」라고 적으면
     * 읽는 쪽이 명령을 고쳐 다시 과녁을 단다(문구가 처방을 되돌리는 자리 · F335). */
    ...(과녁줄.length
      ? [과녁쓴것
        ? '   과녁을 대고 다시 부른다 — 그 프로젝트의 배포집합을 마지막으로 건드린 커밋이다:'
        : 범위쓴것
          ? '   과녁 커밋으로는 이 게이트가 안 열린다(F578) — **범위**를 대고 다시 부른다:'
          : '   다시 부른다 — 배포 파일이 미커밋이라 **과녁을 대면 안 되는** 상태다:', ...과녁줄]
      : ['   ⚠ 과녁을 못 뽑았다(배포집합이 비었거나 git 이력을 못 읽었다) — 커밋 해시를 직접 대라: --commit <sha>']),
    `   배포 게이트와 **무관한** 검수(도구·훅·테스트 코드)라면 그대로 돌린다: ${범위밖탈출} 을 붙인다.`,
  ];
}

// ─────────────────────────────────────────────────────────────── CLI

/* ① 설계 선파악 — 기능지도 + 업그레이드 제안. 결과는 장부에 「제안됨」으로 쌓이고,
 * 클로드가 --제안판정 으로 채택/기각을 정한다. **배포 게이트와 무관하다**(위 설계 주석). */
function 제안실행(argv, 대상, timeoutMs) {
  const 현황 = 제안현황();
  const 기각제목들 = [...현황.values()].filter((p) => p.상태 === '기각').map((p) => p.제목).slice(-50);
  const diff = 디프수집(대상);

  진행걸기(argv, { 단계: '①선파악', 대상: { 종류: 대상.종류, 값: 대상.값 }, 인자: argv });
  console.log(`설계 선파악 중… (${모델설정.분석.model}/${모델설정.분석.effort} · 읽기 전용 샌드박스)`);
  console.log(소요안내(['--버그만'], 1));   // 판단 패스 1번 — 그래도 포그라운드 기본 2분은 넘는다
  const 결과 = 스키마실행(제안프롬프트(diff, 기각제목들, 방향텍스트(), 철학텍스트()), 제안스키마경로, timeoutMs,
    `codex 선파악(${모델설정.분석.model}/${모델설정.분석.effort})`);

  const now = new Date().toISOString();
  /* 변경지문은 **검수자에게 실제로 보낸 diff** 로 만든다 — 최종 체크가 같은 손잡이로 이 지도를 되찾는다. */
  const 변경fp = 변경지문(diff);
  const { 기록행들, 신규 } = 선파악행들(대상, 결과, 현황, now, 방향지문(), 변경fp);
  for (const 행 of 기록행들) append(제안경로, 행);

  console.log(`\n── 기능지도 (검수자가 파악한 이 변경의 기능 · 변경 ${변경fp}) ──`);
  for (const f of 결과.기능지도 || []) console.log(`  · ${f.기능} — ${f.설명}`);

  const 학습 = 학습데이터줄들(결과.학습데이터);
  if (학습.length) {
    console.log('\n── 학습데이터 영향 (알림 — 배포를 막지 않는다) ──');
    for (const l of 학습) console.log(l);
  }

  console.log(`\n── 업그레이드 제안 ${신규.length}건 ──`);
  if (!신규.length) console.log('  (없음 — 검수자가 올릴 것이 없다고 판단했다)');
  for (const p of 신규) {
    console.log(`\n[${p.크기}] ${p.제목}   (관련: ${p.관련기능})`);
    console.log(`  무엇을: ${p.무엇을}`);
    console.log(`  왜: ${p.왜}`);
    console.log(`  방향: ${p.구현방향}`);
    console.log(`  판정: node tools/codex-review.js --제안판정 ${p.키} --채택`);
    console.log(`        node tools/codex-review.js --제안판정 ${p.키} --기각 --사유 "..."`);
  }
  if (신규.length) {
    console.log('\n다음 순서: 제안마다 채택/기각을 판정한다 — 채택이면 구현 후, 기각이면 그대로 최종 검수(node tools/codex-review.js).');
    console.log('크기 「대」또는 방향을 바꾸는 제안은 클로드가 정하지 말고 유호님께 선택지로 올린다.');
  }
  console.log(`\n기록: ${path.relative(ROOT, 제안경로).replace(/\\/g, '/')}`);
  return 0;
}

// ─────────────────────────────────────────── ②설계 심문 (①배포 검수와 다른 일)

/* ■ 대상은 **코드가 아니라 설계 문서**(계약·L0·C0)이고, 도는 시점은 매 배포가 아니라 **동결 직전 1회**다.
 *   2026-08-06 유호님이 이걸 껐던 실제 이유는 「가치 없음」이 아니라 **조립+대기 20분이 유호님 앞에서
 *   흘렀다**는 것이다(F121). 그래서 이 함수의 존재 이유는 심문 자체가 아니라 **손 조립을 없애는 것**이고,
 *   부르는 쪽은 이걸 백그라운드로 던진 뒤 다른 일을 한다 — 그때 20분은 유호님 시간이 아니게 된다.
 *
 * 🔑 장부를 검수기록과 **섞지 않는다**: `게이트판정()` 이 검수기록을 읽어 배포를 막는데, 심문 행이 거기
 *   섞이면 「설계 문서를 심문했다」가 「이 코드를 검수했다」로 읽힌다. 대상이 다른 기록은 장부도 다르다. */
const 심문경로 = process.env.SYNK_INTERROGATION_LEDGER || path.join(ROOT, 'docs', '_ops', '심문기록.jsonl');
const 심문템플릿 = process.env.SYNK_INTERROGATION_TEMPLATE || path.join(ROOT, 'docs', '_ops', '동결심문_프롬프트.md');
const 심문결과폴더 = process.env.SYNK_INTERROGATION_OUT || path.join(ROOT, 'docs', '_ops', '심문결과');

const 확인불가 = (m) => { const e = new Error(m); e.확인불가 = true; return e; };

/* memory 인덱스의 🚫 줄 **전량**. 골라 넣지 않는 이유는 템플릿 주석에 있다.
 * 경로는 ROOT 에서 파생한다 — 하드코딩하면 다른 기계에서 통째로 죽는다(가드 맹점 ①과 같은 계열).
 * 🔑 **repo 밖 파일이라 없을 수 있다.** 그때 빈 목록으로 접지 않고 **거절**한다: 닫힌 결정을 안 실은
 *   심문은 유호님이 이미 기각한 안을 그대로 다시 물어 오고, 그건 심문의 모양을 한 재제안이다. */
function 금지목록(경로) {
  // 슬러그 조립은 memory-graph 한 곳에서만 한다(F206) — 여기 판은 워크트리에서 어긋났다.
  const p = 경로 || process.env.SYNK_MEMORY_INDEX
    || path.join(require(path.join(ROOT, 'tools', 'memory-graph.js')).memoryDir(), 'MEMORY.md');
  if (!fs.existsSync(p)) {
    throw 확인불가(`memory 인덱스를 못 찾았다: ${p}\n  (SYNK_MEMORY_INDEX 로 경로를 줄 수 있다. 닫힌 결정 없이 도는 심문은 재제안을 물어 온다.)`);
  }
  const 줄 = fs.readFileSync(p, 'utf8').split('\n').filter((l) => l.includes('🚫'));
  if (!줄.length) throw 확인불가(`memory 인덱스에 🚫 줄이 0건이다: ${p} — 추출이 깨졌다고 본다`);
  return 줄.join('\n');
}

/* 마커 치환. **못 찾으면 던진다** — 조용히 원문 그대로 보내면 심문자는 빈 자리를 공격하고,
 * 그 결과는 「지적 없음」과 같은 모양이 된다(이 파일이 산문 정규식 파싱을 안 하는 것과 같은 이유). */
/* ☠️ 첫 `---` **위는 잘라 버린다** — 거긴 사람용 운영 메모(켜짐/꺼짐 표식·이 파일의 내력)다.
 *   2026-08-06 실측: 전문을 보냈더니 GPT가 머리말의 ⏸꺼짐을 읽고 "정본 지시에 따라 실행하지
 *   않았습니다"로 **거부**했다 — 종료코드 0, 241바이트, 겉보기엔 성공. 지시문과 운영 메모가
 *   한 파일에 살면 **모델은 둘을 안 가른다.** 경계는 파일이 아니라 이 한 줄이 긋는다. */
function 심문본문(전문) {
  const i = 전문.indexOf('\n---');
  if (i === -1) throw 확인불가(`템플릿에 --- 구분선이 없다 — 운영 메모와 지시문의 경계가 없으면 머리말이 심문자에게 간다`);
  return 전문.slice(i + 4).replace(/^\s*\n/, '');
}

/* 🔑 철학 게이트가 **비면 던진다** — 검수(자동·매 배포)와 여기서 세기가 갈리는 건 일부러다.
 *   심문은 동결 직전 1회이고 그 결과로 계약이 얼어붙는다(소급 불가). 그 판을 판단 기준 없이
 *   돌리면 「지적 없음」과 구분이 안 되는 통과가 나온다 — 금지목록을 못 읽을 때 거절하는 것과
 *   같은 이유다. 반대로 매 배포 게이트에서까지 던지면 워크트리·CI 에서 배포가 통째로 막혀
 *   **따를 수 없는 처방**이 되고, 그러면 가드를 끄게 된다(F103). 거기선 크게 경고만 한다. */
function 심문프롬프트(대상경로, 템플릿경로, 금지경로, 철학정본 = 철학경로) {
  if (!fs.existsSync(대상경로)) throw 확인불가(`심문 대상이 없다: ${대상경로}`);
  let t = 심문본문(fs.readFileSync(템플릿경로 || 심문템플릿, 'utf8'));
  const 철학 = 철학텍스트(철학정본);
  if (!철학) throw 확인불가(`판단 정본에서 게이트를 못 뽑았다: ${철학정본} — 기준 없이 돈 심문은 「지적 없음」과 같은 모양이다`);
  for (const [마커, 값] of [['{{금지목록}}', 금지목록(금지경로)], ['{{철학게이트}}', 철학], ['{{대상문서}}', fs.readFileSync(대상경로, 'utf8')]]) {
    if (!t.includes(마커)) throw 확인불가(`템플릿에 ${마커} 마커가 없다: ${심문템플릿} — 치환 없이 보내면 빈 심문이 「통과」로 보인다`);
    t = t.split(마커).join(값);
  }
  return t;
}

/* 금지목록 지문 — **모델 대조의 조건 통제가 사후에 증명되게** 한다.
 * 2026-08-07 실측: 말하기_설계 sol↔luna 대조가 「luna 가 더 많이 잡았다」를 냈는데, 두 런 사이에
 * memory 인덱스가 갱신돼 **모델 차이인지 프롬프트 차이인지 못 갈랐다.** 장부는 `방향`(제품방향.md)
 * 지문만 박고 있었고, 정작 매 런 바뀌는 쪽인 금지목록은 안 박았다 — 그래서 그 대조는 판정으로
 * 승격되지 못하고 버려졌다. 같은 날 같은 자리에서 두 번째로 밟았다(L0·C0).
 * 🔑 이 값이 두 행에서 같아야 「모델만 다름」이 성립한다. 다르면 그 대조는 조건 통제 실패이고,
 *   **판정을 못 낸다는 사실이 행에 남는다**(안 남으면 오염된 대조가 판정처럼 인용된다).
 * ponytail: 프롬프트 조립과 이 해시는 각자 파일을 읽는다(두 번). 그 사이 창은 마이크로초라
 *   실제 위험(런 사이 몇 분~몇 시간)과 층이 다르다 — 한 번 읽기로 합치려면 심문프롬프트 시그니처를
 *   깨야 해서 안 합쳤다. 그 창까지 닫아야 하면 금지목록 값을 인자로 내려보내라. */
function 금지지문(경로) {
  return crypto.createHash('sha256').update(금지목록(경로)).digest('hex').slice(0, 12);
}

/* 결과 경로 = 대상이름-지문-**모델**. 모델이 이름에 없으면 같은 문서를 두 모델로 돌릴 때
 * 두 번째가 첫 번째를 **조용히 덮는다**(08-06 실제로 덮였다 — 심문기록 2행이 같은 파일을 가리킨다).
 * 그런데 sol↔luna 대조의 조건은 「같은 문서·같은 효력·모델만 다름」이라, 덮이면 그 실측 자체가
 * 불가능해진다. 조립을 함수로 가른 이유는 심문실행 안에 두면 실제 codex 호출로만 쓰여
 * **어떤 검사도 못 닿기** 때문이다(검사할 수 없는 자리 = 조용히 새는 자리). */
/* ⚠ 2026-08-09 회차가 들어오면서 **같은 함정이 한 칸 안쪽에서 다시 열렸다**: 같은 문서를 같은
 *   모델로 2회 돌리면 모델 이름만으로는 두 결과가 같은 파일을 가리킨다 → 2회차가 1회차를 조용히
 *   덮고, 그러면 「2회 돌렸다」는 기록만 남고 재료는 1벌뿐이 된다. 그래서 회차도 이름에 넣는다.
 *   1회일 때도 `-1` 을 붙인다 — 있을 때와 없을 때 이름이 갈리면 그 갈림 자체가 다음 함정이다. */
/* 🔴 형식 검사 = **거부 탐지**다. 빈 출력만 보면 08-06 의 241바이트 거부를 못 잡는다(안 비어 있었다).
 *   템플릿이 요구하는 건 등급 표기이거나 명시적 「지적 0건」 — 둘 다 없으면 심문이 안 돈 것이다.
 * 🔑 함수로 빼 둔 이유는 **이어받기와 신규 실행이 같은 잣대를 쓰게** 하기 위해서다.
 *   두 곳에 적으면 갈리고, 갈린 쪽은 언제나 「이미 돌았다」= 통과 방향으로 샌다. */
function 심문형식통과(내용) {
  const s = String(내용 || '');
  return !!s && (/\[?P[012]\]?/.test(s) || /지적\s*0\s*건/.test(s));
}

function 심문결과읽기(경로) {
  try { return fs.readFileSync(경로, 'utf8').trim(); } catch (_) { return ''; }
}

/* ■ 제미나이 심문 한 회차 (2026-09-04 · 유호 확정 「아스트라 한벌 + 제미나이 한 벌로 가자」)
 *
 * 🔑 **codex 자리와 «같은 파일»에 같은 모양으로 떨어뜨린다.** 그래야 이어받기·형식 검사·장부·
 *   처분표가 벤더를 몰라도 그대로 돈다(경로에 이미 모델 이름과 효력이 박혀 있어 안 겹친다).
 *   결과 파일에 담는 것은 **산문 그대로**다 — 스키마를 씌우지 않는다. 심문 결과의 잣대가
 *   `심문형식통과`(등급 표기 또는 「지적 0건」)라서, 벤더마다 다른 형식을 만들면 그 잣대가 갈린다.
 *
 * 🔴 **실패는 「지적 0건」이 아니라 «확인 불가»다.** 검수의 둘째 벤더는 실패해도 codex 회차가
 *   게이트를 지지만, 심문은 편성 두 벌이 곧 게이트라서 한 벌이 죽으면 **동결 판정의 분모가 바뀐다.**
 *   그래서 조용히 넘기지 않고 던진다 — 부르는 쪽이 그 회차를 실패로 적는다.
 *
 * ⚠ 시간 상한을 따로 둔다: 검수 diff 는 5분이면 되지만 심문은 문서 전문을 읽고 공격하는 일이라
 *   더 길다. 그래도 무한은 아니다 — 안 끝나는 회차는 「돌고 있다」와 「죽었다」가 같은 얼굴이다. */
function gemini심문한회(프롬프트, timeoutMs, 결과, i, 총, 픽) {
  const 라벨 = `설계 심문 ${i}/${총}(gemini · ${픽.model}/${픽.thinking_level || '기본'})`;
  const 원본 = `${결과}.gemini.json`;            // 서빙 모델·사용량이 든 원 응답 — 결과 옆에 남긴다
  fs.mkdirSync(path.dirname(결과), { recursive: true });
  try {
    execFileSync(process.execPath,
      [제미나이호출경로, '--model', 픽.model,
        ...(픽.thinking_level ? ['--thinking', 픽.thinking_level] : []),
        /* 🔴 09-04 실측 — 심문은 «돈» 창구로 간다. 첫 판이 공짜 몫(하루 20발)에서 죽었다:
         *   `Quota exceeded ... free_tier_requests, limit: 20`. 심문은 문서 전문을 통째로 보내는
         *   무거운 호출이고 빈도가 낮다(통틀어 네 번 돌았다) — 크레딧이 덮기에 딱 맞는 모양이다.
         *   ⚠ 검수 둘째 눈은 그대로 「글」이다(자주 돌고 diff 만 본다 · 크레딧을 거기 태우지 않는다). */
        '--용도', '돈',
        '-o', 원본, '--timeout', String(Math.min(timeoutMs, 900000))],
      자식옵션({
        cwd: 대상ROOT, input: 프롬프트, encoding: 'utf8', timeout: timeoutMs,
        stdio: ['pipe', 'pipe', 'pipe'], maxBuffer: 16 * 1024 * 1024,
      }));
  } catch (e) {
    const 끝줄 = String((e && e.stderr) || (e && e.message) || e).trim().split('\n').filter(Boolean).slice(-2).join(' / ');
    throw 확인불가(`${라벨} 실패: ${끝줄 || '(원인 줄 없음)'}`);
  }
  let r;
  try { r = JSON.parse(fs.readFileSync(원본, 'utf8')); } catch (e) {
    throw 확인불가(`${라벨} 응답을 못 읽었다(${e.message}) — ${path.relative(ROOT, 원본).replace(/\\/g, '/')}`);
  }
  if (!r || !String(r.text || '').trim()) throw 확인불가(`${라벨} 가 빈 답을 냈다 — 확인 불가이므로 동결 불가다`);
  /* «무엇이 답했나»를 눈에 보이게 남긴다 — 픽과 다른 모델이 답하면 그 회차의 조건이 우리가 적은 것과
   * 다르다(제미나이 CLI 가 픽을 무시하고 다른 판으로 서빙한 실측이 있다 · 기억 subscription-cli-review-lanes). */
  if (r.modelVersion && !String(r.modelVersion).startsWith(픽.model)) {
    console.error(`   ⚠ 제미나이 서빙 모델이 픽과 다르다 — 픽 ${픽.model} · 답한 것 ${r.modelVersion}`);
  }
  console.log(`  ${라벨} — 답한 모델 ${r.modelVersion || '(안 알려준다)'}`);
  fs.writeFileSync(결과, String(r.text).trim() + '\n', 'utf8');
  return r;
}

/* 🔴 2026-08-29 — **효력이 이름에 없어서 「깊이를 올렸는데 옛 결과를 이어받는」 일이 났다.**
 *   유호님이 심문을 `high` → `xhigh` 로 올린 그 자리에서 실측됐다: 편성 줄은 「1회 luna/xhigh」라
 *   찍혔는데 codex 호출이 **0회**였고, `…-luna-1.md`(high 로 돈 것)를 그대로 결과로 냈다.
 *   08-07 에 «모델 이름»을 넣어 닫은 것과 **같은 병의 효력 판**이다 — 그때는 두 모델이 서로를
 *   덮었고, 이번엔 두 효력이 서로를 덮었다.
 * 🔑 조건이 이름에 없으면 이어받기는 **조건이 바뀐 것을 원리상 못 본다.** 그리고 새는 방향은
 *   언제나 「이미 돌았다」= 통과 쪽이다(안 도는 쪽으로는 안 샌다).
 * ⚠ 옛 결과 파일(효력 없는 이름)은 새 이름과 안 맞아 **다시 돈다.** 그건 낭비가 아니라 정정이다 —
 *   그 파일이 어느 효력으로 돈 것인지 이름만으론 아무도 모르기 때문이다(장부에만 있다). */
function 심문결과경로(절대, 픽이름, 회차 = 1, 효력) {
  if (!픽이름) throw 확인불가('심문 결과 경로에 모델 이름이 없다 — 이름 없이 쓰면 다른 모델의 결과를 덮는다');
  if (!효력) throw 확인불가('심문 결과 경로에 효력이 없다 — 효력 없이 쓰면 다른 깊이의 결과를 이어받는다(08-29 실측)');
  if (!Number.isInteger(회차) || 회차 < 1) throw 확인불가(`심문 결과 경로의 회차가 정수가 아니다: ${회차}`);
  const 지문 = crypto.createHash('sha256').update(fs.readFileSync(절대)).digest('hex').slice(0, 12);
  const 이름 = `${path.basename(절대, path.extname(절대))}-${지문}-${픽이름}-${효력}-${회차}.md`;
  return { 지문, 경로: path.join(심문결과폴더, 이름) };
}

/* 🔴 F375 — 장부 행은 **던질 때 먼저** 쓴다(2026-08-12 실측: 4회차 `0199ea979dee` 는 결과 파일
 *   3벌이 다 떨어졌는데 장부 행이 0개였다). 지금까지는 완료 시에만 적었다 — 그러면 부모가 죽는
 *   순간 결과는 디스크에 남고 **장부만** 사라진다. 그때 없어지는 것이 하필 재현 재료 전부다:
 *   어느 문서판(대상지문)·어느 금지목록(금지지문)·어느 방향·철학판으로 돌린 회차인지. 그게 없으면
 *   F281(회차 간 대조는 입력을 얼려야 성립)도 F374(낡음 기계대조)도 재료가 통째로 없다.
 * 🔑 「돌았나」와 「끝났나」는 **다른 사실**이라 행도 둘이다(F207 — 미실행이 통과와 같은 모양이면
 *   안 된다). 던짐 행은 재현 재료를 지고, 완료 행은 그 회차가 실제로 형식을 통과했음을 진다.
 *   그래서 판수를 세는 쪽은 반드시 `완료행인가` 로 거른다 — 안 거르면 죽은 회차가 분모를 부풀려
 *   「3판 돌았다」가 거짓이 된다.
 * ⚠ 옛 행에는 `상태` 칸이 없다. 그 행들은 **완료 시에만** 쓰이던 것이라 완료로 읽는다 — 없는 칸을
 *   「모름」으로 읽으면 지난 심문이 통째로 안 센 것이 되고, 그건 동결 판정의 분모를 깎는다. */
const 완료행인가 = (r) => r && r.종류 === '심문' && (r.상태 === undefined || r.상태 === '완료');

/* ⚠ 효력까지 봐야 같은 회차로 세지 않는다(08-29 · 위 `심문결과경로` 와 한 벌).
 * ⚠ **효력 칸이 없는 옛 행은 안 맞힌다** — 그 행이 어느 깊이였는지 모르는데 맞히면 「이미 돌았다」로
 *   접히고, 그 방향이 정확히 이 병이 새던 쪽이다. 모르면 다시 도는 것이 옳다. */
function 심문행키(r, 지문, 회차, model, 효력) {
  return r.대상지문 === 지문 && Number(r.회차) === Number(회차) && r.모델 === model && r.효력 === 효력;
}

/* 🔴 F411 — 완료 행이 **옮겨 적을** 조건 지문을 그 회차의 «던짐» 행에서 읽는다(재계산 금지).
 *   왜: 프롬프트는 던질 때 한 번만 조립되는데(`심문실행` 의 루프 밖) 완료 행은 나중에 append 되므로,
 *   그 사이 철학 정본이나 금지 원천이 바뀌면 장부에 남는 값이 **실제로 쓴 것과 갈린다.**
 *   그리고 그 상태는 정상과 같은 얼굴이다 — 지문이 들어 있으니 「쟀다」로 보인다.
 *   ⚠ 가설이 아니라 실측이다(2026-08-14 · 6회차 런 `e5fa329c11d6`):
 *     던짐 14:09:51Z 철학 `afc4bbfb6bfb` → 완료 14:36:30Z 철학 `1b4c3bdc50b1`
 *     (그 23초 전 `24a222c4` 가 철학 정본을 v1.8 로 올렸다 · 금지도 함께 갈렸다)
 *   그래서 6회차와 7회차를 대조하면 장부는 「철학 동일」로 읽히지만 **실제로는 v1.7 대 v1.8** 이다 —
 *   조건 통제(F281)를 증명하라고 둔 칸이 정반대로 조건이 갈린 것을 감췄다.
 * 🔑 없으면 다시 계산하지 않고 **null 을 박는다** — 그럴듯한 해시는 「쟀는데 틀린 값」이라 안 보이고,
 *   null 은 「안 쟀다」라서 보인다. 장치는 안 도는 쪽보다 이쪽으로 더 자주 샌다(CLAUDE.md 맹점④). */
function 던짐지문읽기(장부경로, 지문, 회차, model, 효력) {
  const 행 = jsonl(장부경로)
    .filter((r) => r.종류 === '심문' && r.상태 === '던짐' && 심문행키(r, 지문, 회차, model, 효력))
    .pop();
  if (!행) return { 방향: null, 철학: null, 금지: null };
  return { 방향: 행.방향 ?? null, 철학: 행.철학 ?? null, 금지: 행.금지 ?? null };
}

/** 던짐 행 — 같은 회차 행이 (던짐이든 완료든) 이미 있으면 안 적는다(이어받기가 두 번 적지 않게).
 *  마지막 인자는 회귀가 픽스처 장부를 끼우는 자리다 — 실장부에 쓰면 그 검사가 판수를 부풀린다. */
function 심문던짐적기(절대, 픽, i, 총회차, 장부경로 = 심문경로, 금지경로, 얼린지문 = null) {
  const { 지문, 경로: 결과 } = 심문결과경로(절대, 픽.이름, i, 픽.effort);
  if (jsonl(장부경로).some((r) => r.종류 === '심문' && 심문행키(r, 지문, i, 픽.model, 픽.effort))) return;
  /* 지문은 **프롬프트를 조립한 그 시점의 것**을 넘겨받는다(F411) — 여기서 다시 계산하면 회차 3개를
   * 적는 사이에도 갈릴 수 있다. 안 넘어오면(회귀 픽스처) 그때만 지금 값을 쓴다. */
  const 조건 = 얼린지문 || { 방향: 방향지문(), 철학: 철학지문(), 금지: 금지지문(금지경로) };
  append(장부경로, {
    종류: '심문', 상태: '던짐', 시각: new Date().toISOString(),
    대상: path.relative(ROOT, 절대).replace(/\\/g, '/'), 대상지문: 지문,
    모델: 픽.model, 효력: 픽.effort, 회차: i, 총회차,
    /* 금지 인덱스는 **repo 밖**(홈)에 산다 — 경로를 인자로 받는 이유는 `심문프롬프트` 와 같다.
     * 이걸 환경에서만 읽으면 회귀가 HOME 에 기대게 되고, CI 는 HOME 을 비워 모사하므로
     * 그 자리에서 거짓 적색이 난다(F296 계열 · 실제로 이 커밋 전 test-ci 가 그렇게 빨갰다). */
    방향: 조건.방향, 철학: 조건.철학, 금지: 조건.금지,
    결과: path.relative(ROOT, 결과).replace(/\\/g, '/'),
  });
}

function 심문실행(argv, timeoutMs) {
  const 대상 = argv[argv.indexOf('--심문') + 1];
  if (!대상 || /^--/.test(대상)) {
    console.error('사용: node tools/codex-review.js --심문 <설계문서 경로> [--검수 sol|luna] [--회차 N] [--timeout 초]');
    /* 편성을 **정본에서 뽑아** 찍는다 — 여기 손으로 적으면 갈린다. 실제로 갈려 있었다:
     * 이 줄이 「luna/high ×2 (유호 확정 08-15)」를 08-30 까지 말하고 있었는데 그 사이 편성이
     * 두 번 바뀌었다(08-29 xhigh ×1 · 08-30 xhigh ×1 + high ×1). `constant-known-in-two-places`. */
    /* 🔴 09-04 — 문구를 여기서 만들지 않는다. 「1회·2회」로 찍던 옛 꼴이 «회차 번호»를 «횟수»로
     *   읽히게 해서 실제로 오독을 만들었다. 벤더별 «몇 벌»을 말하는 한 자리가 정본이다. */
    console.error(`  기본 편성 = ${정책.심문편성문구()} (정본 tools/모델정책.js 심문편성 · \`--회차 N\` 은 앞 N개)`);
    return 2;
  }
  /* 픽을 **여기서** 얹는다 — 이 분기는 main 맨 앞이라 아래쪽 `모델설정.분석 = 정책.분석설정(argv)`
   * 를 안 탄다. 안 얹으면 `--심문 X --검수 sol` 이 조용히 luna 로 돈다(= 이 파일이 막으려는 병).
   * 조합 검사도 지금 — 20분 기다린 뒤 오타를 알 이유가 없다. */
  /* ②의 편성은 **정본이 쥔다**(`모델정책.js` 심문편성) — 여기 모델도 효력도 회차도 안 적는다.
   * ⚠ 08-30 이전엔 이 주석이 「luna/high ×2」라 적혀 있었고 그 사이 편성이 두 번 바뀌었다.
   * 조합 검사를 전부 **지금** 한다 — 마지막 런에서 오타를 알면 앞 런들의 시간이 통째로 버려진다. */
  const 런들 = 정책.심문런들(argv);
  /* 🔴 09-04 — 편성에 제미나이 자리가 생겼다(유호 확정). `모델플래그` 는 **코덱스 조합 검사**라
   *   제미나이 픽을 넣으면 「모르는 코덱스 모델」로 거절한다. 코덱스 자리에만 먹인다.
   *   ⚠ 제미나이 쪽 조합(사고 수준)은 `제미나이설정()` 이 이미 걸렀고, 실제 거절은 호출 때 난다. */
  런들.filter((p) => p.벤더 !== 'gemini').forEach((p) => 모델플래그(p));
  const 회차 = 런들.length;
  const 절대 = path.resolve(대상);
  /* 프롬프트를 **루프 밖에서 한 번** 만든다 — 회차 사이에 금지목록·대상문서가 바뀌면 그 두 회차는
   * 「같은 심문 2회」가 아니라 서로 다른 심문 2건이 되고, 합쳐 읽는 순간 조건 통제가 깨진다. */
  const 프롬프트 = 심문프롬프트(절대);
  /* 조건 지문도 **프롬프트와 같은 자리에서** 굳힌다(F411) — 이 세 값이 증명하려는 것은 「이 런이 어떤
   * 방향·철학·금지 아래 돌았나」이고, 그 답은 프롬프트가 조립된 순간에 이미 정해졌다. 나중에 재계산하면
   * 증거가 아니라 **완료 시각의 스냅샷**이 되고, 그건 조건이 갈린 것을 안 갈린 것처럼 보이게 한다. */
  const 얼린지문 = { 방향: 방향지문(), 철학: 철학지문(), 금지: 금지지문() };
  fs.mkdirSync(심문결과폴더, { recursive: true });
  진행걸기(argv, { 단계: '②심문', 대상: { 종류: 'doc', 값: path.relative(ROOT, 절대).replace(/\\/g, '/') }, 회차, 인자: argv });

  /* 편성을 **먼저 통째로 출력**한다 — 무엇이 돌지 모른 채 30분을 기다리게 두지 않는다.
   * 편성이 조용히 바뀌는 것(예: sol 이 빠짐)도 여기서만 눈에 띈다. */
  console.log(`편성: ${정책.심문편성문구(런들)}`);

  /* 회차 병렬 — 심문은 회차마다 모델이 갈릴 수 있으므로(`--검수` 편성 · 옛 luna·luna·sol 판)
   * 편성 전체를 방에 넣고 자식이 자기 자리 것만 집는다. N회차 = 20분×N 이 ≈20분이 된다.
   * 🔑 프롬프트는 **부모가 만든 그 한 벌**을 넘긴다 — 자식이 다시 조립하면 그 사이 금지목록이나
   *   대상 문서가 바뀐 회차가 생기고, 그 순간 판끼리 대조가 원리상 무효다(F281). */
  /* 🔴 내용 축(09-03) — 값이 **문서 경로**라 워크트리마다 같은 문자열이다. 축이 없으면 같은 문서를
   *   심문하는 두 워크트리가 한 방을 쓰고, 방의 `입력` 에는 **남의 절대경로**가 적혀 자식이 옆
   *   트리의 사본을 심문한다(검수 쪽에서 실측된 병과 같은 뿌리 · `검수런.방지문` 의 내용 축 주석). */
  const 방경로 = 런.방({
    종류: '심문', 값: path.relative(ROOT, 절대).replace(/\\/g, '/'),
    모델: 런들.map((p) => `${p.model}/${p.effort}`).join('+'), 효력: '', 버그만: false, 총회차: 회차,
    내용: 심문결과경로(절대, 런들[0].이름, 1, 런들[0].effort).지문,
  });
  런.json쓰기(방경로, '입력', 0, { 심문: { 절대, 프롬프트, 런들, timeoutMs, 회차 } });

  /* 🔴 F375 — **병렬 스폰보다 먼저** 적는다. 자식이 뜨는 순간부터 부모는 죽을 수 있고, 그 죽음은
   *   회차 하나가 아니라 편성 전체의 장부를 한꺼번에 날린다(실측이 그 꼴이었다). 재현 재료는
   *   여기서 이미 다 정해져 있다 — 프롬프트도 지문도 루프 밖에서 한 벌로 굳혔다. */
  for (let i = 1; i <= 회차; i++) 심문던짐적기(절대, 런들[i - 1], i, 회차, 심문경로, undefined, 얼린지문);

  if (회차 > 1 && !argv.includes(직렬플래그)) 병렬단계(방경로, '심문', 회차, timeoutMs);

  const 결과들 = [];
  for (let i = 1; i <= 회차; i++) {
    모델설정.분석 = 런들[i - 1];   // 런마다 갈린다 — 장부·경로가 이 값을 읽는다
    const { 지문, 경로: 결과 } = 심문결과경로(절대, 모델설정.분석.이름, i, 모델설정.분석.effort);

    /* ── 이어받기 — 심문 결과는 이미 **repo 안 고정 경로**에 떨어지고 그 경로에 대상 지문이
     * 박혀 있다(문서가 한 바이트라도 바뀌면 다른 경로가 된다). 그러니 파일이 있고 형식을
     * 통과하면 그 회차는 끝난 것이다. 20분짜리를 두 번 태우지 않는다.
     * 🔑 잣대는 `심문형식통과` **하나**다 — 이어받기가 느슨하면 거부당한 결과를 통과로 읽는다. */
    const 기존 = 심문결과읽기(결과);
    let 내용;
    let 이어받음 = false;
    if (심문형식통과(기존)) {
      내용 = 기존;
      이어받음 = true;
      console.log(`  ↩ 심문 ${i}/${회차} 이어받음 — 이미 끝난 회차다(codex 호출 0 · ${path.relative(ROOT, 결과).replace(/\\/g, '/')}).`);
    } else {
      const 벤더 = 모델설정.분석.벤더 === 'gemini' ? 'gemini' : 'codex';
      console.log(`설계 심문 ${i}/${회차} — ${대상} (지문 ${지문}) · ${벤더 === 'codex' ? '' : '[제미나이] '}${모델설정.분석.model}/${모델설정.분석.effort}`);
      /* 🔑 **프롬프트는 벤더마다 «같은 한 벌»이다**(09-04). 심문 프롬프트는 문서 전문·철학 게이트·
       *   금지목록을 전부 안에 담고 저장소를 안 돈다 — 그래서 제미나이도 그대로 받는다.
       *   벤더마다 프롬프트를 갈면 그 순간 「같은 문서를 두 집안이 봤다」가 아니라 «서로 다른 심문 둘»이
       *   되고, 합쳐 읽는 순간 조건 통제가 깨진다(F281 · 두 회차 사이 프롬프트를 얼려 두는 그 이유). */
      if (벤더 === 'gemini') {
        gemini심문한회(프롬프트, timeoutMs, 결과, i, 회차, 모델설정.분석);
      } else {
        codex(['exec', ...잠금플래그, ...모델플래그(모델설정.분석), '--ephemeral', '-o', 결과, '-'],
          프롬프트, timeoutMs, `설계 심문 ${i}/${회차}(${모델설정.분석.model})`);
      }
      내용 = 심문결과읽기(결과);
      if (!내용) throw 확인불가(`심문 ${i}/${회차} 가 빈 출력을 냈다 — 확인 불가이므로 동결 불가다`);
      if (!심문형식통과(내용)) {
        throw 확인불가(
          `심문 ${i}/${회차} 결과에 [P0|P1|P2] 등급도 「지적 0건」도 없다 — 형식 미준수이거나 심문이 **거부**됐다.\n` +
          `  결과를 직접 읽어라: ${path.relative(ROOT, 결과).replace(/\\/g, '/')}\n` +
          `  (2026-08-06 실측: 템플릿 머리말의 「꺼짐」 표식을 읽고 거부 → 종료코드 0 · 241바이트 · 겉보기 성공)`
        );
      }
    }

    /* 이어받은 회차를 장부에 **또** 적지 않는다 — 같은 심문이 두 행이 되면 「몇 판 돌았나」가
     * 부풀고, 그 숫자는 동결 판정의 분모다(초록은 분모와 함께만 읽는다). */
    /* 🔑 **완료 행만** 센다(F375). 던짐 행까지 세면 죽은 회차가 「이미 돌았다」로 읽혀 재실행이
     *   막히고, 그 순간 장부의 「몇 판」이 실제로 끝난 판수보다 커진다 — 그게 동결 판정의 분모다. */
    if (jsonl(심문경로).filter(완료행인가).some((r) => 심문행키(r, 지문, i, 모델설정.분석.model, 모델설정.분석.effort))) {
      결과들.push(path.relative(ROOT, 결과).replace(/\\/g, '/'));
      continue;
    }
    /* 대상 **지문**을 박는 이유: 문서가 한 바이트라도 바뀌면 이 심문은 무효다(게이트 조항⑤ 재심문).
     * 회차는 행마다 남긴다 — 한 행에 몰아 적으면 2회차가 죽었을 때 「2회 기록」이 그대로 남는다. */
    /* 조건 지문은 **재계산하지 않는다**(F411) — 출처는 이 회차가 실제로 어느 프롬프트로 돌았느냐로 갈린다:
     *   · 이어받음 = 결과 파일이 이미 있었다 ⇒ 그것을 만든 프롬프트는 «옛 던짐» 의 것이다(이 프로세스가
     *     조립한 `얼린지문` 은 그 결과와 무관하다 — 실측: 7회차 런 `88a14e` 는 3회차 전부 이어받기였고
     *     완료 행을 적은 프로세스는 프롬프트를 만든 프로세스가 아니었다).
     *   · 아니면 = 바로 위에서 이 프로세스의 `프롬프트` 로 codex 를 불렀다 ⇒ `얼린지문` 이 맞다. */
    const 조건 = 이어받음 ? 던짐지문읽기(심문경로, 지문, i, 모델설정.분석.model, 모델설정.분석.effort) : 얼린지문;
    if (조건.철학 === null) {
      console.log(`  ⚠ ${i}/${회차} 던짐 행이 없어 조건 지문을 못 옮긴다 — null 로 적는다(추정 금지 · F411).`);
    }
    append(심문경로, {
      종류: '심문', 상태: '완료', 시각: new Date().toISOString(),
      대상: path.relative(ROOT, 절대).replace(/\\/g, '/'), 대상지문: 지문,
      모델: 모델설정.분석.model, 효력: 모델설정.분석.effort, 회차: i, 총회차: 회차,
      방향: 조건.방향, 철학: 조건.철학, 금지: 조건.금지,
      결과: path.relative(ROOT, 결과).replace(/\\/g, '/'),
    });
    결과들.push(path.relative(ROOT, 결과).replace(/\\/g, '/'));
  }

  console.log(`\n결과 ${결과들.length}벌:`);
  for (const r of 결과들) console.log(`  · ${r}`);
  /* 분모를 함께 낸다(F207) — 「기록: <경로>」만 찍으면 던짐만 남고 완료가 0인 판도 같은 모양이다. */
  const 이판 = jsonl(심문경로).filter((r) => r.종류 === '심문' && r.대상 === path.relative(ROOT, 절대).replace(/\\/g, '/'));
  console.log(`기록: ${path.relative(ROOT, 심문경로).replace(/\\/g, '/')} — 이 문서 던짐 ${이판.filter((r) => r.상태 === '던짐').length} · 완료 ${이판.filter(완료행인가).length}`);
  if (회차 > 1) console.log(`${회차}벌은 **합쳐 읽는다** — 한 벌에만 있는 지적이 곧 그 런이 값한 부분이다(합치는 건 사람이 한다 · 모델에게 시키면 조용히 떨어진다).`);
  console.log('다음: 지적 전건을 채택/기각+사유로 가른다. P0 기각은 유호님께 1줄 보고(조용한 봉인 차단).');
  런.방비우기(방경로);   // 결과는 repo 안(심문결과/)에 있다 — 방에 남은 건 입력 사본뿐이다
  return 0;
}

/* ── 미처분 조회 (2026-08-29 · 유호님 「스킵되는 느낌」)
 * 실측: 지적 369건 중 처분(기각·채택수리·대상아님) 도장이 84건 — **77% 가 도장 없이 쌓여 있었다.**
 * 처분 이력은 다음 런의 재발 지적을 거르는 장치인데, 안 찍으면 그 필터가 23% 로만 돈다.
 * 이 조회는 **아무것도 막지 않는다**(F103) — 몰아서 도장 찍는 자리를 만들 뿐이다.
 * ⚠ 옛 지적일수록 대상 바이트가 이미 바뀌었을 수 있다 — 그래서 행마다 대상·날짜를 싣는다.
 *   낡음 판정은 여기서 안 한다(대상 종류마다 조건이 다르다 · 던지기와 같은 원칙). */
function 미처분현황(장부 = {}) {
  const 기록p = 장부.기록경로 || 기록경로;
  const 기각p = 장부.기각경로 || 기각경로;
  const 처분키 = new Set(장부읽기(기각p).map((r) => r.키).filter(Boolean));
  const 산것 = new Map();               // 키 → 마지막 등장(뒤 행이 이긴다 = 최신 등급·근거)
  let 총지적 = 0;
  for (const r of 장부읽기(기록p)) {
    for (const f of r.지적 || []) {
      총지적 += 1;
      if (!f.키 || 처분키.has(f.키)) continue;
      산것.set(f.키, { f, 시각: String(r.시각 || '').slice(5, 10), 대상: (r.대상 && String(r.대상.값 || '')).slice(0, 12) });
    }
  }
  /* 장부는 한 벌이고 이 조회는 **한 저장소만** 센다 — 분모가 어느 저장소의 것인지 안 적으면
   * 「전체 지적 N건」이 장부 전량으로 읽힌다(수는 자와 함께 적는다). */
  const 저장소표기 = 타저장소() ? ` · 저장소 ${저장소이름(대상ROOT)}` : '';
  if (!산것.size) { console.log(`미처분 0건 (전체 지적 ${총지적}건 · 처분 도장 ${처분키.size}개${저장소표기}) — 다 닫혀 있다.`); return 0; }
  const 등급순 = ['P0', 'P1', 'P2', 'P3'];
  const 묶음 = new Map(등급순.map((g) => [g, []]));
  for (const v of 산것.values()) (묶음.get(v.f.등급) || 묶음.get('P3')).push(v);
  const 요약 = 등급순.map((g) => `${g} ${묶음.get(g).length}`).join(' · ');
  console.log(`미처분 ${산것.size}건 (전체 지적 ${총지적}건 중 · 고유 키 기준${저장소표기}) — ${요약}`);
  console.log('처분 셋: --기각(틀렸다·영구필터) · --채택수리(고쳤다) · --대상아님(이 배포 밖) — 전부 --사유 필수\n');
  for (const g of 등급순) {
    const 줄들 = 묶음.get(g);
    if (!줄들.length) continue;
    console.log(`── ${g} ${줄들.length}건 ──`);
    for (const { f, 시각, 대상 } of 줄들) {
      console.log(`  ${f.파일}${f.라인 ? ':' + f.라인 : ''} — ${String(f.제목 || '').slice(0, 70)}${f.합의 ? ` · 합의 ${f.합의}` : ''} (${대상} · ${시각})`);
      console.log(`    키 ${f.키}`);
    }
  }
  console.log('\n예: node tools/codex-review.js --채택수리 <키> --사유 "어느 커밋에서 고쳤나"');
  return 0;
}

/* 🔴 F135(2026-08-06 실측): `--help` 를 줬더니 거절이 아니라 **기본 동작(미커밋 검수)** 으로 떨어져
 *   14분짜리 sol 런이 조용히 시작됐다. 이 파일은 모델 픽에 대해 「모르는 이름은 기본값으로 접지 않고
 *   거절한다」를 이미 쓰고 있었는데 **최상위 인자 파싱만** 그 규칙 밖이었다 — 한 파일 안에서 층마다
 *   엄격도가 다르면 **느슨한 층이 실질 정책**이 된다.
 *   값을 받는 플래그는 뒤 토큰을 건너뛴다(`--사유 "--x"` 같은 값을 인자로 오인하지 않는다). */
const 값플래그 = ['--심문', '--제안판정', '--기각', '--채택수리', '--대상아님', '--사유', '--timeout', '--commit', '--base', '--모델', '--검수', '--효력', '--회차', '--런처분', '--런중단', '--기록무효', 저장소플래그, 벤더플래그];
const 홑플래그 = ['--채택', '--확인', '--제안', '--버그만', '--uncommitted', 범위밖탈출, 던지기플래그, 직렬플래그, '--런목록', 한도무시플래그, '--딴파일', '--미처분'];
const 아는플래그 = new Set([...값플래그, ...홑플래그]);
const 사용법 = [
  '사용:',
  '  node tools/codex-review.js [--commit <sha> | --base <브랜치> | --uncommitted] [--버그만] [--검수 sol|luna] [--효력 max] [--회차 1] [--벤더 codex|둘] [--timeout 초]',
  '      ⚠ 대상 diff 에 배포 파일이 0건이면 **돌리기 전에 멈춘다**(F314 — 태워도 배포 게이트가 안 열린다).',
  '        배포와 무관한 코드 검수면 --범위밖 을 붙인다.',
  '      --벤더 둘 = codex 회차 뒤에 gemini(둘째 검수자 · API 키 레인 · diff 만 본다) 한 회차를 더한다(09-02).',
  '        합의 「n/총」이 «벤더 합의»가 된다. gemini 가 못 보면 그 회차만 «확인 불가»로 남고 게이트는 codex 가 진다.',
  '  node tools/codex-review.js --제안                      선파악(기능지도+업그레이드 제안)',
  '  node tools/codex-review.js --제안판정 <키> --채택|--기각 --사유 "왜"',
  '  node tools/codex-review.js --기각 <키> --사유 "왜"        틀린 지적 — 다음 런에서 걸러진다',
  '  node tools/codex-review.js --채택수리 <키> --사유 "왜"    옳은 지적을 고쳤다 — 안 걸러진다(재등장 = 수리 미완 신호)',
  '  node tools/codex-review.js --대상아님 <키> --사유 "왜"    이번 채택 범위 밖 — 안 걸러진다(범위가 바뀌면 유효)',
  '  node tools/codex-review.js --기록무효 <기록행 시각> --사유 "왜"   그 **기록행 한 줄**을 도장에서 뺀다(지적은 안 건드린다)',
  '      쓰는 자리 = 행의 «지문»과 «지적»이 서로 다른 검수의 것이 됐을 때(체크포인트 방이 섞인 판 · 09-03).',
  '      장부에서 지우지 않는다 · 지적을 --기각 하지 않는다(남의 진짜 지적이면 재발 필터에서 영구히 사라진다).',
  '  node tools/codex-review.js --확인                      배포 게이트 조회',
  '  node tools/codex-review.js --미처분                    도장 없는 지적 전수 조회(몰아서 처분하는 자리 · 막지 않는다)',
  '  node tools/codex-review.js --심문 <설계문서 경로>        ②설계 심문',
  '',
  '  📦 형제 저장소를 잰다 — git·codex 가 그쪽에서 돈다(기본은 이 저장소):',
  `  ${저장소플래그} <경로>   예) ${저장소플래그} ../SYNK-talk --commit 20d4455`,
  '                검수 장부·판단 정본은 **이 저장소**에 그대로 남고, 행마다 저장소가 찍혀 갈린다',
  '                (처분 이력이 저장소를 넘어 서로를 걸러내면 그게 거짓 초록이다).',
  '                ⚠ 그 저장소엔 Apps Script 배포 게이트가 없다 — 이 검수는 배포를 열지도 막지도 않는다.',
  '                  SYNK-talk 의 배포 게이트는 그쪽 `tools/원격배포.js` 의 배포판 대조다.',
  '                ⚠ ②심문에는 안 쓴다(심문은 문서 경로를 그대로 받는다).',
  '',
  '  ⏱ 오래 걸리는 판단 패스를 **세션 밖으로** 내보내는 손잡이 — 30분을 기다리지 않는다:',
  '  --던지기      세션에서 떼어내 돌린다(세션이 끝나도 산다). 즉시 돌아오고, 결과는 세션을',
  '                새로 열 때 훅이 알린다. 그동안 다른 일을 해라.',
  '  --런목록      던진 런들의 상태(도는 중 · 멈춤 · 완주 미처분)',
  '  --런처분 <ID> 결과를 읽고 찍는 도장 — 찍기 전까지 세션마다 계속 알린다',
  '  --런중단 <ID> --사유 "왜"   도는 런을 **그 자리에서 끈다**(대상이 낡았을 때 · F334)',
  '  --직렬        회차 병렬을 끈다(기본은 병렬 — 벽시계가 회차 수만큼 줄어든다)',
  '  --한도무시    벤더 한도 마커가 있어도 강행(풀렸는지 확인용 · 성공 1회면 마커가 스스로 지워진다)',
  '',
  '  ↩ 중간에 죽어도 **끝난 회차는 다시 안 돈다** — 같은 명령을 그대로 다시 부르면 이어받는다.',
  '  ⛔ 벤더 한도가 감지되면 리셋 시각 전의 검수·심문·선파악을 태우기 전에 막는다(--한도무시 로 확인 강행).',
].join('\n');

/* 던지기 — 이 프로세스를 **세션에서 떼어내** 다시 띄우고 즉시 돌아온다(②의 처방).
 *
 * 왜 필요한가: 백그라운드(`&`)로 돌려도 그 자식은 세션이 만든 셸의 자식이라 **세션이 끝나면
 * 같이 죽는다**(F334 · 보드 두 줄이 같은 문장으로 남았다). `detached` 는 새 프로세스 그룹이라
 * 부모가 사라져도 산다.
 *
 * 🔑 여기가 이 설계의 유일한 새 위험이다 — **던져 놓고 까먹는 것**(유호님이 정확히 그걸 우려했다).
 *   그래서 던진 런은 상태 파일로 남고, `.claude/hooks/review-runs.js` 가 **세션을 열 때마다**
 *   완주 미처분·멈춤을 알린다. 장치와 발동 조건을 같은 커밋에 둔다(CLAUDE.md 신뢰성 조항).
 * ⚠ stdio 는 파일 fd 다 — 부모가 곧 죽으므로 파이프면 자식의 출력이 갈 곳을 잃는다. */
function 던지기(argv) {
  /* 벤더 한도면 **던지기 전에** 끊는다 — codex() 게이트만으로도 안 새지만, 그때는 이미
   * 런 JSON·(심문이면) 장부 던짐 행이 생긴 뒤라 「던졌는데 완료 0」 소음이 남는다.
   * 실측 08-13(런 87f15a): 그 소음 3행을 세 세션이 각자 판독했다. */
  const 한도 = 런.한도상태();
  if (런.한도막나(한도)) {
    console.error(`🔴 던지지 않는다 — ${한도차단문(한도)}`);
    return 2;
  }
  const 종류 = argv.includes('--심문') ? '심문' : (argv.includes('--제안') ? '선파악' : '검수');
  const 런ID = 런.런ID발급(종류);
  const 로그 = 런.로그경로(런ID);
  const 인자 = 런.자식인자(argv);   // `--던지기` 를 뺀다 — 안 빼면 자식이 또 던지고 손자가 또 던진다
  fs.mkdirSync(path.dirname(로그), { recursive: true });

  let child;
  const fd = fs.openSync(로그, 'a');
  try {
    child = spawn(process.execPath, [__filename, ...인자], 자식옵션({
      cwd: ROOT, detached: true,
      stdio: ['ignore', fd, fd],
      env: { ...process.env, SYNK_REVIEW_RUN_ID: 런ID },
    }));
    child.unref();
  } catch (e) {
    console.error(`🔴 던지기 실패(${e.message}) — 세션 안에서 그냥 돌리려면 ${던지기플래그} 를 빼고 다시 부른다.`);
    return 2;
  } finally { fs.closeSync(fd); }

  /* 던질 때의 HEAD 를 박는다 — F334 의 급소가 여기다: 도는 사이 누가 커밋하면 그 런의 대상이
   * 낡는데, 그걸 **아무도 안 알려** 유호님이 계속 기다렸고 쿼터도 계속 탔다.
   * ⚠ 「낡았다」를 여기서 **판정하지 않는다** — 대상 종류마다 낡는 조건이 다르다(`--commit` 은
   *   sha 가 고정이라 그 검수 자체는 유효하고, `--uncommitted` 는 커밋되는 순간 무효다).
   *   지어내지 말고 **HEAD 가 움직였다는 사실만** 전하고, 끌지 말지는 사람이 정한다. */
  let head = '';
  try { head = git(['rev-parse', 'HEAD']); } catch (_) { /* 못 읽으면 대조를 안 할 뿐이다 */ }

  런.런쓰기({
    런ID, 종류, 인자, 로그, pid: child.pid, HEAD: head,
    시작: new Date().toISOString(), 상태: '진행',
    대상: 인자.join(' ') || '(기본)',
    세션: 보드id.세션id() || '',
    /* 🔑 위 `HEAD` 는 **재는 저장소**의 것이다 — 어느 저장소인지 같이 안 적으면 `review-runs` 훅이
     *   이 집의 HEAD 와 대조해 형제 저장소 런마다 「던진 뒤 HEAD 가 움직였다」를 **매 세션 거짓으로**
     *   외친다. 거짓 경보는 사람이 훅을 통째로 무시하게 만든다(그러면 진짜 F334 가 안 보인다).
     * ⚠ 집이면 안 적는다 — 옛 런 행과 같은 모양을 유지한다. */
    ...(타저장소() ? { 저장소: 저장소이름(대상ROOT), 저장소경로: 대상ROOT } : {}),
  });

  console.log(`🚀 던졌다 — 이 세션이 끝나도 계속 돈다(pid ${child.pid}).`);
  console.log(`   런 ${런ID} · 종류 ${종류}`);
  console.log(`   로그: ${로그}`);
  console.log(`   이 세션은 **기다리지 않는다.** 다른 일을 해라 — 결과는 세션을 새로 열 때 훅이 알린다.`);
  console.log(`   지금 보고 싶으면: node tools/codex-review.js --런목록`);
  return 0;
}

/** 던진 런들의 현재 상태. 판정 어휘는 `검수런.판정` 한 곳에서만 나온다. */
function 런현황() {
  const s = 런.요약();
  const 줄 = (x) => `  · ${x.런.런ID} · ${x.런.종류} · ${x.판.분 == null ? '?' : x.판.분}분 · ${x.런.대상}`;
  if (!s.진행.length && !s.멈춤.length && !s.완주미처분.length && !s.미결미처분.length && !s.실패미처분.length) { console.log('던진 런 없음.'); return 0; }
  if (s.완주미처분.length) {
    console.log(`✅ 완주했는데 **아직 안 주운** 런 ${s.완주미처분.length}건 — 결과를 읽고 처분해라:`);
    s.완주미처분.forEach((x) => { console.log(줄(x)); console.log(`      로그: ${x.런.로그}`); });
    console.log(`   처분 도장: node tools/codex-review.js --런처분 <런ID>`);
  }
  /* 🟠 **결과는 있는데 처리할 것이 남은** 런 — 종료코드 1 은 이 도구에서 「차단 지적을 찾았다」다
   * (`main` 끝: `return 차단.length ? 1 : 0`). 이 칸이 없던 동안 그게 아래 🔴 로 떨어져
   * 「주울 답이 없다」로 나갔고, 지적 13건(P1 2)이 「접었으면 도장」 처방을 받았다(F561). */
  if (s.미결미처분.length) {
    console.log(`🟠 **결과가 나왔고 처리할 것이 남은** 런 ${s.미결미처분.length}건 — 오류가 아니다(주울 것이 있다):`);
    s.미결미처분.forEach((x) => {
      console.log(`${줄(x)} — 종료코드 ${x.런.종료코드 == null ? '?' : x.런.종료코드}`);
      console.log(`      ${x.런.비고 || '차단급 지적을 찾았다 — 장부: docs/_ops/검수기록.jsonl'}`);
      console.log(`      로그: ${x.런.로그}`);
    });
    console.log(`   오판이면 --기각 <키> --사유 "…" · 다 처리했으면 도장: node tools/codex-review.js --런처분 <런ID> --사유 "무엇을 했나"`);
  }
  /* 실패는 완주와 **다른 칸**이다 — 뭉치면 ✅ 의 얼굴로 나가고, 사람이 「결과가 있다」고 믿고
   * 로그를 연다(실측 F509: 44KB 가 전부 404 였다). 여기선 답이 없다는 말부터 한다.
   * ⚠ 단 뜻을 모르는 코드까지 「없다」로 단정하지 않는다 — 그 단정이 F561 이었다. */
  if (s.실패미처분.length) {
    const 모름 = s.실패미처분.filter((x) => x.판.결과 == null).length;
    console.log(`🔴 **실패로 끝난** 런 ${s.실패미처분.length}건 — `
      + (모름 === s.실패미처분.length ? '주울 답이 **있는지 모른다**(종료코드 뜻이 표에 없다):' : '주울 답이 없다(통과가 아니다):'));
    s.실패미처분.forEach((x) => {
      console.log(`${줄(x)} — 종료코드 ${x.런.종료코드 == null ? '?' : x.런.종료코드}${x.판.결과 == null ? ' · 뜻 모름' : ''}`);
      console.log(`      왜: ${x.런.비고 || '(비고 없음 — 로그 끝을 본다)'}`);
      console.log(`      로그: ${x.런.로그}`);
    });
    console.log(`   고치고 다시 던졌거나 접었으면 도장: node tools/codex-review.js --런처분 <런ID> --사유 "무엇을 했나"`);
  }
  if (s.멈춤.length) {
    console.log(`🔴 **멈춘** 런 ${s.멈춤.length}건(죽었거나 매달렸다 — 통과가 아니다):`);
    s.멈춤.forEach((x) => {
      const 이 = 런.이어받기명령(x.런);
      console.log(`${줄(x)} — ${x.판.사유 || ''}`);
      console.log(`      이어받기: ${이.명령}`);
      if (이.비고) console.log(`      ↩ ${이.비고}`);
    });
  }
  if (s.진행.length) {
    console.log(`⏳ 도는 중 ${s.진행.length}건:`);
    s.진행.forEach((x) => console.log(줄(x)));
  }
  return 0;
}

/* 🔴 F541 — 「사유가 «다른 지적»을 논하는 기각」을 막는다 (실측 2026-08-17).
 *   같은 논증이 키를 **하나 밀려** 등록돼, 진짜 P1(`tools/rot-check.js:300`)이 영구 기각되고
 *   정작 틀린 지적(`tools/lib/loom.js:642`)은 게이트에 그대로 남았다. 양쪽 다 「통과」로 샌다.
 * 🔑 왜 사람이 못 봤나 — 장부 행은 제목·파일을 **키에서** 채운다. 그래서 「제목: 알 수 없는 숫자형
 *   장부 상태 · 파일: rot-check.js · 사유: (loom 이야기)」가 **겉보기엔 완벽하게 정상인 행**이 된다.
 *   제목과 사유를 나란히 놓기 전엔 안 보인다(신뢰성 ④ 「맞는 얼굴로 틀린 값을 내는 자리」).
 * ⚠ 대가를 함께 적는다: 사유가 남의 파일을 «참고로» 인용하는 정당한 기각이 실재한다. 그래서
 *   차단으로 끝내지 않고 `--딴파일` 확인 손잡이를 준다 — 따를 수 없는 처방은 우회를 정상 통로로
 *   만든다(F103). 닫는 것 1개 = 「사유가 아무 파일도 안 짚으면 판정하지 않는다」(산문 기각은 정상).
 * @returns {{대상:string, 남:string[]}|null} null = 어긋남 없음(또는 판정할 재료가 없음)
 */
function 사유_파일어긋남(원본, 사유) {
  const 대상 = 원본 && 원본.파일;
  // `(기능체크)`·`(모름)` 은 파일이 아니다 — 없는 것을 대조하면 그 자체가 거짓양성이다
  if (!대상 || 대상.startsWith('(') || !/\./.test(대상)) return null;
  const 이름 = 대상.split(/[\\/]/).pop();
  if (사유.includes(대상) || 사유.includes(이름)) return null;   // 자기 파일을 짚었다 = 정상
  const 남 = [...new Set((사유.match(/[\w가-힣.\-/\\]+\.(?:js|mjs|cjs|ts|tsx|json|md|sql|py|html|css|yml|yaml)\b/g) || [])
    .filter((p) => p.split(/[\\/]/).pop() !== 이름))];
  return 남.length ? { 대상, 남 } : null;                        // 아무 파일도 안 짚으면 판정 안 한다
}

function main(argv) {
  if (argv.includes('--help') || argv.includes('-h')) { console.log(사용법); return 0; }

  /* 한도 우회는 env 로 — 여기서 한 번 심으면 회차 자식·던지기 자식까지 spawn env 로 흐른다. */
  if (argv.includes(한도무시플래그)) process.env[런.한도무시키] = '1';

  /* 🔑 **대상 저장소를 맨 먼저 연다** — 아래 모든 조회(장부 범위·미처분·런 대상)가 이 값에
   *   매달린다. 인자 검사(F135)보다 앞이지만 조용히 접히지 않는다: 못 열면 확인 불가(2)로 죽고
   *   사유가 나온다. 여는 순간 argv 의 값이 절대 경로로 고쳐져 자식들이 같은 저장소를 연다. */
  try { 저장소열기(argv); } catch (e) {
    console.error('🔴 확인 불가 — 검수가 **안 돌았다**(통과가 아니다): ' + e.message);
    return 2;
  }

  /* 자식 진입점 — 부모가 띄운 **회차 하나만** 돌고 체크포인트에 적고 끝난다.
   * 사람이 부를 일이 없어 사용법에 안 싣는다. 실패도 마커로 남긴다 — 안 남기면 부모 폴링이
   * 상한까지 헛돌고, 그 시간은 사람이 기다린 시간이다. */
  if (argv[0] === 회차실행플래그) {
    const 방 = argv[1];
    const i = Number(argv[2]);
    const 단계 = argv[3] || '검수';
    const 입력 = 방 ? 런.json읽기(방, '입력', 0) : null;
    if (!방 || !Number.isInteger(i) || !입력 || !아는단계.has(단계)) {
      console.error(`${회차실행플래그}: 방·회차·단계·입력이 갖춰지지 않았다(부모가 쓰는 내부 진입점이다)`);
      return 2;
    }
    if (입력.분석) 모델설정.분석 = 입력.분석;
    if (입력.구조화) 모델설정.구조화 = 입력.구조화;
    /* 🔑 대상 저장소는 **방에서** 받는다 — 이 진입점의 argv 는 `[--회차실행, 방, i, 단계]` 넷뿐이라
     *   `--저장소` 가 아예 없다. 안 받으면 자식이 이 집에서 git·codex 를 돌려 **딴 저장소를 검수**하고,
     *   그 결과가 부모 방에 「끝난 회차」로 들어간다(맞는 얼굴로 틀린 값 · 조용하다). */
    if (입력.저장소) 저장소잡기(입력.저장소);
    try {
      if (단계 === '심문') {
        const s = 입력.심문;
        const 픽 = s && s.런들 && s.런들[i - 1];
        if (!픽) throw new Error('심문 편성이 방에 없다');
        모델설정.분석 = 픽;
        const { 경로: 결과 } = 심문결과경로(s.절대, 픽.이름, i, 픽.effort);
        codex(['exec', ...잠금플래그, ...모델플래그(픽), '--ephemeral', '-o', 결과, '-'],
          s.프롬프트, s.timeoutMs, `설계 심문 ${i}/${s.회차}(${픽.model})`);
        /* 형식 미통과는 **실패로 남긴다** — 파일은 생겼는데 거부 응답이면 부모의 `단계끝났나` 가
         * 영원히 false 라 폴링이 상한까지 헛돈다. 사람이 기다리는 시간이 그 값이다. */
        if (!심문형식통과(심문결과읽기(결과))) throw new Error(`심문 ${i} 결과가 형식을 통과하지 못했다(거부 의심)`);
      } else if (단계 === '기능') {
        /* 프롬프트를 자식이 다시 조립하지 않는다 — diff·채택제안·방향이 그 사이 바뀌면 회차마다
         * 다른 질문을 던진 것이 되고, 합쳐 읽는 순간 조건 통제가 깨진다(심문의 F281 과 같은 축). */
        /* 회차마다 **제 렌즈의** 프롬프트를 집는다(③). 옛 방(단수 칸)을 이어받을 때를 위해 폴백을 둔다. */
        const 내프롬프트 = (입력.기능프롬프트들 && 입력.기능프롬프트들[i - 1]) || 입력.기능프롬프트;
        if (!내프롬프트) throw new Error(`기능체크 프롬프트가 방에 없다(회차 ${i})`);
        런.json쓰기(방, '기능', i, 스키마실행(내프롬프트, 기능체크스키마경로, 입력.timeoutMs,
          `codex 기능체크 ${i}/${입력.회차}·${기능렌즈(i).이름}(${모델설정.분석.model}/${모델설정.분석.effort})`));
      } else {
        /* 기능 쪽과 **같은 모양으로** 막는다 — 이 칸들은 부모가 자식을 띄우기 전에 적어야 하는데,
         * 단계 병렬로 띄우는 순서가 바뀌면서 「아직 안 적힌 방」을 읽을 수 있게 됐다(2026-08-12).
         * 없이 들어가면 `대상.flags` 에서 TypeError 로 죽고, 부모는 순차 폴백으로 **완주해 버린다**
         * — 증상이 「가끔 안 빨라짐」뿐이라 아무 데도 안 적힌다. 그래서 이름을 붙여 남긴다. */
        if (!입력.대상) throw new Error('검수 대상이 방에 없다(부모가 띄우기 전에 입력을 안 적었다)');
        검수한회(입력.대상, 입력.timeoutMs, 방, i, 입력.검수회차 || 입력.회차);
      }
      return 0;
    } catch (e) {
      런.조각쓰기(방, `실패-${단계}`, i, String((e && e.message) || e));
      console.error(`${단계} 회차 ${i} 실패 — ${(e && e.message) || e}`);
      return 2;
    }
  }

  if (argv.includes('--런목록')) return 런현황();
  if (argv.includes('--미처분')) return 미처분현황();
  if (argv.includes('--런처분')) {
    const id = argv[argv.indexOf('--런처분') + 1];
    const 사유 = argv.includes('--사유') ? argv[argv.indexOf('--사유') + 1] : '';
    if (!id || /^--/.test(id)) { console.error('사용: --런처분 <런ID> [--사유 "무엇을 했나"]'); return 2; }
    if (!런.처분(id, 사유)) { console.error(`모르는 런 "${id}" — 오타로 허공에 도장을 찍으면 진짜 런이 미처분으로 남는다.`); return 2; }
    console.log(`처분 도장: ${id}${사유 ? ' — ' + 사유 : ''} (다음 세션부터 안 알린다)`);
    return 0;
  }

  /* 「그 자리에서 끈다」 — F334 의 교훈이 요구한 동작이다(무효가 된 진행 중 작업을 끄고 명시한다).
   * 사유를 필수로 받는다: 왜 껐는지가 안 남으면 다음 세션이 같은 것을 다시 던진다. */
  if (argv.includes('--런중단')) {
    const id = argv[argv.indexOf('--런중단') + 1];
    const 사유 = argv.includes('--사유') ? argv[argv.indexOf('--사유') + 1] : '';
    if (!id || /^--/.test(id)) { console.error('사용: --런중단 <런ID> --사유 "왜 끄나"'); return 2; }
    if (!사유) { console.error('중단에는 사유가 필요하다 — 없으면 다음 세션이 같은 것을 다시 던진다.'); return 2; }
    const r = 런.중단(id, 사유);
    if (!r.ok) { console.error(`🔴 중단 실패 — ${r.왜}`); return 2; }
    console.log(r.이미죽음
      ? `이미 죽어 있었다 — 상태만 「중단」으로 적었다: ${id} (${사유})`
      : `껐다(pid ${r.pid}): ${id} — ${사유}`);
    return 0;
  }

  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (값플래그.includes(a)) { i++; continue; }          // 바로 뒤는 값이다
    if (!a.startsWith('--') || 아는플래그.has(a)) continue;
    console.error(`🔴 모르는 인자 "${a}" — 기본 동작으로 접지 않는다(F135: --help 하나가 14분짜리 런을 조용히 시작시켰다).`);
    console.error(사용법);
    return 2;
  }

  /* 던지기는 **인자 검사 뒤**다 — 오타를 안은 채 던지면 그 프로세스는 세션 밖에서 조용히 죽고,
   * 사람은 30분 뒤에야 「런이 멈춤」으로 그 오타를 알게 된다. 여기서 걸러야 즉시 안다. */
  if (argv.includes(던지기플래그)) return 던지기(argv);

  /* ②설계 심문 — 대상이 문서라 미커밋 판정·지문 결속(①의 것)을 타지 않는다. 그래서 맨 앞에서 가른다.
   * 기본 타임아웃이 ① 보다 긴 이유: 실측 20분(F121). 여기서 짧게 끊으면 「확인 불가」만 쌓인다. */
  if (argv.includes('--심문')) {
    /* `--저장소` 는 ①검수 전용이다 — ②심문은 **문서 경로를 그대로** 받으므로(`path.resolve(대상)`)
     * 형제 저장소 문서도 이미 인자 하나로 심문할 수 있고, git 도 clasp 도 안 탄다. 여기서 조용히
     * 받으면 「이 플래그를 줬으니 결과·장부도 그쪽에 남겠지」라는 틀린 그림이 생긴다 — 결과는
     * 언제나 이 집(`docs/_ops/심문결과`)에 남는다. 그래서 조용히 받지 않고 사실을 말한다. */
    if (타저장소()) {
      console.error(`🔴 ${저장소플래그} 는 ①검수(git 대상) 전용이다 — ②심문은 문서 경로를 그대로 받는다.`);
      console.error(`   그대로 부르면 된다: node tools/codex-review.js --심문 <문서 경로>  (형제 저장소 문서도 경로만 주면 된다)`);
      console.error('   심문 결과·장부는 어느 문서를 심문하든 이 저장소(docs/_ops/심문결과 · 심문기록.jsonl)에 남는다.');
      return 2;
    }
    const 초 = argv.includes('--timeout') ? Number(argv[argv.indexOf('--timeout') + 1]) : 1800;
    return 심문실행(argv, 초 * 1000);
  }

  // 제안 판정 — 클로드(또는 유호님)가 채택/기각을 장부에 남긴다
  if (argv.includes('--제안판정')) {
    const k = argv[argv.indexOf('--제안판정') + 1];
    const 채택 = argv.includes('--채택');
    const 기각 = argv.includes('--기각');
    const 사유 = argv.includes('--사유') ? argv[argv.indexOf('--사유') + 1] : '';
    if (!k || 채택 === 기각) {
      console.error('사용: --제안판정 <키> --채택 [--사유 "..."]  또는  --제안판정 <키> --기각 --사유 "왜"');
      return 2;
    }
    if (기각 && !사유) {
      console.error('기각에는 사유가 필요하다 — 없으면 다음 회차에 왜 안 하는지 설명할 수 없다.');
      return 2;
    }
    const 현황 = 제안현황();
    if (!현황.has(k)) {
      console.error(`모르는 제안 키 "${k}" — 오타로 허공에 판정을 남기면 진짜 제안이 미판정으로 남는다.`);
      return 2;
    }
    const p = 현황.get(k);
    /* 판정 행에도 **대상과 방향**을 박는다 — 지금까지 판정 행은 키만 들고 있어서, 그 판정이 어느
     * 변경의 제안에 대한 것이고 어느 방향 아래서 내려졌는지 **행 스스로 말하지 못했다.**
     * 대상·변경은 원 제안 행에서 그대로 **복사**한다(새로 계산하면 같은 판정을 두 곳에서 정하게 된다 —
     * 판정 시점의 작업본은 제안 시점과 이미 다르므로 다시 재면 딴 변경을 가리킨다). */
    append(제안경로, {
      종류: '판정', 시각: new Date().toISOString(),
      ...저장소스탬프(),
      대상: p.대상 || null, 방향: 방향지문(), 철학: 철학지문(), 변경: p.변경 || null,
      키: k, 상태: 채택 ? '채택' : '기각', 사유,
    });
    console.log(`${채택 ? '채택' : '기각'}: ${p.제목}${사유 ? ' — ' + 사유 : ''}`);
    console.log(채택
      ? '구현한 뒤 최종 검수(node tools/codex-review.js)를 돌린다 — 기능체크가 구현 여부까지 본다.'
      : '이 제안은 다음 선파악 프롬프트에 「기각됨」으로 실려 다시 올라오지 않는다.');
    return 0;
  }

  /* ── 기록행 무효 표식 (2026-09-03) — 「이 행은 검수 도장이 아니다」를 **장부에** 남긴다.
   *
   * 쓰는 자리: 방 열쇠 충돌·중단 등으로 기록행의 «지문»과 «지적»이 서로 다른 검수의 것이 됐을 때.
   *   그 행은 지우면 안 되고(append-only), 지적을 `--기각` 해도 안 된다 — 지적 자체는 남의 진짜
   *   결함이라 기각하면 재발 필터에서 영구히 사라진다. 무효로 만드는 것은 «행과 지문의 짝»이다.
   * 🔑 짝을 못 찾아도 **적는다**(다른 워크트리에 있는 행일 수 있다 · 장부는 union 으로 합쳐진다).
   *   대신 조용히 넘기지 않고 큰 소리로 말한다 — 오타로 허공에 표식을 남기면 정작 그 행은
   *   계속 게이트를 막는데 사람은 처리했다고 믿는다(새는 방향은 「막힘」이라 안전하되, 시간을 태운다). */
  if (argv.includes('--기록무효')) {
    const 시각 = argv[argv.indexOf('--기록무효') + 1];
    const 사유 = argv.includes('--사유') ? argv[argv.indexOf('--사유') + 1] : '';
    if (!시각 || /^--/.test(시각) || !사유) {
      console.error('사용: --기록무효 <기록행 시각(ISO)> --사유 "왜 이 행이 도장이 아닌가"');
      console.error('  예: node tools/codex-review.js --기록무효 2026-09-03T00:17:59.689Z --사유 "방 열쇠 충돌 — 지적이 옆 세션 것이다"');
      return 2;
    }
    const 행들 = 장부읽기(기록경로);
    const 대상행 = 행들.filter(검수행인가).find((r) => r.시각 === 시각);
    if (!대상행) {
      console.error(`⚠ 이 트리의 장부(${path.relative(ROOT, 기록경로).replace(/\\/g, '/')})엔 시각 "${시각}" 인 검수 기록행이 **없다**.`);
      console.error('   표식은 적는다 — 그 행이 다른 워크트리·브랜치에 있으면 장부가 합쳐질 때(merge=union) 붙는다.');
      console.error('   시각을 잘못 쳤다면 이 표식은 아무것도 안 지운다(그 행은 계속 게이트를 막는다). 장부에서 시각을 확인해라.');
    } else {
      console.log(`무효로 표시할 행: ${시각} · 대상 ${대상행.대상 ? `${대상행.대상.종류} ${대상행.대상.값}` : '(모름)'} · 변경 ${대상행.변경 || '(없음)'}`);
      console.log(`   지문 ${JSON.stringify(대상행.지문 || {})} · 지적 ${(대상행.지적 || []).length}건`);
    }
    append(기록경로, { 종류: '무효', 시각: new Date().toISOString(), ...저장소스탬프(), 무효행: 시각, 사유 });
    console.log(`\n표식을 적었다 — 배포 게이트는 이 행을 **도장으로 세지 않는다**(장부에는 그대로 남는다).`);
    console.log('   지적은 손대지 않았다 — 그 지적들이 진짜라면 원래 임자의 장부에서 그대로 살아 있어야 한다.');
    return 0;
  }

  // 처분 등록 — 세 레버가 **한 통로**를 탄다(호출부마다 고치는 대신 잘못 쓸 수 없는 공용 통로)
  {
    const 쓴레버 = 처분레버들.find((L) => argv.includes(L.플래그));
    if (쓴레버) {
      const k = argv[argv.indexOf(쓴레버.플래그) + 1];
      const 사유 = argv.includes('--사유') ? argv[argv.indexOf('--사유') + 1] : '';
      if (!k || !사유) {
        console.error(`사용: ${쓴레버.플래그} <키> --사유 "왜"  (사유 없는 처분은 받지 않는다 — 다음 회차에 왜 그랬는지 설명할 수 없다)`);
        return 2;
      }
      /* 원본은 **이 저장소의 기록에서만** 찾는다 — 안 가르면 형제 저장소의 같은 이름 지적을
       * 원본으로 집어 F541 검사가 엉뚱한 파일을 대조하고, 처분 행에도 남의 제목이 박힌다. */
      const 원본 = 장부읽기(기록경로).flatMap((r) => r.지적 || []).find((f) => f.키 === k);
      const 딴파일 = argv.includes('--딴파일');
      const 어긋남 = 딴파일 ? null : 사유_파일어긋남(원본, 사유);
      if (어긋남) {
        console.error(`[F541] 사유가 «${어긋남.대상}» 을 한 번도 안 짚고 다른 파일만 논한다 — ${어긋남.남.join(' · ')}`);
        console.error(`   이 키 "${k}" 는 ${원본.제목} (${어긋남.대상}) 이다.`);
        console.error('   키를 하나 밀려 친 모양이다. 그러면 **진짜 결함이 영구 기각되고 틀린 지적은 게이트에 남는다**');
        console.error('   — 2026-08-17 에 실제로 그랬다(F541). 장부 행은 제목·파일을 키에서 채우므로 겉보기엔 정상이다.');
        console.error('   → 키가 틀렸으면 맞는 키를 찾아 다시: node tools/codex-review.js --확인  (키·파일이 나란히 나온다)');
        console.error('   → 남의 파일을 참고로 인용한 것이고 키가 맞으면: 같은 명령에 --딴파일 을 붙인다');
        return 2;
      }
      /* 🔑 `'지문'` 레버(대상아님)는 **찍힌 지문에서만** 게이트를 연다 — 그래서 처분하는 순간의
       *   지문을 프로젝트별로 함께 박는다(검수 기록과 같은 `{이름: fp}` 모양). 안 박으면 그 행은
       *   게이트에서 영원히 무효라, 08-17 처분 4건이 실제로 그랬다(F588).
       * ⚠ 지문을 못 재면 **적지 않는다** — 빈 값을 넣으면 「어느 배포에 대한 판정인지 모름」이
       *   조용히 「통과」가 된다. 없으면 게이트가 안 열리고, 그게 맞는 방향이다. */
      let 지문 = null;
      if (레버of(쓴레버.처분) && 레버of(쓴레버.처분).게이트해소 === '지문') {
        지문 = {};
        for (const p of 클라스프프로젝트들()) {
          const nm = path.relative(ROOT, p).replace(/\\/g, '/') || '(루트)';
          try { 지문[nm] = 점검.지문(p, ROOT); } catch (_) { /* 못 재면 그 프로젝트는 비운다 */ }
        }
        if (!Object.keys(지문).length) 지문 = null;
      }
      append(기각경로, {
        시각: new Date().toISOString(), ...저장소스탬프(),
        키: k, 파일: 원본 ? 원본.파일 : '(모름)', 제목: 원본 ? 원본.제목 : '(모름)', 사유,
        처분: 쓴레버.처분,
        ...(지문 ? { 지문 } : {}),
        // 확인하고 지난 것은 «지났다»고 적는다 — 안 적으면 다음 사람이 이 행을 F541 로 다시 의심한다
        ...(딴파일 ? { 딴파일확인: true } : {}),
      });
      console.log(`${쓴레버.처분} 등록: ${k} — ${사유}${타저장소() ? ` (저장소 ${저장소이름(대상ROOT)})` : ''}`);
      console.log(`   ${쓴레버.다음런}`);
      /* 형제 저장소엔 지문에 걸 배포 게이트가 없다 — 「등록됨」만 찍고 지나가면 나중에 아무도
       * 「왜 안 열렸나」를 못 찾는다(F588 이 정확히 그 모양이었다). 그 사실을 그 자리에서 말한다. */
      if (타저장소() && 레버of(쓴레버.처분) && 레버of(쓴레버.처분).게이트해소 === '지문') {
        console.log('   ⚠ 이 저장소엔 Apps Script 배포 게이트가 없다 — 이 처분은 «재발 필터 축»에서만 뜻이 있고 지문 결속은 안 한다.');
      }
      if (지문) {
        console.log(`   지문 결속: ${Object.entries(지문).map(([n, v]) => `${n}=${v}`).join(' · ')}`);
        /* 과녁 검사 결과를 **그 자리에서** 말한다 — 조용히 「등록됨」만 찍으면 게이트가 안 열린
         * 이유를 나중에 아무도 못 찾는다(F588 이 정확히 그 모양이었다). */
        for (const p of 클라스프프로젝트들()) {
          const nm = path.relative(ROOT, p).replace(/\\/g, '/') || '(루트)';
          let 집합 = []; try { 집합 = 점검.배포집합(p, ROOT) || []; } catch (_) {}
          if (!집합.length) continue;
          const 밖 = 과녁이배포집합밖(원본, 집합);
          console.log(`   ${밖 ? '✅' : '🔴'} ${nm}: 과녁이 배포집합 ${밖 ? '밖 — 이 지문에서 게이트가 열린다' : '**안**(또는 판정 불가) — 이 처분으로는 게이트가 안 열린다'}`);
        }
      }
      return 0;
    }
  }

  // 게이트 조회
  if (argv.includes('--확인')) {
    /* 🔴 형제 저장소엔 **이 게이트가 없다.** 여기서 프로젝트 0건을 돌고 0(=차단 없음)을 내면
     *   「통과」와 「잴 것이 없었다」가 같은 모양이 된다 — 이 파일 머리말이 종료코드로 지키는 바로
     *   그 구분이다. 그래서 확인 불가(2)를 내고 **그 저장소의 진짜 게이트**를 이름으로 댄다. */
    if (타저장소()) {
      console.error(`🔴 확인 불가 — ${저장소이름(대상ROOT)} 에는 이 게이트가 **없다**(통과가 아니다).`);
      console.error('   이 조회가 재는 것은 Apps Script 배포 게이트(clasp-guard)뿐이고, 그건 이 저장소에만 있다.');
      console.error('   → SYNK-talk 의 배포 게이트는 `node tools/원격배포.js` 의 배포판 대조다(그쪽 저장소에서 부른다).');
      console.error(`   이 저장소의 검수 기록·처분을 보려면: node tools/codex-review.js --미처분 ${저장소플래그} ${대상ROOT}`);
      return 2;
    }
    let 최악 = 0;
    for (const p of 클라스프프로젝트들()) {
      const r = 게이트판정(p, ROOT);
      console.log(r.lines.join('\n'));
      if (r.level === 'block') 최악 = Math.max(최악, 1);
    }
    return 최악;
  }

  /* 어느 저장소를 재는지 **맨 먼저** 말한다 — 대상이 sha 뿐이면 그 줄만 보고는 어느 저장소의
   * 커밋인지 알 수 없고, 형제 저장소가 들어온 뒤로 그 모호함은 사고 재료다. */
  if (타저장소()) console.log(`저장소: ${저장소이름(대상ROOT)} (${대상ROOT}) — 이 도구의 집이 아니다`);

  let 대상;
  try {
    대상 = 대상결정(argv);
  } catch (e) {
    /* 🔴 08-31 실측이 정확히 이 자리였다 — talk 커밋 sha 를 여기서 못 읽어 죽었고, 사유가
     *   `fatal: ambiguous argument` 뿐이라 도구 결함으로 읽혔다. 이제 원인이 둘로 갈린다
     *   (정말 없는 개정 · 저장소를 안 댔다) — 그 갈래를 말해 준다.
     * ⚠ 가르는 축은 **git 의 말투가 아니다.** 없는 개정의 문구는 셋으로 갈린다(실측 08-31:
     *   짧은 sha → `ambiguous argument` · 40자 sha → `bad object` · 브랜치 → `ambiguous argument`).
     *   문구 목록으로 재면 넷째 문구가 생기는 날 조용히 침묵한다 — 낡는 목록은 안 쓴다.
     *   축은 「집에서 **개정을 대고** 부르다 못 읽었나」다. `확인불가` 표가 붙은 것은 git 이 이미
     *   제 처방을 낸 것(버퍼 초과)이라 여기서 두 번째 처방을 얹지 않는다. */
    const 지정개정 = argv.includes('--commit') ? argv[argv.indexOf('--commit') + 1]
      : argv.includes('--base') ? argv[argv.indexOf('--base') + 1] : null;
    console.error('🔴 확인 불가 — 검수가 **안 돌았다**(통과가 아니다): ' + String((e && e.message) || e).split('\n')[0]);
    if (!타저장소() && 지정개정 && !(e && e.확인불가)) {
      console.error(`   이 저장소에서 «${지정개정}» 를 못 읽었다. 형제 저장소(SYNK-talk 등)의 개정이면 저장소를 대라:`);
      console.error(`   → node tools/codex-review.js ${저장소플래그} ../SYNK-talk ${argv.includes('--base') ? '--base' : '--commit'} ${지정개정}`);
    }
    return 2;
  }
  if (!대상.파일들.length) {
    console.log('검수할 변경이 없다 — 대상 diff 가 비었다.');
    return 0;
  }
  const 기각들 = 장부읽기(기각경로);
  const 범위들 = 범위(대상.파일들);

  // 선택지는 둘뿐이다(sol·luna · 둘 다 high · 유호 확정 08-15). `--효력` 은 1회성 조정 — 더 깊게는 `--효력 max`.
  let 회차, 편성;
  try {
    모델설정.분석 = 정책.분석설정(argv);
    회차 = 정책.회차설정(argv);     // 기본 2 — 근거는 tools/모델정책.js
    편성 = 벤더편성(argv, 회차);    // `--벤더` 검사도 지금 — 모르는 값은 몇 분 뒤가 아니라 여기서 거절한다
    모델플래그(모델설정.분석);      // 조합 검사를 **먼저** 한다 — 몇 분 기다린 뒤 오타를 알 이유가 없다
    모델플래그(모델설정.구조화);    // 2단계도 지금 — 1단계가 끝난 뒤 죽으면 그 몇 분이 통째로 버려진다
  } catch (e) {
    console.error('🔴 확인 불가 — 검수가 **안 돌았다**(통과가 아니다): ' + e.message);
    return 2;
  }

  /* 900 이 아닌 이유(F249 · 2026-08-08 실측): max 추론 검수가 900 초를 넘겼고, 타임아웃 없이
   * 직접 돌리니 15분을 넘겨 **완주해 P1 1건·P2 2건을 냈다** — 안 도는 게 아니라 못 기다린 것이었다.
   * 심문(위)이 1800 인데 더 무거운 검수가 900 이던 역전을 없앤다. */
  const 초 = argv.includes('--timeout') ? Number(argv[argv.indexOf('--timeout') + 1]) : 1800;

  // ① 설계 선파악 모드 — 버그 검수 대신 기능지도+업그레이드 제안만 내고 끝낸다
  if (argv.includes('--제안')) {
    console.log(`대상: ${대상.종류} ${대상.값} · 파일 ${대상.파일들.length}개`);
    try {
      return 제안실행(argv, 대상, 초 * 1000);
    } catch (e) {
      if (e.확인불가) {
        console.error('🔴 확인 불가 — 선파악이 **안 돌았다**: ' + e.message);
        console.error('   제안 단계는 게이트와 무관하다 — 최종 검수(버그+기능체크)로 그냥 진행해도 된다.');
        return 2;
      }
      throw e;
    }
  }

  console.log(`대상: ${대상.종류} ${대상.값} · 파일 ${대상.파일들.length}개`);
  /* 🔴 형제 저장소에서 「범위: 없음」은 «안 잰 것»이 아니라 «잴 것이 없는 것»이다 — 두 뜻이 같은
   *   문구로 나가면 다음 사람이 이 검수를 「반쪽」으로 읽는다. 그리고 여기서 **그 저장소의 진짜
   *   게이트가 무엇인지** 같이 댄다: 검수 초록을 배포 허가로 읽는 것이 이 도구가 가장 두려운 오독이다. */
  if (타저장소()) {
    console.log('검수 범위(clasp 프로젝트): 해당 없음 — 이 저장소엔 Apps Script 배포층이 없다(빠뜨린 게 아니다).');
    console.log('   ⚠ 그래서 이 검수는 **배포 게이트를 열지도 막지도 않는다**. clasp-guard 는 이 기록을 원리상 안 읽는다.');
    console.log('   → SYNK-talk 의 배포 게이트는 `node tools/원격배포.js` 의 배포판 대조다(그쪽 저장소에서 따로 부른다).');
  } else {
    console.log(`검수 범위(clasp 프로젝트): ${범위들.length ? 범위들.join(', ') : '없음 — 배포 파일이 아닌 변경'}`);
  }

  /* 실행 전 정지 — 태우고 나서 「범위 밖이었다」를 알게 되는 자리를 없앤다(F314 · 위 설계 주석). */
  if (!argv.includes(범위밖탈출)) {
    const 정지 = 범위밖정지(대상, 범위들);
    if (정지) { console.error('\n' + 정지.join('\n')); return 2; }
  }
  /* 0 은 분모와 함께 읽는다 — 「이력 81건으로 걸러낸다」는 그중 몇 건이 실제로 거르는지를 감춘다. */
  if (기각들.length) {
    const 셈 = 처분레버들.map((L) => `${L.처분} ${기각들.filter((r) => 처분of(r) === L.처분).length}`).join(' + ');
    console.log(`처분 이력 ${기각들.length}건 = ${셈} — 이 중 «기각»만 재발 필터로 걸러낸다.`);
  }

  진행걸기(argv, { 단계: '③최종검수', 대상: { 종류: 대상.종류, 값: 대상.값 }, 회차, 인자: argv });

  console.log(`모델: 분석=${모델설정.분석.model}/${모델설정.분석.effort}(${모델설정.분석.이름}) · 구조화=${모델설정.구조화.model}/${모델설정.구조화.effort} · 판단 패스 ${회차}회`);
  console.log(`codex 검수 중… (읽기 전용 샌드박스 · 2단계 · ${모델설정.분석.effort} 추론 — xhigh 실측이 5~8분이었다` +
    (회차 > 1 ? ` · ${회차}회라 그 배로 걸린다` : '') + ')');
  console.log(소요안내(argv, 회차));

  /* 변경지문(change_id) — 기능체크에 **실제로 실릴 그 바이트**로 만든다. 그래야 선파악이 같은
   * 손잡이로 남긴 기능지도를 되찾을 수 있다. `--버그만` 이어도 장부엔 박는다(행마다 붙어야 계보다).
   * 🔑 이 수집이 **검수보다 앞**인 것은 08-12 변경의 요구였다 — 기능 자식을 검수와 동시에 띄우려면
   *   그 프롬프트가 먼저 방에 있어야 한다. 덤으로 정확도도 오른다: 예전엔 검수 8~13분이 지난
   *   뒤에 diff 를 떴는데, `--uncommitted` 대상은 그 사이 남의 세션이 커밋하면 **검수한 것과
   *   다른 diff** 로 기능체크를 돌리고 있었다(같은 방·다른 입력 · 시점 의존 · F073 인접).
   * 🔴 이제 **방보다도 앞**이다(09-03) — 이 지문이 곧 방 열쇠의 «내용» 축이라 방을 열기 전에 있어야
   *   한다. 자를 하나 더 만들지 않고 장부의 `변경`(change_id)을 그대로 쓴다(한 판정엔 자 하나). */
  const diff본문 = 디프수집(대상);
  const 변경fp = 변경지문(diff본문);

  /* 방을 **여기서** 연다 — 버그 사냥과 기능체크가 같은 방을 써야 한쪽이 죽어도 다른 쪽 결과가
   * 산다. 방마다 갈라 두면 「기능체크에서 죽었는데 검수까지 다시」가 되어 F334 가 반만 닫힌다. */
  // 방 지문의 총회차 = 검수 편성 길이 — `--벤더 둘` 과 codex 단독이 같은 방을 쓰면 한쪽이 다른 쪽 회차를 이어받는다
  const 방경로 = 검수방(대상, 편성.length, argv, 변경fp);
  console.log(`체크포인트: ${방경로} — 중간에 죽어도 끝난 회차는 다시 안 돈다(같은 명령을 그대로 다시 부르면 이어받는다).`);
  console.log(`   방 열쇠에 이 변경의 내용 지문(${변경fp})이 들어간다 — 옆 세션이 «다른 미커밋»을 검수 중이어도 그 방을 이어받지 않는다(09-03).`);
  if (편성.length > 회차) console.log(`벤더 편성: ${편성.join(' → ')} — 마지막 회차는 gemini(둘째 검수자 · diff 만 · API 키 레인). 게이트는 codex 가 진다.`);
  /* 프롬프트를 방에 넣어 자식과 **같은 질문**을 쓰게 한다(자식이 다시 조립하면 회차마다 다른
   * 질문이 되고, 그 순간 회차 대조가 원리상 무효다 — 심문의 F281 과 같은 축). */
  /* 회차마다 **다른 렌즈**의 프롬프트를 만든다(③). 재료(diff·채택제안·방향·철학·아는미완)는 **한 번만**
   * 뽑아 회차 사이에 공유한다 — 회차마다 다시 뽑으면 그 사이 바뀐 것이 섞여, 갈린 것이 렌즈 때문인지
   * 재료 때문인지 못 가른다(F045 — 조건은 하나씩 바꾼다). */
  const 미완 = argv.includes('--버그만') ? null : 아는미완줄들();
  /* 🔴 「0줄」을 셋으로 갈라 말한다 — 08-31 talk 첫 런에서 이 한 줄이 「열린 트랙 0개」라고만 적어
   *   **출처가 틀렸다는 사실이 사람 눈에 안 보였다**(지적 3건이 전부 그 대가였다). */
  if (미완 && !미완.출처) {
    console.error(`⚠ 「아는 미완」 — 이 저장소(${저장소이름(대상ROOT)})의 미완 재료를 이 도구가 **모른다**.`);
    console.error('   0건이 아니라 «출처 없음»이다. 재료 표 = codex-review.js 의 `아는미완출처들`.');
  } else if (미완 && 미완.오류) {
    console.error(`⚠ 「아는 미완」 재료(${미완.출처.이름})를 못 읽었다 — ${미완.오류}`);
  } else if (미완) {
    console.log(`아는 미완 ${미완.줄들.length}줄을 기능체크에 동봉한다 (출처: ${미완.출처.이름} · 전체 ${미완.전체}건).`);
  }
  const 채택제안 = argv.includes('--버그만') ? [] : 채택제안줄들();
  const 기능프롬프트들 = argv.includes('--버그만') ? null
    : Array.from({ length: 회차 }, (_, i) =>
      기능체크프롬프트(diff본문, 채택제안, 방향텍스트(), 철학텍스트(), 기능렌즈(i + 1), 미완));
  if (기능프롬프트들 && 회차 > 1) {
    console.log(`기능체크 렌즈: ${Array.from({ length: 회차 }, (_, i) => `${i + 1}회 ${기능렌즈(i + 1).이름}`).join(' · ')}` +
      '\n   ↳ 회차가 서로 «다른 각도»라 원건 수를 앞 회차와 직접 빼지 마라(F281 — 분모가 바뀌었다).');
  }

  /* ⚠ 자식이 읽을 칸은 **띄우기 전에 전부** 적는다. 예전엔 `codex실행` 이 열리면서 `대상`·
   *   `timeoutMs`·`회차` 를 적었는데, 이제 자식을 그보다 **먼저** 띄우므로 그 순서로는 검수
   *   자식이 `대상 = undefined` 를 읽는다. 새는 방향이 나쁘다 — 자식은 조용히 죽고 부모는
   *   순차 폴백으로 완주하니, 증상이 「가끔 안 빨라짐」뿐이고 아무 데도 안 적힌다. */
  입력쓰기(방경로, {
    대상, timeoutMs: 초 * 1000, 회차, 검수회차: 편성.length, 벤더들: 편성, 분석: 모델설정.분석, 구조화: 모델설정.구조화,
    // 회차 자식은 argv 로 이걸 못 받는다(`--회차실행` 은 인자가 넷뿐이다) — 방이 유일한 통로다
    ...(타저장소() ? { 저장소: 대상ROOT } : {}),
    /* 회차별 배열로 적는다. 옛 판의 단수 `기능프롬프트` 도 함께 남긴다 — 이 커밋 **전에** 시작된
     * 방을 이어받을 때 자식이 그 칸을 읽기 때문이다(체크포인트 하위호환 · 없으면 「방에 없다」로 죽는다). */
    ...(기능프롬프트들 ? { 기능프롬프트들, 기능프롬프트: 기능프롬프트들[0] } : {}),
  });

  /* ⚡ 단계 병렬 — 검수와 기능체크를 **한꺼번에** 띄운다(판정·근거는 `병렬계획`).
   * 부모는 그 뒤 평소의 순차 루프를 그대로 돈다: 자식이 채운 칸은 이어받아 즉시 돌아오고,
   * 못 채운 칸만 부모가 태운다. 그래서 병렬이 통째로 실패해도 순차 폴백이 공짜다. */
  const 계획 = 병렬계획(argv, 회차, 편성.length);
  if (계획.length) 병렬실행(방경로, 계획, 초 * 1000);

  let 결과;
  try {
    결과 = codex실행(대상, 초 * 1000, 회차, 방경로, argv, true, 편성);
  } catch (e) {
    if (e.확인불가) {
      console.error('🔴 확인 불가 — 검수가 **안 돌았다**(통과가 아니다): ' + e.message);
      // 타임아웃엔 로그인을 의심시키지 않는다 — F249 1회차가 이 힌트를 따라가 시간을 버렸다.
      if (!e.타임아웃) console.error('   codex 로그인 상태는 `codex login status` 로 본다.');
      return 2;
    }
    throw e;
  }

  { const 줄 = 회차별줄(결과 && 결과.회차별, 결과 && 결과.지적); if (줄) console.log(줄); }

  /* ③-2 기능 전수 체크 — 버그 사냥(위)과 별개 패스로, 바뀐 기능 하나하나가 실제로 도는지 본다.
   * 유호님 설계(2026-08-05): 「검수자가 최종적으로 꼼꼼히 버그 체크하고 **업데이트되는 기능
   * 세세히 전부 체크**」. 지적 0건과 「기능 X 는 본 적도 없음」이 같은 모양이면 안 되는 자리다.
   * 깨짐은 P1 지적으로 변환돼 같은 게이트를 탄다. `--버그만` 은 유호님 「빠르게」 모드용. */
  let 기체 = null;
  if (기능프롬프트들) {
    console.log(`기능 전수 체크 중… (같은 모델 · 별도 패스 · ${회차}회)`);
    try {
      const 모음 = [];
      /* 상한을 안 씌운다 — 여기 있던 `Math.min(초 * 1000, 900000)` 은 **처방이 안 닿는 자리**였다.
       * 2026-08-05 도입 당시엔 `초` 기본이 900 이라 무해한 no-op 이었는데, 08-08 에 F249 가 기본을
       * 1800 으로 올리면서 **그날부터 조용히 구속조건이 됐다** — 옆자리만 올리고 이 clamp 를 안 봤다.
       * 증상: 기능체크가 900 초에 끊기며 「`--timeout 1800` 로 늘려 다시 돌린다」를 처방하는데, 그
       * 플래그가 이 자리엔 원리상 안 닿아 **몇 번을 따라도 같은 자리에서 같은 초로 끊긴다**(F103 —
       * 따를 수 없는 처방은 우회를 정상 통로로 만든다 · 08-10 실측 2회, 900 초 ×2·×1).
       * 상한이 필요하면 호출자가 `--timeout` 으로 명시한다 — 여기서 몰래 깎지 않는다. */
      /* 자식은 위에서 검수와 **함께** 띄웠다(`병렬계획`). 여기 남은 것은 순차 폴백뿐이다 —
       * 자식이 채운 회차는 바로 아래 이어받기로 즉시 돌아오고, 못 채운 것만 부모가 태운다. */
      for (let i = 1; i <= 회차; i++) {
        const 이전 = 런.json읽기(방경로, '기능', i);
        if (이전) { console.log(`  ↩ 기능체크 ${i}/${회차} 이어받음 — 이미 끝난 회차다(codex 호출 0).`); 모음.push(이전); continue; }
        const r = 스키마실행(기능프롬프트들[i - 1], 기능체크스키마경로, 초 * 1000,
          `codex 기능체크${회차 > 1 ? ` ${i}/${회차}회·${기능렌즈(i).이름}` : ''}(${모델설정.분석.model}/${모델설정.분석.effort})`);
        런.json쓰기(방경로, '기능', i, r);
        모음.push(r);
      }
      기체 = 기능체크병합(모음);
    } catch (e) {
      if (e.확인불가) {
        console.error('🔴 확인 불가 — 기능체크가 **안 돌았다**(통과가 아니다): ' + e.message);
        return 2;
      }
      throw e;
    }
  } else {
    console.log('(--버그만: 기능 전수 체크 생략 — 유호님 「빠르게」 모드)');
  }

  const 지적 = [...(결과.지적 || []), ...기능체크지적들(기체 && 기체.체크)].map((f) => ({ ...f, 키: 키(f) }));
  const 기각키 = 걸러지는키들(기각들);
  const 신규 = 지적.filter((f) => !기각키.has(f.키));
  /* 안 걸러지는 처분이 다시 올라온 것은 **숨기지 않고 나란히 찍는다** — 채택수리의 재등장은
   * 소음이 아니라 「수리가 덜 됐다」는 신호이고, 조용히 지나가면 그 신호가 죽는다. */
  { const 줄들 = 이전처분줄들(신규, 기각들);
    if (줄들.length) {
      console.log(`\n↩ 이전에 «채택수리·범위밖»으로 처분한 지적이 ${줄들.length}건 다시 올라왔다 — 걸러내지 않았다:`);
      console.log(줄들.join('\n'));
    } }

  /* 폐루프 대조 — 선파악이 알던 기능 중 최종이 안 짚은 것. **지적으로 안 만든다**(채택 범위: 알림).
   * null = 이 변경엔 선파악 자체가 없다. `[]`(미확인 0건)와 절대 같은 모양으로 두지 않는다. */
  const 지도 = 선파악지도(변경fp);
  const 미확인 = 기체 && 지도 ? 미확인기능들(지도, 기체.체크) : null;

  /* 🔴 [2026-08-31 실측] codex 가 «프로세스로는 성공»하고 «내용으로는 못 봤다»고 답하는 자리를 막는다.
   *
   * 무슨 일이 났나 — 이 파일 머리말이 「통과와 미실행을 절대 같은 모양으로 두지 않는다」고 적어 뒀는데,
   *   그 방어가 **CLI 층에만** 있었다(codex 없음·로그인 만료·타임아웃·파싱 실패 → 확인불가=2).
   *   실제로 난 것은 그 밖이다: codex 가 **정상 종료**하고 요약에
   *     「환경에서 명령 실행이 차단되어 저장소를 검사할 수 없었다」
   *   를 적어 냈다. 지적이 없으니 신규 0건 → 종료 0 → **장부에 「지적 0건」으로 기록** →
   *   배포 게이트가 그 지문을 「이종 검수 통과」로 뒤집었다. 한 줄도 안 본 검수가 초록이 된 것이다.
   *   그날 사람이 본문을 읽어서 잡았지 종료코드로는 못 잡았다 — 다음 세션은 못 잡는다.
   *
   * 🔑 자를 「지적 0건일 때만」으로 좁힌 것이 이 검사의 급소다.
   *   지적이 하나라도 있으면 codex 는 **분명히 저장소를 봤다** — 그때 요약에 무슨 낱말이 있든
   *   확인 불가가 아니다. 좁히지 않으면 「명령 실행이 차단되지 않는다」 같은 정상 지적 문장에
   *   걸려 멀쩡한 검수를 죽인다(거짓 적색은 거짓 초록의 반대편 실패다).
   *
   * ⚠ 여기서 **장부에 적기 전에** 죽는다. 적고 나서 죽으면 그 줄이 남아 게이트가 계속 초록이다
   *   (2026-08-31 의 그 줄이 실제로 남았고, 그래서 그날 게이트는 재실행 뒤에도 거짓으로 열려 있었다). */
  {
    const 못봤다징후 = [
      /명령\s*실행이[^\n]{0,24}차단/,             // 09-02 실측 문면: 「저장소 명령 실행이 «정책에 의해» 차단되어」 — 옛 정규식은 사이 낱말에 막혔다
      /저장소를\s*(검사|확인|조회)할\s*수\s*없/,
      /(파일|소스|코드|변경)[을를]?\s*(읽|열)지\s*못/,    // 「파일을 읽지 못했습니다」 — 목적격 조사가 «을»이면 옛 정규식이 안 물었다
      /^\s*확인\s*불가/m,                          // AGENTS.md Code Review Rules ④ — 못 봤으면 첫 줄에 「확인 불가」(codex 가 실제로 따랐다 · 09-02)
      /command\s+execution\s+(was\s+)?blocked/i,
      /unable\s+to\s+(inspect|read|access)\s+the\s+(repo|repository|files)/i,
      /sandbox\s+(denied|blocked|prevented)/i,
      /blocked\s+by\s+policy/i,                     // codex 0.15x 의 실제 거부 문구 — 「Rejected(… rejected: blocked by policy)」
    ];
    const 본문 = String(결과.요약 || '') + '\n' + String(결과.원문 || '');
    const 걸린것 = 지적.length === 0 ? 못봤다징후.find((re) => re.test(본문)) : null;
    if (걸린것) {
      throw 확인불가(
        '검수가 저장소를 못 봤다 — **통과가 아니라 «확인 불가»다.**\n' +
        '  codex 는 정상 종료했지만 요약이 「못 봤다」고 말한다:\n' +
        '    ' + String(결과.요약 || '(요약 없음)').slice(0, 200) + '\n' +
        '  지적 0건이 «깨끗해서»가 아니라 «안 봐서»이므로 장부에 적지 않는다(적으면 게이트가 거짓으로 열린다).\n' +
        '  처방: 같은 명령을 다시 돌린다. 2026-08-31 실측 — 기계가 프로세스 생성에 허덕일 때 났고,\n' +
        '        세션을 몇 개 닫아 부하를 내리자 같은 지문에서 정상 완주했다.');
    }
  }

  append(기록경로, {
    시각: new Date().toISOString(),
    /* 어느 저장소를 잰 행인가 — 없으면 이 집이다(옛 행 전량이 그 모양이다). 이 한 칸이 없으면
     * sha 만 든 행이 어느 저장소의 것인지 스스로 못 말하고, 게이트·필터가 남의 행을 집는다. */
    ...저장소스탬프(),
    대상: { 종류: 대상.종류, 값: 대상.값 },
    // 어느 모델이 어느 추론 수준으로 봤는지 남긴다 — 나중에 「그때 왜 못 잡았나」를 물을 수 있어야 한다
    모델: { 분석: { ...모델설정.분석 }, 구조화: { ...모델설정.구조화 } },
    // 몇 회 돌았고 회차마다 몇 건이었나 — 「2회가 값했나」는 이 분모 없이 못 읽는다
    회차, 회차별: 결과.회차별 || null,
    // 어느 벤더들이 봤나(09-02) — 없으면 codex 만 본 옛 행이다. 회차별 칸이 벤더·서빙모델·확인불가를 쥔다.
    벤더들: 결과.벤더들 || ['codex'],
    /* 기능체크 회차가 **어느 각도**였나(③). 이 칸이 없으면 회차 대조가 원리상 무효다 —
     * 조건이 갈렸는데 무엇이 갈렸는지 안 적히면 다음 사람이 원건 수를 그냥 빼 버린다(F281).
     * `--버그만` 이면 기능체크 자체가 없으므로 null 이고, 그건 「렌즈 0」과 다른 상태다. */
    기능렌즈: 기능프롬프트들 ? Array.from({ length: 회차 }, (_, i) => 기능렌즈(i + 1).이름) : null,
    /* ② 그 런이 「아는 미완」을 몇 줄 동봉했나 — 0 과 「재료를 못 읽었다」가 같은 모양이면 안 된다.
     * 🔑 `출처` 를 함께 적는다(08-31): 옛 칸 이름이 `열린PR전체` 라 **어느 저장소든 PR 로 쟀다고**
     *   읽혔고, talk 런의 `0` 이 「열린 PR 이 0개」로 보였다(실제로는 PR 을 아예 안 쓰는 저장소다).
     *   수는 자와 함께 적는다 — 이름 하나가 분모를 거짓말하게 두지 않는다. */
    아는미완: 미완 ? {
      실은줄: 미완.줄들.length, 전체: 미완.전체,
      출처: 미완.출처 ? 미완.출처.이름 : null,
      ...(미완.오류 ? { 오류: 미완.오류 } : {}),
    } : null,
    // 같은 이유로 **어느 방향 아래서** 봤는지도 남긴다(방향 정본은 유호님 지시로 개정된다)
    방향: 방향지문(),
    // 그리고 **어느 판단 기준 아래서** — 철학 정본은 방향보다 자주 개정된다(하루 세 번 실측)
    철학: 철학지문(),
    // 어느 **변경**이었는지 — 선파악 기능지도·제안·판정이 같은 값을 들고 있어야 계보가 이어진다
    변경: 변경fp,
    범위: 범위들,
    지문: 유효지문(대상),
    요약: 결과.요약 || '',
    지적,
    기능체크: (기체 && 기체.체크) || [],
    학습데이터: (기체 && 기체.학습데이터) || [],
    미확인,
    // 1단계 산문을 그대로 보관한다 — 2단계 구조화가 무엇을 떨어뜨렸는지 나중에 대조할 수 있어야 한다.
    원문: 결과.원문 || '',
  });

  /* 체크포인트는 **장부에 들어간 뒤에야** 버린다 — 순서를 뒤집으면 append 가 실패하는 날
   * 결과가 양쪽 어디에도 없다. 지우는 이유는 다음 판이 낡은 회차를 이어받지 않게 하기 위해서고,
   * 못 지워도 사고는 아니다(방 지문에 대상·모델이 들어 있어 다른 검수와는 이미 갈려 있다). */
  런.방비우기(방경로);

  console.log('\n── 검수 결과 ──');
  /* 회차별 건수를 합집합과 나란히 — 이게 없으면 「2회 돌렸다」가 「2회가 값했다」로 읽힌다. */
  if (결과.회차별) {
    console.log(`회차별 지적: ${결과.회차별.map((r) => `${r.회차}회 ${r.지적수}건`).join(' · ')}` +
      ` → 합집합 ${(결과.지적 || []).length}건` +
      (결과.회차별.every((r) => r.지적수 === (결과.지적 || []).length) ? ' (겹침 100% — 이 변경에선 2회차가 새로 못 잡았다)' : ''));
  }
  console.log(결과.요약 || '(요약 없음)');
  if (기체) {
    console.log('\n── 기능 전수 체크 ──');
    if (!(기체.체크 || []).length) console.log('  (검수자가 체크할 기능을 하나도 못 찾았다 — diff 가 기능 변경이 아닐 때만 정상)');
    for (const c of 기체.체크 || []) {
      const 표 = c.판정 === '정상' ? '✅' : c.판정 === '의심' ? '⚠' : '🔴';
      console.log(`  ${표} ${c.기능}${c.판정 !== '정상' ? ' — ' + String(c.근거 || '').slice(0, 140) : ''}`);
    }
    const 학습 = 학습데이터줄들(기체.학습데이터);
    if (학습.length) {
      console.log('\n── 학습데이터 영향 (알림 — 배포를 막지 않는다) ──');
      for (const l of 학습) console.log(l);
    }
    console.log(미확인 === null
      ? `\n폐루프 대조: 이 변경(${변경fp})엔 선파악 기능지도가 없다 — **대조 안 함**(미확인 0건이 아니다). 먼저 --제안 을 돌린다.`
      : 미확인.length
        ? `\n⚠ 폐루프 대조 — 선파악이 알던 기능 ${미확인.length}건을 최종이 안 짚었다(알림 · 배포 안 막는다):\n` + 미확인.map((n) => '  · ' + n).join('\n')
        : `\n폐루프 대조: 선파악 기능 전건이 최종 체크에 잡혔다 (변경 ${변경fp}).`);
  }
  if (!신규.length) console.log('\n새 지적 0건.');
  for (const f of 신규) {
    console.log(`\n[${f.등급}${f.합의 ? ` · 합의 ${f.합의}` : ''}] ${f.파일}${f.라인 ? ':' + f.라인 : ''} — ${f.제목}`);
    console.log(`  근거: ${f.근거}`);
    console.log(`  수정: ${f.수정방향}`);
    console.log(`  키: ${f.키}   (틀린 지적이면: node tools/codex-review.js --기각 ${f.키} --사유 "...")`);
  }
  const 차단 = 신규.filter((f) => 차단급.has(f.등급));
  if (지적.length !== 신규.length) console.log(`\n(기각 이력으로 걸러낸 재발 지적 ${지적.length - 신규.length}건)`);
  console.log(`\n기록: docs/_ops/검수기록.jsonl`);
  return 차단.length ? 1 : 0;
}

module.exports = {
  게이트판정, 유효지문, 배포변경있나, 키, 범위, 대상결정, 미커밋파일들, 차단급, 기록경로, 기각경로, 모델설정, 효력들, 모델플래그, 잠금플래그, 외부도구들,
  실패요점, 범위밖정지, 범위밖탈출, 과녁커밋, 과녁판정, git버퍼, 버퍼초과,
  머지기준, 커밋읽기, 커밋파일들, 과녁이열리나,   // F578 — 회귀가 「두 축이 같은 기준인가」를 출력으로 잰다
  진행파일, 진행시작, 진행종료, 낡은진행, 진행경고줄, 소요안내,
  값플래그, 홑플래그, 아는플래그, 한도무시플래그,
  등급갈림,   // 🔍 2단계 «변환»이 판단을 섞었나(09-04) — 회귀가 이 순수 함수를 직접 문다
  // 대상 저장소 — 회귀가 「집과 재는 것이 갈렸나」·「장부가 저장소로 갈리나」를 출력으로 잰다
  저장소플래그, 저장소이름, 저장소열기, 저장소잡기, 타저장소, 클라스프프로젝트들,
  저장소스탬프, 이저장소표, 행저장소, 장부읽기, 대상저장소: () => 대상ROOT,
  처분레버들, 처분of, 레버of, 걸러지는키들, 게이트해소키들, 과녁이배포집합밖, 이전처분줄들,
  // 무효 표식(09-03) — 회귀가 「표식이 붙은 행은 도장으로 안 세나」를 출력으로 잰다
  검수행인가, 무효행들,
  제안경로, 제안키, 제안현황, 제안프롬프트, 선파악행들, 기능체크프롬프트, 기능체크지적들, 채택제안줄들, 방향텍스트, 방향지문, 방향경로, 방향상한, 디프상한,
  아는미완줄들, 아는미완블록, 기능렌즈, 기능렌즈들,
  // 재료가 저장소마다 갈리는 자리 — 회귀가 「출처 없음 ≠ 0건」을 출력으로 잰다(08-31)
  아는미완출처, 아는미완출처들,
  철학텍스트, 철학지문, 철학경로, 철학상한, 철학블록, 철학카드경로,
  변경지문, 선파악지도, 미확인기능들, 학습데이터줄들, 기능체크병합, 회차병합,
  심문프롬프트, 금지목록, 금지지문, 심문템플릿, 심문경로, 심문결과경로, 심문던짐적기, 완료행인가, 심문행키,
  던짐지문읽기,
  심문형식통과, 심문결과읽기,
  검수방, 단계끝났나, 아는단계, 완료칸, 회차실행플래그, 직렬플래그, 던지기플래그, 런현황,
  // 벤더 편성(09-02) — 회귀가 「편성·거절·합의 분모」를 출력으로 잰다 · `codex` 는 밖의사실.js 의 라이브 검색 반박이 빌린다
  codex, 검수한회, 벤더편성, 벤더모드, 벤더플래그, 아는벤더모드, gemini프롬프트, 검수규칙읽기, 병렬계획,
  병렬계획, 입력쓰기, 회차별줄,
  자식옵션, 창숨김누락,
  사유_파일어긋남,
};

if (require.main === module) {
  /* 던져진 런이면 **자기 끝을 자기가 적는다.**
   * 🔑 밖에서 죽으면(kill·재부팅·세션 정리) 이 자리가 안 돌아 상태가 `진행` 으로 남고,
   *   `검수런.판정` 이 pid 부재를 보고 **멈춤**으로 읽는다 — 그게 정확히 원하는 판별이다.
   *   「완주」를 여기서만 적는 이유가 그거다: 적히지 않은 것은 안 끝난 것이다. */
  const 런ID = process.env.SYNK_REVIEW_RUN_ID;
  const 마감 = (코드) => {
    if (!런ID) return;
    /* 두 번째 벽 — 회차 자식은 **자기 끝을 부모 런에 적지 않는다**(F352).
     * `자식환경()` 이 런ID 를 지우므로 정상 경로에선 여기 안 걸린다. 그런데 등록층은 언제나
     * 「통과」 방향으로 새므로(새 spawn 자리가 `...process.env` 를 펼치는 날) 벽을 두 개 세운다.
     * 실측 08-12: 손자 하나가 부모 런을 「진행」→「실패」로 덮는 것을 격리 픽스처로 재현했다. */
    if (런.자식인가()) return;
    /* 생산자 키를 준다 — 이 도구의 1 은 「차단 지적을 찾았다」이지 실패가 아니다(F561).
     * 안 줘도 `판정()` 이 다시 판독하므로 사고는 아니지만, 장부 라벨까지 정직해야
     * JSON 을 직접 여는 사람이 안 속는다. */
    try { 런.런갱신(런ID, { 상태: 런.상태이름(코드, 'codex'), 끝: new Date().toISOString(), 종료코드: 코드 }); }
    catch (_) { /* 상태를 못 적어도 결과는 장부에 있다 — 여기서 더 죽이지 않는다 */ }
  };
  try {
    const 코드 = main(process.argv.slice(2));
    마감(코드);
    process.exit(코드);
  } catch (e) {
    마감(2);
    /* 확인 불가는 **통과가 아니다** — 그 말을 여기서도 붙인다. 종료코드 2 는 파이프를 한 번
     * 끼우면 사라지므로(F308 ①), 본문 문구가 마지막 방어선이다. */
    const 앞 = e && e.확인불가 ? '🔴 확인 불가 — 검수가 **안 돌았다**(통과가 아니다): ' : '🔴 ';
    console.error(앞 + String((e && e.message) || e));
    process.exit(2);
  }
}
